/* data/maulid/syarafil-anam.js - Maulid Syarafil Anam (Arab, transliterasi, terjemah). Dibuat oleh template-kitab/maulid_dari_md.py.
   Satu bait = {no, ar, lt, id}. Boleh diedit langsung. */
registerMaulid({"id": "syarafil-anam", "judul": "Maulid Syarafil Anam", "sumber": "Disalin dari PDF Majmu'ah Maulid Syarafil Anam; transliterasi & terjemah disusun ulang - mohon ditashih.",bagian:[
{judul:"Pembuka: Assalamu 'Alaik",isi:[
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 1},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ زَيْنَ الْأَنْبِيَاءِ", "lt": "As-salâmu ‘alaika ۞ zainal-anbiyâ'i", "id": "Salam sejahtera untukmu, wahai perhiasan para nabi.", "no": 2},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ أَتْقَى الْأَتْقِيَاءِ", "lt": "As-salâmu ‘alaika ۞ atqal-atqiyâ'i", "id": "Salam sejahtera untukmu, wahai yang paling bertakwa di antara orang-orang bertakwa.", "no": 3},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ أَصْفَى الْأَصْفِيَاءِ", "lt": "As-salâmu ‘alaika ۞ ashfal-ashfiyâ'i", "id": "Salam sejahtera untukmu, wahai yang paling suci di antara orang-orang suci.", "no": 4},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ أَزْكَى الْأَزْكِيَاءِ", "lt": "As-salâmu ‘alaika ۞ azkal-azkiyâ'i", "id": "Salam sejahtera untukmu, wahai yang paling bersih di antara orang-orang yang bersih.", "no": 5},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ مِنْ رَبِّ السَّمَاءِ", "lt": "As-salâmu ‘alaika ۞ min rabbis-samâ'i", "id": "Salam sejahtera untukmu dari Tuhan pemilik langit.", "no": 6},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ دَائِمًا بِلَا انْقِضَاءِ", "lt": "As-salâmu ‘alaika ۞ dâ'iman bilan-qidlâ'i", "id": "Salam sejahtera untukmu, selamanya tanpa berkesudahan.", "no": 7},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ أَحْمَدُ يَا حَبِيْبِيْ", "lt": "As-salâmu ‘alaika ۞ aḥmadu yâ ḥabîbî", "id": "Salam sejahtera untukmu, wahai Ahmad, wahai kekasihku.", "no": 8},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ طٰهٰ يَا طَبِيْبِيْ", "lt": "As-salâmu ‘alaika ۞ ṭâhâ yâ ṭabîbî", "id": "Salam sejahtera untukmu, wahai Thaha, wahai penyembuh (hati)ku.", "no": 9},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا مِسْكٌ وَطِيْبُ", "lt": "As-salâmu ‘alaika ۞ yâ miskun wa ṭîbu", "id": "Salam sejahtera untukmu, wahai (yang harum bagai) kesturi dan wewangian.", "no": 10},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا مَاحِيَ الذُّنُوْبِ", "lt": "As-salâmu ‘alaika ۞ yâ mâḥiyadz-dzunûbi", "id": "Salam sejahtera untukmu, wahai penghapus dosa-dosa (dengan syafaatmu).", "no": 11},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا عَوْنَ الْغَرِيْبِ", "lt": "As-salâmu ‘alaika ۞ yâ ‘aunal-gharîbi", "id": "Salam sejahtera untukmu, wahai penolong orang yang terasing.", "no": 12},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ أَحْمَدُ يَا مُحَمَّدُ", "lt": "As-salâmu ‘alaika ۞ aḥmadu yâ muḥammadu", "id": "Salam sejahtera untukmu, wahai Ahmad, wahai Muhammad.", "no": 13},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ طٰهٰ يَا مُمَجَّدُ", "lt": "As-salâmu ‘alaika ۞ ṭâhâ yâ mumajjadu", "id": "Salam sejahtera untukmu, wahai Thaha, wahai yang diagungkan.", "no": 14},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا كَهْفًا وَمَقْصَدُ", "lt": "As-salâmu ‘alaika ۞ yâ kahfan wa maqshadu", "id": "Salam sejahtera untukmu, wahai tempat berlindung dan tempat yang dituju.", "no": 15},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا حُسْنًا تَفَرَّدْ", "lt": "As-salâmu ‘alaika ۞ yâ ḥusnan tafarrad", "id": "Salam sejahtera untukmu, wahai yang tiada tandingan keindahannya.", "no": 16},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا جَالِيَ الْكُرُوْبِ", "lt": "As-salâmu ‘alaika ۞ yâ jâliyal-kurûbi", "id": "Salam sejahtera untukmu, wahai penghilang segala kesusahan.", "no": 17},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا خَيْرَ الْأَنَامِ", "lt": "As-salâmu ‘alaika ۞ yâ khairal-anâmi", "id": "Salam sejahtera untukmu, wahai sebaik-baik makhluk.", "no": 18},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا بَدْرَ التَّمَامِ", "lt": "As-salâmu ‘alaika ۞ yâ badrat-tamâmi", "id": "Salam sejahtera untukmu, wahai purnama yang sempurna.", "no": 19},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا نُوْرَ الظَّلَامِ", "lt": "As-salâmu ‘alaika ۞ yâ nûradh-dhalâmi", "id": "Salam sejahtera untukmu, wahai cahaya di tengah kegelapan.", "no": 20},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا كُلَّ الْمَرَامِ", "lt": "As-salâmu ‘alaika ۞ yâ kullal-marâmi", "id": "Salam sejahtera untukmu, wahai segala tujuan (kami).", "no": 21},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا ذَا الْمُعْجِزَاتِ", "lt": "As-salâmu ‘alaika ۞ yâ dzal-mu‘jizâti", "id": "Salam sejahtera untukmu, wahai pemilik berbagai mukjizat.", "no": 22},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا ذَا الْبَيِّنَاتِ", "lt": "As-salâmu ‘alaika ۞ yâ dzal-bayyinâti", "id": "Salam sejahtera untukmu, wahai pemilik bukti-bukti yang nyata.", "no": 23},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا هَادِيَ الْهُدَاةِ", "lt": "As-salâmu ‘alaika ۞ yâ hâdiyal-hudâti", "id": "Salam sejahtera untukmu, wahai pemimpin para pemberi petunjuk.", "no": 24},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا ذُخْرَ الْعُصَاةِ", "lt": "As-salâmu ‘alaika ۞ yâ dzukhral-‘ushâti", "id": "Salam sejahtera untukmu, wahai simpanan (harapan) para pendosa.", "no": 25},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا حُسْنَ الصِّفَاتِ", "lt": "As-salâmu ‘alaika ۞ yâ ḥusnash-shifâti", "id": "Salam sejahtera untukmu, wahai yang indah sifat-sifatnya.", "no": 26},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا ذَا الْمَوْهِبَاتِ", "lt": "As-salâmu ‘alaika ۞ yâ dzal-mauhibâti", "id": "Salam sejahtera untukmu, wahai pemilik berbagai anugerah.", "no": 27},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا رُكْنَ الصَّلَاحِ", "lt": "As-salâmu ‘alaika ۞ yâ ruknash-shalâḥi", "id": "Salam sejahtera untukmu, wahai pilar kebaikan.", "no": 28},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا رَبَّ السَّمَاحِ", "lt": "As-salâmu ‘alaika ۞ yâ rabbas-samâḥi", "id": "Salam sejahtera untukmu, wahai pemilik kemurahan hati.", "no": 29},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا زَيْنَ الْمِلَاحِ", "lt": "As-salâmu ‘alaika ۞ yâ zainal-milâḥi", "id": "Salam sejahtera untukmu, wahai perhiasan orang-orang yang rupawan.", "no": 30},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا دَاعِيَ الْفَلَاحِ", "lt": "As-salâmu ‘alaika ۞ yâ dâ‘iyal-falâḥi", "id": "Salam sejahtera untukmu, wahai penyeru kepada keberuntungan.", "no": 31},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا نُوْرَ الصَّبَاحِ", "lt": "As-salâmu ‘alaika ۞ yâ nûrash-shabâḥi", "id": "Salam sejahtera untukmu, wahai cahaya pagi.", "no": 32},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا حَيَّ الْفَلَاحِ", "lt": "As-salâmu ‘alaika ۞ yâ ḥayyal-falâḥi", "id": "Salam sejahtera untukmu, wahai (penyeru) \"marilah menuju kemenangan\".", "no": 33},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا ضَوْءَ الْبَصَائِرِ", "lt": "As-salâmu ‘alaika ۞ yâ dlau'al-bashâ'iri", "id": "Salam sejahtera untukmu, wahai cahaya mata hati.", "no": 34},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا عَالِيَ الْمَفَاخِرِ", "lt": "As-salâmu ‘alaika ۞ yâ ‘âliyal-mafâkhiri", "id": "Salam sejahtera untukmu, wahai yang tinggi kemuliaannya.", "no": 35},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا بَحْرَ الذَّخَائِرِ", "lt": "As-salâmu ‘alaika ۞ yâ baḥradz-dzakhâ'iri", "id": "Salam sejahtera untukmu, wahai lautan perbendaharaan.", "no": 36},
{"ar": "اَلسَّلَامُ عَلَى ۞ الْمُقَدَّمِ لِلْإِمَامَةِ", "lt": "As-salâmu ‘alâ ۞ al-muqaddami lil-imâmah", "id": "Salam sejahtera atas (Nabi) yang didahulukan menjadi imam.", "no": 37},
{"ar": "اَلسَّلَامُ عَلَى ۞ الْمُشَفَّعِ فِي الْقِيَامَةِ", "lt": "As-salâmu ‘alâ ۞ al-musyaffa‘i fil-qiyâmah", "id": "Salam sejahtera atas (Nabi) yang diterima syafaatnya pada hari kiamat.", "no": 38},
{"ar": "اَلسَّلَامُ عَلَى ۞ الْمُظَلَّلِ بِالْغَمَامَةِ", "lt": "As-salâmu ‘alâ ۞ al-mudhallali bil-ghamâmah", "id": "Salam sejahtera atas (Nabi) yang dinaungi awan.", "no": 39},
{"ar": "اَلسَّلَامُ عَلَى ۞ الْمُتَوَّجِ بِالْكَرَامَةِ", "lt": "As-salâmu ‘alâ ۞ al-mutawwaji bil-karâmah", "id": "Salam sejahtera atas (Nabi) yang dimahkotai dengan kemuliaan.", "no": 40},
{"ar": "اَلسَّلَامُ عَلَى ۞ الْخُلَاصَةِ مِنْ تِهَامَةِ", "lt": "As-salâmu ‘alâ ۞ al-khulâshati min tihâmah", "id": "Salam sejahtera atas (manusia) pilihan dari Tihamah.", "no": 41},
{"ar": "اَلسَّلَامُ عَلَى ۞ الْمُبَشِّرِ بِالسَّلَامَةِ", "lt": "As-salâmu ‘alâ ۞ al-mubasysyiri bis-salâmah", "id": "Salam sejahtera atas (Nabi) yang membawa kabar gembira keselamatan.", "no": 42},
{"ar": "اَلسَّلَامُ عَلَى ۞ مُحَمَّدٍ الرَّسُوْلِ", "lt": "As-salâmu ‘alâ ۞ muḥammadinir-rasûli", "id": "Salam sejahtera atas Muhammad sang Rasul.", "no": 43},
{"ar": "اَلسَّلَامُ عَلَى ۞ النَّبِيِّ أَبِي الْبَتُوْلِ", "lt": "As-salâmu ‘alâ ۞ an-nabiyyi abil-batûli", "id": "Salam sejahtera atas Nabi, ayah Fathimah Al-Batul.", "no": 44},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ يَا وَجْهَ الْجَمِيْلِ", "lt": "As-salâmu ‘alaika ۞ yâ wajhal-jamîli", "id": "Salam sejahtera untukmu, wahai yang berwajah indah.", "no": 45},
{"ar": "اَلسَّلَامُ عَلَيْكَ ۞ الْخَلِيْفَةِ مِنْكَ فِيْنَا ۞ أَبِيْ بَكْرٍ مُبِيْدِ الْجَاحِدِيْنَا", "lt": "As-salâmu ‘alaika, al-khalîfati minka fînâ ۞ abî bakrin mubîdil-jâḥidînâ", "id": "Salam sejahtera atas khalifahmu di tengah kami, Abu Bakar, pembasmi orang-orang yang ingkar.", "no": 46},
{"ar": "وَكَذَا عُمَرُ ۞ وَلِيُّ الصَّالِحِيْنَا", "lt": "Wa kadzâ ‘umaru ۞ waliyyush-shâliḥînâ", "id": "Demikian pula (salam atas) Umar, pemimpin orang-orang saleh.", "no": 47},
{"ar": "وَذِي النُّوْرَيْنِ ۞ رَأْسِ النَّاسِكِيْنَا", "lt": "Wa dzin-nûraini ۞ ra'sin-nâsikînâ", "id": "Dan (atas) Dzun Nurain (Utsman), pemuka para ahli ibadah.", "no": 48},
{"ar": "وَكَذَاكَ عَلِيٌّ ۞ السَّامِيْ يَقِيْنَا", "lt": "Wa kadzâka ‘aliyyun ۞ as-sâmî yaqînâ", "id": "Demikian pula Ali, yang tinggi keyakinannya.", "no": 49},
{"ar": "اَلسَّلَامُ عَلَى ۞ أَصْحَابِكَ أَجْمَعِيْنَا", "lt": "As-salâmu ‘alâ ۞ ash-ḥâbika ajma‘înâ", "id": "Salam sejahtera atas seluruh sahabatmu.", "no": 50},
{"ar": "وَكَذَا الْحَسَنَيْنِ ۞ خَيْرِ الْعَالَمِيْنَ", "lt": "Wa kadzal-ḥasanaini ۞ khairil-‘âlamîna", "id": "Demikian pula Hasan dan Husain, sebaik-baik (pemuda) di alam semesta.", "no": 51},
{"ar": "وَآلِكَ كُلِّهِمْ وَالتَّابِعِيْنَا ۞ وَتَابِعِهِمْ وَتَابِعِ التَّابِعِيْنَا", "lt": "Wa âlika kullihim wat-tâbi‘înâ ۞ wa tâbi‘ihim wa tâbi‘it-tâbi‘înâ", "id": "Dan atas seluruh keluargamu, para tabi'in, pengikut mereka, dan pengikut tabi'in.", "no": 52}]},
{judul:"Khairu Man Wathi'ats-Tsara",isi:[
{"ar": "اَلصَّلَاةُ عَلَى النَّبِيِّ ۞ وَالسَّلَامُ عَلَى الرَّسُوْلِ ۞ الشَّفِيْعِ الْأَبْطَحِيِّ ۞ وَمُحَمَّدٍ عَرَبِيِّ", "lt": "Ash-shalâtu ‘alan-nabiyyi ۞ was-salâmu ‘alar-rasûli ۞ asy-syafî‘il-abṭaḥiyyi ۞ wa muḥammadin ‘arabiyyi", "id": "Shalawat atas Nabi dan salam atas Rasul, pemberi syafaat dari lembah Makkah, Muhammad, orang Arab (pilihan).", "no": 1},
{"ar": "خَيْرُ مَنْ وَطِيَ الثَّرَى الْمُشَفَّعُ فِي الْوَرَى ۞ مَنْ بِهِ حُلَّتْ عُرَى كُلِّ عَبْدٍ مُذْنِبِ", "lt": "Khairu man waṭiyats-tsarâl-musyaffa‘u fil-warâ ۞ man bihî ḥullat ‘urâ kulli ‘abdin mudznibi", "id": "Sebaik-baik orang yang menginjak bumi, yang diterima syafaatnya bagi makhluk; dengannya terlepas ikatan (dosa) setiap hamba yang berdosa.", "no": 2},
{"ar": "مَا لَهُ مِنْ مُشْبِهٍ فَازَ أُمَّتُهُ بِهِ ۞ مَنْ يَمُتْ فِيْ حُبِّهِ نَالَ كُلَّ الْمَطْلَبِ", "lt": "Mâ lahû min musybihin fâza ummatuhû bihî ۞ man yamut fî ḥubbihî nâla kullal-maṭlabi", "id": "Tiada yang menyerupainya; umatnya beruntung karenanya. Siapa yang mati dalam mencintainya, ia meraih segala yang dicari.", "no": 3},
{"ar": "أَنَا مَفْتُوْنٌ بِهِ طَامِعٌ فِيْ قُرْبِهِ ۞ رَبِّ عَجِّلْ لِيْ بِهِ لَعَلَّ يَصْفُوْ مَشْرَبِيْ", "lt": "Ana maftûnun bihî ṭâmi‘un fî qurbihî ۞ rabbi ‘ajjil lî bihî la‘alla yashfû masyrabî", "id": "Aku terpesona olehnya dan mendambakan kedekatan dengannya. Wahai Tuhanku, segerakanlah (pertemuan) dengannya, semoga jernih tempat minumku.", "no": 4},
{"ar": "كَمْ شَفَا مِنْ مُقْسِمٍ كَمْ جَلَا مِنْ أَظْلَمِ ۞ كَمْ لَهُ مِنْ أَنْعُمٍ لِلْفَطِيْنِ وَلِلْغَبِيْ", "lt": "Kam syafâ min muqsimin kam jalâ min adhlami ۞ kam lahû min an‘umin lil-faṭîni wa lil-ghabî", "id": "Betapa banyak (penderitaan) yang ia sembuhkan, betapa banyak kegelapan yang ia terangi, betapa banyak nikmatnya bagi orang yang cerdas maupun yang bodoh.", "no": 5},
{"ar": "كَمْ لَهُ مِنْ مُكْرَمَاتٍ كَمْ عَطَايَا وَافِرَاتٍ ۞ كَمْ رَوَتْ عَنْهُ الثِّقَاتُ كُلُّ عِلْمٍ وَاجِبِ", "lt": "Kam lahû min mukramâtin kam ‘aṭâyâ wâfirâtin ۞ kam rawat ‘anhuts-tsiqâtu kullu ‘ilmin wâjibi", "id": "Betapa banyak kemuliaannya, betapa banyak pemberiannya yang melimpah, dan betapa banyak ilmu wajib yang diriwayatkan para perawi terpercaya darinya.", "no": 6},
{"ar": "نِعْمَ ذَاكَ الْمُصْطَفَى ذُو الْمُرُوْءَةِ وَالْوَفَا ۞ فَضْلُ أَحْمَدَ مَا خَفَى شَرْقَهَا وَالْمَغْرِبِ", "lt": "Ni‘ma dzâkal-mushṭafâ dzul-murû'ati wal-wafâ ۞ fadllu aḥmada mâ khafâ syarqahâ wal-maghribi", "id": "Alangkah baiknya (Nabi) pilihan itu, pemilik kehormatan dan kesetiaan; keutamaan Ahmad tidaklah tersembunyi di timur maupun di barat.", "no": 7},
{"ar": "كَمْ بِهِ مِنْ مُوْلَعٍ غَارِقٍ فِي الْأَدْمُعِ ۞ عَقْلُهُ لَمَّا دُعِيْ فِيْ مَحَبَّتِهِ سُبِيْ", "lt": "Kam bihî min mûla‘in ghâriqin fil-admu‘i ۞ ‘aqluhû lammâ du‘î fî maḥabbatihî subî", "id": "Betapa banyak orang yang tergila-gila kepadanya, tenggelam dalam air mata; akalnya tertawan oleh cintanya ketika ia dipanggil.", "no": 8},
{"ar": "يَا رَسُوْلَ اللهِ يَا خَيْرَ كُلِّ الْأَنْبِيَاءِ ۞ نَجِّنَا مِنْ هَاوِيَةْ يَا زَكِيَّ الْمَنْصِبِ", "lt": "Yâ rasûlallâhi yâ khaira kullil-anbiyâ'i ۞ najjinâ min hâwiyah yâ zakiyyal-manshibi", "id": "Wahai Rasulullah, wahai sebaik-baik seluruh nabi, selamatkanlah kami (dengan syafaatmu) dari neraka Hawiyah, wahai yang suci kedudukannya.", "no": 9},
{"ar": "وَعَلَى عَلَمِ الْهُدَى أَحْمَدَ مُفْنِي الْعِدَى ۞ جُدْ بِتَسْلِيْمٍ بَدَا لِلنَّبِيِّ الْيَثْرِبِيْ", "lt": "Wa ‘alâ ‘alamil-hudâ aḥmada mufnil-‘idâ ۞ jud bitaslîmin badâ lin-nabiyyil-yatsribî", "id": "Dan atas panji petunjuk, Ahmad, pembinasa musuh, limpahkanlah salam yang tampak bagi Nabi dari Yatsrib (Madinah).", "no": 10},
{"ar": "وَعَلَيْهِ فَسَلِّمَا مَاسَ غُصْنٌ فِي الْحِمَى ۞ أَوْ بَدَا بَدْرُ السَّمَا فِيْ بَهِيْمِ الْغَيْهَبِ", "lt": "Wa ‘alaihi fasallimâ mâsa ghushnun fil-ḥimâ ۞ au badâ badrus-samâ fî bahîmil-ghaihabi", "id": "Ucapkanlah salam kepadanya selama dahan bergoyang di tanah haram, atau purnama tampak di langit dalam pekatnya malam.", "no": 11},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 12}]},
{judul:"Pembukaan: Ayat-ayat Al-Qur'an",isi:[
{"ar": "بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ", "lt": "Bismillâhir-raḥmânir-raḥîm", "id": "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang.", "no": 1},
{"ar": "إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِيْنًا ۞ لِّيَغْفِرَ لَكَ اللهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُ عَلَيْكَ وَيَهْدِيَكَ صِرَاطًا مُّسْتَقِيْمًا ۞ وَيَنْصُرَكَ اللهُ نَصْرًا عَزِيْزًا", "lt": "Innâ fataḥnâ laka fatḥam mubînâ ۞ liyaghfira lakallâhu mâ taqaddama min dzanbika wa mâ ta'akhkhara wa yutimma ni‘matahû ‘alaika wa yahdiyaka shirâṭam mustaqîmâ ۞ wa yanshurakallâhu nashran ‘azîzâ", "id": "Sungguh Kami telah memberikan kepadamu kemenangan yang nyata, agar Allah mengampuni dosamu yang lalu dan yang akan datang, menyempurnakan nikmat-Nya atasmu, menunjukimu ke jalan yang lurus, dan agar Allah menolongmu dengan pertolongan yang perkasa. (QS. Al-Fath: 1-3)", "no": 2},
{"ar": "لَقَدْ جَاءَكُمْ رَسُوْلٌ مِّنْ أَنْفُسِكُمْ عَزِيْزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيْصٌ عَلَيْكُمْ بِالْمُؤْمِنِيْنَ رَءُوْفٌ رَّحِيْمٌ ۞ فَإِنْ تَوَلَّوْا فَقُلْ حَسْبِيَ اللهُ لَا إِلٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ", "lt": "Laqad jâ'akum rasûlum min anfusikum ‘azîzun ‘alaihi mâ ‘anittum ḥarîshun ‘alaikum bil-mu'minîna ra'ûfur raḥîm ۞ fa in tawallau faqul ḥasbiyallâhu lâ ilâha illâ huwa ‘alaihi tawakkaltu wa huwa rabbul-‘arsyil-‘adhîm", "id": "Sungguh telah datang kepadamu seorang rasul dari kaummu sendiri; berat terasa olehnya penderitaanmu, ia sangat menginginkan (keimanan dan keselamatan) bagimu, amat belas kasih lagi penyayang terhadap orang-orang mukmin. Jika mereka berpaling, katakanlah: Cukuplah Allah bagiku, tiada tuhan selain Dia; hanya kepada-Nya aku bertawakal, dan Dia adalah Tuhan pemilik Arasy yang agung. (QS. At-Taubah: 128-129)", "no": 3},
{"ar": "صَدَقَ اللهُ الْعَلِيُّ الْعَظِيْمُ ۞ وَبَلَّغَ رَسُوْلُهُ الْحَبِيْبُ الْكَرِيْمُ ۞ وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ", "lt": "Shadaqallâhul-‘aliyyul-‘adhîm ۞ wa ballagha rasûluhul-ḥabîbul-karîm ۞ wal-ḥamdu lillâhi rabbil-‘âlamîn", "id": "Mahabenar Allah Yang Mahatinggi lagi Mahaagung, dan Rasul-Nya, kekasih yang mulia, telah menyampaikan(nya); segala puji bagi Allah, Tuhan semesta alam.", "no": 4},
{"ar": "إِنَّ اللهَ وَمَلَائِكَتَهُ يُصَلُّوْنَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِيْنَ آمَنُوْا صَلُّوْا عَلَيْهِ وَسَلِّمُوْا تَسْلِيْمًا ۞ وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ", "lt": "Innallâha wa malâ'ikatahû yushallûna ‘alan-nabiyy, yâ ayyuhal-ladzîna âmanû shallû ‘alaihi wa sallimû taslîmâ ۞ wal-ḥamdu lillâhi rabbil-‘âlamîn", "id": "Sesungguhnya Allah dan para malaikat-Nya bershalawat untuk Nabi. Wahai orang-orang yang beriman, bershalawatlah kamu untuknya dan ucapkanlah salam dengan penuh penghormatan. (QS. Al-Ahzab: 56) Segala puji bagi Allah, Tuhan semesta alam.", "no": 5}]},
{judul:"Al-Hamdu Lillahil Ladzi Syarrafal Anam",isi:[
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 1},
{"ar": "بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ", "lt": "Bismillâhir-raḥmânir-raḥîm", "id": "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang.", "no": 2},
{"ar": "اَلْحَمْدُ لِلّٰهِ الَّذِيْ شَرَّفَ الْأَنَامَ بِصَاحِبِ الْمَقَامِ الْأَعْلَى، وَكَمَّلَ السُّعُوْدَ بِأَكْرَمِ مَوْلُوْدٍ حَوَى شَرَفًا وَفَضْلًا", "lt": "Al-ḥamdu lillâhil-ladzî syarrafal-anâma bishâḥibil-maqâmil-a‘lâ, wa kammalas-su‘ûda bi'akrami maulûdin ḥawâ syarafan wa fadllâ", "id": "Segala puji bagi Allah yang memuliakan umat manusia dengan (Nabi) pemilik kedudukan tertinggi, dan menyempurnakan kebahagiaan dengan kelahiran bayi paling mulia yang menghimpun kemuliaan dan keutamaan.", "no": 3},
{"ar": "وَشَرَّفَ بِهِ الْآبَاءَ وَالْجُدُوْدَ، وَمَلَأَ الْوُجُوْدَ بِجُوْدِهِ عَدْلًا", "lt": "Wa syarrafa bihil-âbâ'a wal-judûd, wa mala'al-wujûda bijûdihî ‘adlâ", "id": "Dengannya Allah memuliakan para ayah dan kakek (leluhur)nya, dan memenuhi alam semesta dengan keadilan melalui kemurahannya.", "no": 4},
{"ar": "حَمَلَتْهُ أُمُّهُ آمِنَةُ فَلَمْ تَجِدْ لِحَمْلِهِ أَلَمًا وَلَا ثِقْلًا", "lt": "Ḥamalat-hu ummuhû âminatu falam tajid liḥamlihî alaman wa lâ tsiqlâ", "id": "Ibunya, Aminah, mengandungnya tanpa merasakan sakit dan berat karena kandungannya.", "no": 5},
{"ar": "وَوَضَعَتْهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَخْتُوْنًا مُكَحَّلًا، فِيْ خِلَعِ الْوَقَارِ وَالْمَهَابَةِ يُجْلَى", "lt": "Wa wadla‘at-hu shallallâhu ‘alaihi wa sallama makhtûnan mukaḥḥalâ, fî khila‘il-waqâri wal-mahâbati yujlâ", "id": "Ia melahirkannya ﷺ dalam keadaan telah dikhitan dan bercelak, tampil dalam busana kewibawaan dan keagungan.", "no": 6},
{"ar": "وَوُلِدَ نَبِيُّنَا مُحَمَّدٌ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِوَجْهٍ مَا يُرَى أَحْسَنُ مِنْهُ وَلَا أَحْلَى، بِنُوْرٍ كَالشَّمْسِ بَلْ هُوَ أَضْوَأُ وَأَجْلَى", "lt": "Wa wulida nabiyyunâ muḥammadun shallallâhu ‘alaihi wa sallama biwajhin mâ yurâ aḥsanu minhu wa lâ aḥlâ, binûrin kasy-syamsi bal huwa adlwa'u wa ajlâ", "id": "Nabi kita Muhammad ﷺ lahir dengan wajah yang tiada terlihat yang lebih tampan dan manis daripadanya, dengan cahaya bagaikan matahari, bahkan lebih terang dan jelas.", "no": 7},
{"ar": "وَثَغْرٍ فَاقَ دُرًّا وَلُؤْلُؤًا بَلْ هُوَ أَعْلَى وَأَغْلَى، وَطَافَ بِهِ لَيْلَةَ الْإِسْرَاءِ وَتَمَلَّى", "lt": "Wa tsaghrin fâqa durran wa lu'lu'an bal huwa a‘lâ wa aghlâ, wa ṭâfa bihî lailatal-isrâ'i wa tamallâ", "id": "(Dengan) gigi yang mengungguli mutiara dan permata, bahkan lebih tinggi dan lebih berharga. Ia berkeliling pada malam Isra' dan menikmati (pemandangan alam malakut).", "no": 8},
{"ar": "وَجَعَلَ دِيْنَهُ عَلَى الدَّوَامِ مُسْتَعْلِيًا لَا مُسْتَعْلًى، وَذِكْرَهُ عَلَى مَمَرِّ الْأَيَّامِ يُكَرَّرُ وَيُتْلَى", "lt": "Wa ja‘ala dînahû ‘alad-dawâmi musta‘liyan lâ musta‘lâ, wa dzikrahû ‘alâ mamarril-ayyâmi yukarraru wa yutlâ", "id": "Allah menjadikan agamanya selamanya unggul dan tidak terungguli, dan menjadikan sebutannya terus diulang dan dibaca sepanjang masa.", "no": 9},
{"ar": "أَشْرَقَتْ لِمَوْلِدِهِ الْحَنَادِسُ شَرْقًا وَغَرْبًا وَوَعْرًا وَسَهْلًا، وَخَرَّتْ لِمَوْلِدِهِ الْأَصْنَامُ مِنْ أَعْلَى الْمَجَالِسِ خُضُوْعًا وَذُلًّا", "lt": "Asyraqat limaulidihil-ḥanâdisu syarqan wa gharban wa wa‘ran wa sahlâ, wa kharrat limaulidihil-ashnâmu min a‘lal-majâlisi khudlû‘an wa dzullâ", "id": "Karena kelahirannya, kegelapan menjadi terang di timur dan barat, di tanah yang sulit maupun yang mudah; berhala-berhala tersungkur dari tempat-tempat tertinggi dalam keadaan tunduk dan hina.", "no": 10},
{"ar": "وَارْتَجَّ إِيْوَانُ كِسْرَى وَهُوَ جَالِسٌ فَعَدِمَ الْقَوْمُ نُطْقًا وَعَقْلًا، وَخَمَدَتْ نَارُ فَارِسَ وَتَبَدَّدَ مِنْهُمْ جَمْعًا وَشَمْلًا", "lt": "Wartajja îwânu kisrâ wa huwa jâlisun fa‘adimal-qaumu nuṭqan wa ‘aqlâ, wa khamadat nâru fârisa wa tabaddada minhum jam‘an wa syamlâ", "id": "Istana Kisra berguncang ketika ia sedang duduk di dalamnya, hingga kaumnya kehilangan kata-kata dan akal; api Persia padam, dan persatuan mereka pun tercerai-berai.", "no": 11},
{"ar": "وَزُخْرِفَتِ الْجِنَانُ لَيْلَةَ مَوْلِدِهِ وَاطَّلَعَ الْحَقُّ وَتَجَلَّى، وَنَادَتِ الْكَائِنَاتُ مِنْ جَمِيْعِ الْجِهَاتِ أَهْلًا وَسَهْلًا، ثُمَّ أَهْلًا وَسَهْلًا، أَلْفَ صَلُّوْا عَلَى النَّبِيِّ خَاتِمِ الرُّسُلِ الْكِرَامِ", "lt": "Wa zukhrifatil-jinânu lailata maulidihî waṭṭala‘al-ḥaqqu wa tajallâ, wa nâdatil-kâ'inâtu min jamî‘il-jihâti ahlan wa sahlâ, tsumma ahlan wa sahlâ, alfa shallû ‘alan-nabiyyi khâtimir-rusulil-kirâm", "id": "Surga dihiasi pada malam kelahirannya, kebenaran pun tampak dan bersinar; seluruh makhluk dari segala penjuru berseru: Selamat datang, sekali lagi selamat datang! Bershalawatlah seribu kali kepada Nabi, penutup para rasul yang mulia.", "no": 12}]},
{judul:"Bi Syahri Rabi'in",isi:[
{"ar": "لَا إِلٰهَ إِلَّا اللهُ لَا إِلٰهَ إِلَّا اللهُ ۞ لَا إِلٰهَ إِلَّا اللهُ زَجَّ الْغَفَرَ", "lt": "Lâ ilâha illallâh, lâ ilâha illallâh ۞ lâ ilâha illallâh, zajjal-ghafar", "id": "Tiada tuhan selain Allah, tiada tuhan selain Allah, tiada tuhan selain Allah (kalimat yang menghalau dosa).", "no": 1},
{"ar": "بِشَهْرِ رَبِيْعٍ قَدْ بَدَا نُوْرُهُ الْأَعْلَى ۞ فَيَا حَبَّذَا بَدْرًا بِذَاكَ الْحِمَى يُجْلَى", "lt": "Bisyahri rabî‘in qad badâ nûruhul-a‘lâ ۞ fayâ ḥabbadzâ badran bidzâkal-ḥimâ yujlâ", "id": "Di bulan Rabi' telah tampak cahayanya yang tertinggi; alangkah indahnya purnama yang bersinar di tanah haram itu.", "no": 2},
{"ar": "أَنَارَتْ بِهِ الْأَكْوَانُ شَرْقًا وَمَغْرِبًا ۞ وَأَهْلُ السَّمَا قَالُوْا لَهُ مَرْحَبًا أَهْلَا", "lt": "Anârat bihil-akwânu syarqan wa maghriban ۞ wa ahlus-samâ qâlû lahû marḥaban ahlâ", "id": "Dengannya alam semesta bercahaya di timur dan barat, dan penghuni langit berkata kepadanya: Selamat datang.", "no": 3},
{"ar": "وَأُلْبِسَ ثَوْبَ النُّوْرِ عِزًّا وَرِفْعَةً ۞ فَمَا مِثْلُهُ فِيْ خَلْعَةِ الْحُسْنِ يُسْتَحْلَى", "lt": "Wa ulbisa tsauban-nûri ‘izzan wa rif‘atan ۞ famâ mitsluhû fî khal‘atil-ḥusni yustaḥlâ", "id": "Ia dipakaikan busana cahaya sebagai kemuliaan dan keluhuran; tiada yang menyamainya dalam busana keindahan yang memesona.", "no": 4},
{"ar": "وَلَمَّا رَآهُ الْبَدْرُ حَارَ لِحُسْنِهِ ۞ وَشَاهَدَ مِنْهُ بَهْجَةً تَسْلِبُ الْعَقْلَا", "lt": "Wa lammâ ra'âhul-badru ḥâra liḥusnihî ۞ wa syâhada minhu bahjatan taslibul-‘aqlâ", "id": "Ketika purnama melihatnya, ia terpana oleh ketampanannya, dan menyaksikan darinya keceriaan yang memikat akal.", "no": 5},
{"ar": "وَأُطْفِئَ نُوْرُ الشَّمْسِ مِنْ نُوْرِ وَجْهِهِ ۞ فَلِلّٰهِ مَا أَبْهَى وَلِلّٰهِ مَا أَجْلَى", "lt": "Wa uṭfi'a nûrusy-syamsi min nûri wajhihî ۞ falillâhi mâ abhâ wa lillâhi mâ ajlâ", "id": "Cahaya matahari menjadi redup oleh cahaya wajahnya; demi Allah, betapa indah dan betapa terangnya.", "no": 6},
{"ar": "أَيَا مَوْلِدَ الْمُخْتَارِ جَدَّدْتَ شَوْقَنَا ۞ إِلَى خَيْرِ مَبْعُوْثٍ جَلِيْلٍ حَوَى الْفَضْلَا", "lt": "Ayâ maulidal-mukhtâri jaddadta syauqanâ ۞ ilâ khairi mab‘ûtsin jalîlin ḥawal-fadllâ", "id": "Wahai kelahiran (Nabi) pilihan, engkau perbarui kerinduan kami kepada sebaik-baik utusan yang agung, yang menghimpun keutamaan.", "no": 7},
{"ar": "وَسَعْدًا مُقِيْمًا بِافْتِخَارٍ بِمَوْلِدٍ ۞ لَهُ خَبَرٌ عَنْ حُسْنِهِ أَبَدًا يُتْلَى", "lt": "Wa sa‘dan muqîman biftikhârin bimaulidin ۞ lahû khabarun ‘an ḥusnihî abadan yutlâ", "id": "Dan (engkau perbarui) kebahagiaan yang abadi dengan bangga atas kelahiran yang kabar keindahannya selalu dibacakan.", "no": 8},
{"ar": "عَلَيْهِ صَلَاةُ اللهِ مَا هَبَّتِ الصَّبَا ۞ وَمَا سَارَ حَادٍ بِالنِّيَاقِ إِلَى الْمَعْلَى", "lt": "‘Alaihi shalâtullâhi mâ habbatish-shabâ ۞ wa mâ sâra ḥâdin bin-niyâqi ilal-ma‘lâ", "id": "Semoga shalawat Allah tercurah kepadanya selama angin timur berembus, dan selama penggiring unta berjalan menuju Ma'la.", "no": 9},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 10}]},
{judul:"Inna Fatahna",isi:[
{"ar": "قَوْلُهُ تَعَالَى: يَا أَيُّهَا النَّبِيُّ إِنَّا أَرْسَلْنَاكَ شَاهِدًا وَمُبَشِّرًا وَنَذِيْرًا، أَيْ شَاهِدًا لِلرُّسُلِ بِالتَّبْلِيْغِ، وَمُبَشِّرًا لِمَنْ آمَنَ بِالْجَنَّةِ، وَنَذِيْرًا لِمَنْ كَذَّبَ بِالنَّارِ", "lt": "Qauluhû ta‘âlâ: yâ ayyuhan-nabiyyu innâ arsalnâka syâhidan wa mubasysyiran wa nadzîrâ, ay syâhidan lir-rusuli bit-tablîgh, wa mubasysyiran liman âmana bil-jannah, wa nadzîran liman kadzdzaba bin-nâr", "id": "Firman Allah Ta‘ala: \"Wahai Nabi, sesungguhnya Kami mengutusmu sebagai saksi, pembawa kabar gembira, dan pemberi peringatan\", yakni saksi bagi para rasul atas penyampaian (risalah), pembawa kabar gembira tentang surga bagi orang yang beriman, dan pemberi peringatan tentang neraka bagi orang yang mendustakan.", "no": 1},
{"ar": "وَدَاعِيًا إِلَى اللهِ، أَيْ إِلَى تَوْحِيْدِهِ وَطَاعَتِهِ، بِإِذْنِهِ، أَيْ بِأَمْرِهِ، وَسِرَاجًا مُنِيْرًا، سَمَّاهُ اللهُ سِرَاجًا لِأَنَّهُ يُهْتَدَى بِهِ كَالسِّرَاجِ يُسْتَضَاءُ بِهِ فِي الظُّلْمَةِ", "lt": "Wa dâ‘iyan ilallâh, ay ilâ tauḥîdihî wa ṭâ‘atih, bi'idznih, ay bi'amrih, wa sirâjan munîrâ, sammâhullâhu sirâjan li'annahû yuhtadâ bihî kas-sirâji yustadlâ'u bihî fidh-dhulmah", "id": "\"Dan sebagai penyeru kepada Allah\", yakni kepada tauhid dan ketaatan kepada-Nya, \"dengan izin-Nya\", yakni dengan perintah-Nya, \"dan sebagai pelita yang menerangi\". Allah menamainya pelita karena petunjuk diperoleh melaluinya, bagaikan pelita yang menerangi kegelapan.", "no": 2},
{"ar": "وَبَشِّرِ الْمُؤْمِنِيْنَ بِأَنَّ لَهُمْ مِنَ اللهِ فَضْلًا كَبِيْرًا، أَمَرَهُ اللهُ تَعَالَى أَنْ يُبَشِّرَ الْمُؤْمِنِيْنَ بِالْفَضْلِ الْكَبِيْرِ مِنَ اللهِ عَزَّ وَجَلَّ", "lt": "Wa basysyiril-mu'minîna bi'anna lahum minallâhi fadllan kabîrâ, amarahullâhu ta‘âlâ an yubasysyiral-mu'minîna bil-fadllil-kabîri minallâhi ‘azza wa jall", "id": "\"Dan sampaikanlah kabar gembira kepada orang-orang mukmin bahwa bagi mereka karunia yang besar dari Allah.\" Allah Ta‘ala memerintahkannya untuk memberi kabar gembira kepada orang-orang mukmin tentang karunia yang besar dari Allah ‘Azza wa Jalla. (QS. Al-Ahzab: 45-47)", "no": 3},
{"ar": "وَقَدْ بَيَّنَ اللهُ تَعَالَى الْفَضْلَ الْكَبِيْرَ فِيْ قَوْلِهِ تَعَالَى: وَالَّذِيْنَ آمَنُوْا وَعَمِلُوا الصَّالِحَاتِ فِيْ رَوْضَاتِ الْجَنَّاتِ لَهُمْ مَا يَشَاءُوْنَ عِنْدَ رَبِّهِمْ ذٰلِكَ هُوَ الْفَضْلُ الْكَبِيْرُ", "lt": "Wa qad bayyanallâhu ta‘âlal-fadllal-kabîra fî qaulihî ta‘âlâ: wal-ladzîna âmanû wa ‘amilush-shâliḥâti fî raudlâtil-jannât, lahum mâ yasyâ'ûna ‘inda rabbihim, dzâlika huwal-fadllul-kabîr", "id": "Allah Ta‘ala telah menjelaskan karunia yang besar itu dalam firman-Nya: \"Dan orang-orang yang beriman dan mengerjakan kebajikan berada di taman-taman surga; mereka memperoleh apa yang mereka kehendaki di sisi Tuhan mereka. Yang demikian itulah karunia yang besar.\" (QS. Asy-Syura: 22)", "no": 4},
{"ar": "قَوْلُهُ تَعَالَى: وَلَا تُطِعِ الْكَافِرِيْنَ، أَيْ مِنْ أَهْلِ مَكَّةَ، وَالْمُنَافِقِيْنَ، أَيْ مِنْ أَهْلِ الْمَدِيْنَةِ، وَدَعْ أَذَاهُمْ، قَالَ ابْنُ عَبَّاسٍ وَقَتَادَةُ: مَعْنَاهُ اصْبِرْ عَلَى أَذَاهُمْ يَا مُحَمَّدُ", "lt": "Qauluhû ta‘âlâ: wa lâ tuṭi‘il-kâfirîn, ay min ahli makkah, wal-munâfiqîn, ay min ahlil-madînah, wa da‘ adzâhum, qâlabnu ‘abbâsin wa qatâdah: ma‘nâhush-bir ‘alâ adzâhum yâ muḥammad", "id": "Firman-Nya Ta‘ala: \"Dan janganlah engkau menuruti orang-orang kafir\", yakni dari penduduk Makkah, \"dan orang-orang munafik\", yakni dari penduduk Madinah, \"dan abaikanlah gangguan mereka\". Ibnu Abbas dan Qatadah berkata: Maknanya, bersabarlah atas gangguan mereka, wahai Muhammad.", "no": 5},
{"ar": "وَقَالَ الزَّجَّاجُ: أَيْ لَا تُجَازِهِمْ عَلَيْهِ، وَهٰذَا مَنْسُوْخٌ بِآيَةِ الْقِتَالِ، وَتَوَكَّلْ عَلَى اللهِ، أَمَرَهُ بِالتَّوَكُّلِ عَلَيْهِ وَآنَسَهُ بِقَوْلِهِ: وَكَفَى بِاللهِ وَكِيْلًا، وَمَعْنَى وَكِيْلًا أَيْ حَافِظًا", "lt": "Wa qâlaz-zajjâj: ay lâ tujâzihim ‘alaih, wa hâdzâ mansûkhun bi'âyatil-qitâl, wa tawakkal ‘alallâh, amarahû bit-tawakkuli ‘alaihi wa ânasahû biqaulihî: wa kafâ billâhi wakîlâ, wa ma‘nâ wakîlan ay ḥâfidhâ", "id": "Az-Zajjaj berkata: Yakni, janganlah engkau membalas gangguan mereka; dan ini dihapus (hukumnya) dengan ayat perang. \"Dan bertawakallah kepada Allah\": Allah memerintahkannya untuk bertawakal kepada-Nya dan menenangkannya dengan firman-Nya: \"Dan cukuplah Allah sebagai pemelihara\". Makna wakil adalah penjaga. (QS. Al-Ahzab: 48)", "no": 6},
{"ar": "رُوِيَ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: كُنْتُ نُوْرًا بَيْنَ يَدَيِ اللهِ تَعَالَى قَبْلَ أَنْ يَخْلُقَ آدَمَ بِأَلْفَيْ عَامٍ، يُسَبِّحُ اللهَ تَعَالَى ذٰلِكَ النُّوْرُ وَتُسَبِّحُ الْمَلَائِكَةُ بِتَسْبِيْحِهِ", "lt": "Ruwiya ‘anin-nabiyyi shallallâhu ‘alaihi wa sallama annahû qâl: kuntu nûran baina yadayillâhi ta‘âlâ qabla an yakhluqa âdama bi'alfai ‘âm, yusabbiḥullâha ta‘âlâ dzâlikan-nûru wa tusabbiḥul-malâ'ikatu bitasbîḥih", "id": "Diriwayatkan dari Nabi ﷺ bahwa beliau bersabda: Dahulu aku adalah cahaya di hadapan Allah Ta‘ala dua ribu tahun sebelum Dia menciptakan Adam. Cahaya itu bertasbih kepada Allah Ta‘ala, dan para malaikat bertasbih mengikuti tasbihnya.", "no": 7},
{"ar": "فَلَمَّا خَلَقَ اللهُ تَعَالَى آدَمَ أَلْقَى ذٰلِكَ النُّوْرَ فِيْ طِيْنَتِهِ، فَأَهْبَطَنِيَ اللهُ فِيْ صُلْبِ آدَمَ إِلَى الْأَرْضِ، وَحَمَلَنِيْ فِي السَّفِيْنَةِ فِيْ صُلْبِ نُوْحٍ، وَجَعَلَنِيْ فِيْ صُلْبِ إِبْرَاهِيْمَ الْخَلِيْلِ حِيْنَ قُذِفَ بِهِ إِلَى النَّارِ", "lt": "Falammâ khalaqallâhu ta‘âlâ âdama alqâ dzâlikan-nûra fî ṭînatih, fa ahbaṭaniyallâhu fî shulbi âdama ilal-ardl, wa ḥamalanî fis-safînati fî shulbi nûḥ, wa ja‘alanî fî shulbi ibrâhîmal-khalîli ḥîna qudzifa bihî ilan-nâr", "id": "Ketika Allah Ta‘ala menciptakan Adam, Dia meletakkan cahaya itu dalam tanah asal kejadiannya. Lalu Allah menurunkanku ke bumi di dalam sulbi Adam, membawaku di dalam bahtera di sulbi Nuh, dan menjadikanku di sulbi Ibrahim Al-Khalil ketika ia dilemparkan ke dalam api.", "no": 8},
{"ar": "وَلَمْ يَزَلْ يَنْقُلُنِيْ مِنَ الْأَصْلَابِ الطَّاهِرَةِ إِلَى الْأَرْحَامِ الزَّكِيَّةِ الْفَاخِرَةِ، حَتَّى أَخْرَجَنِيَ اللهُ مِنْ بَيْنِ أَبَوَيَّ وَلَمْ يَلْتَقِيَا عَلَى سِفَاحٍ قَطُّ", "lt": "Wa lam yazal yanqulunî minal-ashlâbiṭ-ṭâhirati ilal-arḥâmiz-zakiyyatil-fâkhirah, ḥattâ akhrajaniyallâhu min baini abawayya wa lam yaltaqiyâ ‘alâ sifâḥin qaṭṭ", "id": "Dia senantiasa memindahkanku dari sulbi-sulbi yang suci ke rahim-rahim yang bersih lagi mulia, hingga Allah melahirkanku dari kedua orang tuaku, dan keduanya sama sekali tidak pernah bertemu dalam perzinaan. (Kitab Asy-Syari'ah, Al-Ajurri)", "no": 9}]},
{judul:"Tanaqqalta fi Ashlabi Arbabi Su'dadin",isi:[
{"ar": "اَللهُ اللهُ اللهُ رَبُّنَا ۞ اَللهُ اللهُ اللهُ حَسْبُنَا", "lt": "Allâhu allâhu allâhu rabbunâ ۞ allâhu allâhu allâhu ḥasbunâ", "id": "Allah, Allah, Allah Tuhan kami; Allah, Allah, Allah yang mencukupi kami.", "no": 1},
{"ar": "تَنَقَّلْتَ فِيْ أَصْلَابِ أَرْبَابِ سُؤْدَدٍ ۞ كَذَا الشَّمْسُ فِيْ أَبْرَاجِهَا تَتَنَقَّلُ", "lt": "Tanaqqalta fî ashlâbi arbâbi su'dadin ۞ kadzasy-syamsu fî abrâjihâ tatanaqqalu", "id": "Engkau berpindah-pindah di sulbi para pemilik kemuliaan, sebagaimana matahari berpindah-pindah di gugusan bintangnya.", "no": 2},
{"ar": "وَسِرْتَ سَرِيًّا فِيْ بُطُوْنٍ تَشَرَّفَتْ ۞ بِحَمْلٍ عَلَيْهِ فِي الْأُمُوْرِ الْمُعَوَّلُ", "lt": "Wa sirta sariyyan fî buṭûnin tasyarrafat ۞ biḥamlin ‘alaihi fil-umûril-mu‘awwalu", "id": "Engkau berjalan mulia di dalam rahim-rahim yang menjadi mulia karena mengandung (dirimu), yang menjadi andalan dalam segala urusan.", "no": 3},
{"ar": "هَنِيْئًا لِقَوْمٍ أَنْتَ فِيْهِمْ وَمِنْهُمُ ۞ بَدَا مِنْكَ بَدْرٌ بِالْجَمَالِ مُسَرْبَلُ", "lt": "Hanî'an liqaumin anta fîhim wa minhumu ۞ badâ minka badrun bil-jamâli musarbalu", "id": "Berbahagialah kaum yang engkau berada di tengah mereka dan berasal dari mereka; darimu tampak purnama yang berselimut keindahan.", "no": 4},
{"ar": "وَلِلّٰهِ وَقْتٌ جِئْتَ فِيْهِ وَطَالِعٌ ۞ سَعِيْدٌ عَلَى أَهْلِ الْوُجُوْدِ وَمُقْبِلُ", "lt": "Wa lillâhi waqtun ji'ta fîhi wa ṭâli‘un ۞ sa‘îdun ‘alâ ahlil-wujûdi wa muqbilu", "id": "Alangkah indahnya waktu engkau datang, dengan bintang keberuntungan yang membahagiakan dan menyambut seluruh penghuni alam.", "no": 5},
{"ar": "عَلَيْهِ صَلَاةُ اللهِ ثُمَّ سَلَامُهُ ۞ بِتَعْدَادِ مَا قَطْرٌ مِنَ السُّحْبِ يَنْزِلُ", "lt": "‘Alaihi shalâtullâhi tsumma salâmuhû ۞ bita‘dâdi mâ qaṭrun minas-suḥbi yanzilu", "id": "Semoga shalawat Allah dan salam-Nya tercurah kepadanya sebanyak tetesan hujan yang turun dari awan.", "no": 6},
{"ar": "خِتَامُ جَمِيْعِ الْأَنْبِيَاءِ مُحَمَّدٌ ۞ وَيَوْمَ قِيَامِ النَّاسِ يُبْعَثُ أَوَّلُ", "lt": "Khitâmu jamî‘il-anbiyâ'i muḥammadun ۞ wa yauma qiyâmin-nâsi yub‘atsu awwalu", "id": "Penutup seluruh nabi adalah Muhammad, dan pada hari manusia dibangkitkan, beliaulah yang pertama dibangkitkan.", "no": 7},
{"ar": "فَجُدْ يَا رَسُوْلَ اللهِ مِنْكَ بِرَحْمَةٍ ۞ لِعَبْدٍ أَسِيْرٍ بِالذُّنُوْبِ يُقَبِّلُ", "lt": "Fajud yâ rasûlallâhi minka biraḥmatin ۞ li‘abdin asîrin bidz-dzunûbi yuqabbilu", "id": "Maka limpahkanlah, wahai Rasulullah, rahmat darimu kepada hamba yang tertawan dosa-dosa, yang (datang) menghaturkan penghormatan.", "no": 8},
{"ar": "وَصَلَّى إِلٰهُ كُلَّ يَوْمٍ وَلَيْلَةٍ ۞ عَلَى أَحْمَدَ الْمُخْتَارِ مَوْلَى الْفَضَائِلِ", "lt": "Wa shallâ ilâhu kulla yaumin wa lailatin ۞ ‘alâ aḥmadal-mukhtâri maulal-fadlâ'ili", "id": "Semoga Tuhan melimpahkan shalawat setiap siang dan malam kepada Ahmad, (Nabi) pilihan, pemilik segala keutamaan.", "no": 9},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 10}]},
{judul:"Kehamilan Sayyidah Aminah",isi:[
{"ar": "وَعَنْ يَزِيْدَ بْنِ عَبْدِ اللهِ بْنِ وَهْبٍ عَنْ عَمَّتِهِ قَالَتْ: كُنَّا نَسْمَعُ أَنَّ آمِنَةَ لَمَّا حَمَلَتْ بِرَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَتْ تَقُوْلُ: مَا شَعُرْتُ أَنِّيْ حَمَلْتُ، وَلَا وَجَدْتُ لَهُ ثِقْلًا وَلَا أَلَمًا كَمَا تَجِدُ النِّسَاءُ، إِلَّا أَنِّيْ أَنْكَرْتُ رَفْعَ حَيْضَتِيْ", "lt": "Wa ‘an yazîdabni ‘abdillâhibni wahbin ‘an ‘ammatihî qâlat: kunnâ nasma‘u anna âminata lammâ ḥamalat birasûlillâhi shallallâhu ‘alaihi wa sallama kânat taqûl: mâ sya‘urtu annî ḥamaltu, wa lâ wajadtu lahû tsiqlan wa lâ alaman kamâ tajidun-nisâ', illâ annî ankartu raf‘a ḥaidlatî", "id": "Dari Yazid bin Abdullah bin Wahb, dari bibinya, ia berkata: Kami pernah mendengar bahwa Aminah, ketika mengandung Rasulullah ﷺ, berkata: Aku tidak merasa sedang mengandung, dan tidak merasakan berat maupun sakit sebagaimana dirasakan para wanita, hanya saja aku heran karena haidku terhenti.", "no": 1},
{"ar": "وَأَتَانِيْ آتٍ وَأَنَا بَيْنَ النَّوْمِ وَالْيَقَظَةِ، فَقَالَ لِيْ: هَلْ شَعُرْتِ أَنَّكِ حَمَلْتِ؟ فَكَأَنِّيْ أَقُوْلُ: لَا أَدْرِيْ، فَقَالَ: إِنَّكِ قَدْ حَمَلْتِ بِسَيِّدِ هٰذِهِ الْأُمَّةِ وَنَبِيِّهَا نَبِيِّ الْهُدَى وَالرَّحْمَةِ، وَذٰلِكَ يَوْمَ الْاِثْنَيْنِ", "lt": "Wa atânî âtin wa ana bainan-naumi wal-yaqadhah, faqâla lî: hal sya‘urti annaki ḥamalti? faka'annî aqûl: lâ adrî, faqâl: innaki qad ḥamalti bisayyidi hâdzihil-ummati wa nabiyyihâ nabiyyil-hudâ war-raḥmah, wa dzâlika yaumal-itsnain", "id": "Lalu datang kepadaku seseorang ketika aku antara tidur dan terjaga, ia berkata: Apakah engkau merasa bahwa engkau sedang mengandung? Seakan-akan aku menjawab: Aku tidak tahu. Ia berkata: Sesungguhnya engkau sedang mengandung pemimpin umat ini dan nabinya, nabi petunjuk dan rahmat. Peristiwa itu terjadi pada hari Senin.", "no": 2},
{"ar": "قَالَتْ: فَكَانَ ذٰلِكَ مِمَّا تُيُقِّنَ عِنْدِي الْحَمْلُ، فَلَمَّا دَنَتْ وِلَادَتِيْ أَتَانِيْ ذٰلِكَ الْآتِيْ فَقَالَ لِيْ: قُوْلِيْ: أُعِيْذُهُ بِالْوَاحِدِ الصَّمَدِ مِنْ شَرِّ كُلِّ ذِيْ حَسَدٍ، قَالَتْ: فَكُنْتُ أَقُوْلُ ذٰلِكَ وَأُكَرِّرُهُ مِرَارًا", "lt": "Qâlat: fakâna dzâlika mimmâ tuyuqqina ‘indiyal-ḥamlu, falammâ danat wilâdatî atânî dzâlikal-âtî faqâla lî: qûlî: u‘îdzuhû bil-wâḥidish-shamadi min syarri kulli dzî ḥasad, qâlat: fakuntu aqûlu dzâlika wa ukarriruhû mirârâ", "id": "Ia berkata: Dari situlah aku yakin bahwa aku sedang mengandung. Ketika kelahiranku sudah dekat, orang itu datang lagi dan berkata kepadaku: Ucapkanlah: Aku memohonkan perlindungan untuknya kepada Yang Maha Esa, tempat bergantung, dari kejahatan setiap pendengki. Ia berkata: Maka aku pun mengucapkannya dan mengulanginya berkali-kali. (Ath-Thabaqat Al-Kubra, Ibnu Sa'ad)", "no": 3},
{"ar": "قِيْلَ: لَمَّا أَرَادَ اللهُ عَزَّ وَجَلَّ ظُهُوْرَ خَيْرِ خَلْقِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَمَرَ جِبْرِيْلَ أَنْ يَقْبِضَ طِيْنَتَهُ مِنْ مَكَانِ قَبْرِهِ الْكَرِيْمِ، فَقَبَضَهَا ثُمَّ طَافَ بِهَا جَنَّاتِ النَّعِيْمِ، وَغَمَسَهَا فِيْ أَنْهَارِ التَّسْنِيْمِ، وَأَقْبَلَ بِهَا بَيْنَ يَدَيِ اللهِ الْعَلِيِّ الْعَظِيْمِ", "lt": "Qîla: lammâ arâdallâhu ‘azza wa jalla dhuhûra khairi khalqihî shallallâhu ‘alaihi wa sallam, amara jibrîla an yaqbidla ṭînatahû min makâni qabrihil-karîm, faqabadlahâ tsumma ṭâfa bihâ jannâtin-na‘îm, wa ghamasahâ fî anhârit-tasnîm, wa aqbala bihâ baina yadayillâhil-‘aliyyil-‘adhîm", "id": "Diriwayatkan: Ketika Allah ‘Azza wa Jalla hendak menampakkan sebaik-baik makhluk-Nya ﷺ, Dia memerintahkan Jibril untuk mengambil tanah asal kejadiannya dari tempat kuburnya yang mulia. Jibril pun mengambilnya, lalu membawanya berkeliling surga-surga kenikmatan, mencelupkannya ke sungai-sungai Tasnim, kemudian menghadapkannya ke hadirat Allah Yang Mahatinggi lagi Mahaagung.", "no": 4},
{"ar": "وَلَهَا عَرَقٌ يَسِيْلُ، فَخَلَقَ اللهُ مِنْ ذٰلِكَ الْعَرَقِ نُوْرَ كُلِّ نَبِيٍّ جَلِيْلٍ، فَجَمِيْعُ الْأَنْبِيَاءِ خُلِقُوْا مِنْ نُوْرِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ", "lt": "Wa lahâ ‘araqun yasîl, fakhalaqallâhu min dzâlikal-‘araqi nûra kulli nabiyyin jalîl, fajamî‘ul-anbiyâ'i khuliqû min nûri muḥammadin shallallâhu ‘alaihi wa sallam", "id": "Tanah itu mengeluarkan keringat yang mengalir, maka dari keringat itu Allah menciptakan cahaya setiap nabi yang agung; seluruh nabi diciptakan dari cahaya Muhammad ﷺ.", "no": 5},
{"ar": "ثُمَّ أُوْدِعَتْ تِلْكَ الطِّيْنَةُ فِيْ ظَهْرِ آدَمَ، وَأُلْقِيَ فِيْهَا النُّوْرُ الَّذِيْ سَبَقَ فَخْرُهُ وَتَقَادَمَ، فَوَقَعَتْ هُنَالِكَ طَوَائِفُ الْمَلَائِكَةِ الْمُقَرَّبِيْنَ سُجُوْدًا لِآدَمَ", "lt": "Tsumma ûdi‘at tilkaṭ-ṭînatu fî dhahri âdam, wa ulqiya fîhan-nûrul-ladzî sabaqa fakhruhû wa taqâdam, fawaqa‘at hunâlika ṭawâ'iful-malâ'ikatil-muqarrabîna sujûdan li'âdam", "id": "Kemudian tanah itu dititipkan di punggung Adam, dan diletakkan padanya cahaya yang kemuliaannya telah ada sejak dahulu. Maka di sanalah rombongan malaikat yang didekatkan (kepada Allah) bersujud kepada Adam.", "no": 6},
{"ar": "ثُمَّ أَخَذَ اللهُ تَعَالَى عَلَى آدَمَ الْمَوَاثِيْقَ وَالْعُهُوْدَ، حِيْنَ أَمَرَ الْمَلَائِكَةَ لَهُ بِالسُّجُوْدِ، أَنْ لَا يُوْدِعَ ذٰلِكَ النُّوْرَ إِلَّا فِيْ أَهْلِ الْكَرَمِ وَالْجُوْدِ، الْمُطَهَّرِيْنَ مِنَ الدَّنَسِ وَالْجُحُوْدِ", "lt": "Tsumma akhadzallâhu ta‘âlâ ‘alâ âdamal-mawâtsîqa wal-‘uhûd, ḥîna amaral-malâ'ikata lahû bis-sujûd, an lâ yûdi‘a dzâlikan-nûra illâ fî ahlil-karami wal-jûd, al-muṭahharîna minad-danasi wal-juḥûd", "id": "Kemudian Allah Ta‘ala mengambil perjanjian dan janji dari Adam, ketika Dia memerintahkan para malaikat bersujud kepadanya, agar ia tidak menitipkan cahaya itu kecuali kepada orang-orang yang mulia dan dermawan, yang suci dari noda dan keingkaran.", "no": 7},
{"ar": "فَمَا زَالَ ذٰلِكَ النُّوْرُ يَنْتَقِلُ مِنْ ظُهُوْرِ الْأَخْيَارِ إِلَى بُطُوْنِ الْأَحْرَارِ، حَتَّى أَوْصَلَتْهُ يَدُ الشَّرَفِ وَالْمَكَارِمِ إِلَى عَبْدِ اللهِ بْنِ عَبْدِ الْمُطَّلِبِ بْنِ هَاشِمٍ", "lt": "Famâ zâla dzâlikan-nûru yantaqilu min dhuhûril-akhyâri ilâ buṭûnil-aḥrâr, ḥattâ aushalat-hu yadusy-syarafi wal-makârimi ilâ ‘abdillâhibni ‘abdil-muṭṭalibibni hâsyim", "id": "Cahaya itu terus berpindah dari punggung orang-orang pilihan ke rahim wanita-wanita merdeka (yang mulia), hingga tangan kemuliaan dan keluhuran menyampaikannya kepada Abdullah bin Abdul Muthalib bin Hasyim.", "no": 8},
{"ar": "فَلَمَّا آنَ أَوَانُ وَفَاءِ عَهْدِهِ، طَلَعَ فِي الْأَكْوَانِ طَالِعُ سَعْدِهِ، نُشِرَ عَلَمُ الْفُتُوَّةِ لِظُهُوْرِ خَاتَمِ النُّبُوَّةِ، شَخَصَتْ لِعَبْدِ اللهِ الْأَبْصَارُ، وَأَشْرَقَتْ عَلَيْهِ الْأَنْوَارُ", "lt": "Falammâ âna awânu wafâ'i ‘ahdih, ṭala‘a fil-akwâni ṭâli‘u sa‘dih, nusyira ‘alamul-futuwwati lidhuhûri khâtamin-nubuwwah, syakhashat li‘abdillâhil-abshâr, wa asyraqat ‘alaihil-anwâr", "id": "Ketika tiba saatnya janji itu dipenuhi, terbitlah bintang keberuntungannya di alam semesta, dan dikibarkan panji kepahlawanan untuk kemunculan penutup kenabian. Pandangan mata tertuju kepada Abdullah, dan cahaya-cahaya bersinar di atasnya.", "no": 9},
{"ar": "أُلْبِسَ ثَوْبَ الْمَلَاحَةِ، نَطَقَ بِالْبَيَانِ وَالْفَصَاحَةِ، نَادَاهُ لِسَانُ الْمَشِيْئَةِ: يَا عَبْدَ اللهِ مَا يَصْلُحُ كَنْزًا لِمَا حَمَلْتَ مِنَ الْوَدِيْعَةِ، إِلَّا أَحْشَاءُ آمِنَةَ الْمَنِيْعَةِ، الْمُطَهَّرَةِ مِنَ الدَّنَسِ وَالْأَكْدَارِ", "lt": "Ulbisa tsaubal-malâḥah, naṭaqa bil-bayâni wal-fashâḥah, nâdâhu lisânul-masyî'ah: yâ ‘abdallâhi mâ yashluḥu kanzan limâ ḥamalta minal-wadî‘ah, illâ aḥsyâ'u âminatal-manî‘ah, al-muṭahharati minad-danasi wal-akdâr", "id": "Ia dipakaikan busana ketampanan, berbicara dengan jelas dan fasih. Lisan kehendak (Ilahi) memanggilnya: Wahai Abdullah, tidak ada yang pantas menjadi tempat penyimpanan titipan yang engkau bawa kecuali rahim Aminah yang terjaga, yang suci dari noda dan kekeruhan.", "no": 10},
{"ar": "سَيِّدَةِ النِّسَاءِ بَنِي النَّجَّارِ، اجْتَمَعَ شَمْلُهُ بِشَمْلِهَا، اتَّصَلَ حَبْلُهُ بِحَبْلِهَا، ظَهَرَ صَفَاءُ يَقِيْنِهَا، انْطَوَتِ الْأَحْشَاءُ عَلَى جَنِيْنِهَا، سَطَعَ نُوْرُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيْ جَبِيْنِهَا", "lt": "Sayyidatin-nisâ'i banin-najjâr, ijtama‘a syamluhû bisyamlihâ, ittashala ḥabluhû biḥablihâ, dhahara shafâ'u yaqînihâ, inṭawatil-aḥsyâ'u ‘alâ janînihâ, saṭa‘a nûrun-nabiyyi shallallâhu ‘alaihi wa sallama fî jabînihâ", "id": "(Aminah,) pemuka wanita Bani Najjar. Maka bersatulah Abdullah dengannya, tersambung talinya dengan tali Aminah, tampaklah kejernihan keyakinannya, rahimnya pun mengandung janinnya, dan cahaya Nabi ﷺ memancar di dahinya.", "no": 11},
{"ar": "أَوَّلُ شَهْرٍ مِنْ شُهُوْرِ حَمْلِهَا أَتَاهَا فِي الْمَنَامِ آدَمُ، وَأَعْلَمَهَا أَنَّهَا حَمَلَتْ بِأَجَلِّ الْعَالَمِ", "lt": "Awwalu syahrin min syuhûri ḥamlihâ atâhâ fil-manâmi âdam, wa a‘lamahâ annahâ ḥamalat bi'ajallil-‘âlam", "id": "Pada bulan pertama kehamilannya, Adam datang kepadanya dalam mimpi dan memberitahunya bahwa ia sedang mengandung makhluk paling agung di alam semesta.", "no": 12},
{"ar": "اَلشَّهْرُ الثَّانِيْ أَتَاهَا فِي الْمَنَامِ إِدْرِيْسُ، وَأَخْبَرَهَا بِفَخْرِ مُحَمَّدٍ وَقَدْرِهِ النَّفِيْسِ", "lt": "Asy-syahruts-tsânî atâhâ fil-manâmi idrîs, wa akhbarahâ bifakhri muḥammadin wa qadrihin-nafîs", "id": "Pada bulan kedua, Idris datang kepadanya dalam mimpi dan mengabarkan kemuliaan Muhammad dan derajatnya yang berharga.", "no": 13},
{"ar": "اَلشَّهْرُ الثَّالِثُ أَتَاهَا فِي الْمَنَامِ نُوْحٌ، وَقَالَ لَهَا: إِنَّكِ قَدْ حَمَلْتِ بِصَاحِبِ النَّصْرِ وَالْفُتُوْحِ", "lt": "Asy-syahruts-tsâlitsu atâhâ fil-manâmi nûḥ, wa qâla lahâ: innaki qad ḥamalti bishâḥibin-nashri wal-futûḥ", "id": "Pada bulan ketiga, Nuh datang kepadanya dalam mimpi dan berkata: Sesungguhnya engkau sedang mengandung pemilik pertolongan dan kemenangan.", "no": 14},
{"ar": "اَلشَّهْرُ الرَّابِعُ أَتَاهَا فِي الْمَنَامِ إِبْرَاهِيْمُ الْخَلِيْلُ، وَذَكَرَ لَهَا فَضْلَ مُحَمَّدٍ وَمَحَلَّهُ الْجَلِيْلَ", "lt": "Asy-syahrur-râbi‘u atâhâ fil-manâmi ibrâhîmul-khalîl, wa dzakara lahâ fadlla muḥammadin wa maḥallahul-jalîl", "id": "Pada bulan keempat, Ibrahim Al-Khalil datang kepadanya dalam mimpi dan menyebutkan keutamaan Muhammad dan kedudukannya yang agung.", "no": 15},
{"ar": "اَلشَّهْرُ الْخَامِسُ أَتَاهَا فِي الْمَنَامِ إِسْمَاعِيْلُ، وَبَشَّرَهَا أَنَّ ابْنَهَا صَاحِبُ الْمَهَابَةِ وَالتَّبْجِيْلِ", "lt": "Asy-syahrul-khâmisu atâhâ fil-manâmi ismâ‘îl, wa basysyarahâ annabnahâ shâḥibul-mahâbati wat-tabjîl", "id": "Pada bulan kelima, Isma'il datang kepadanya dalam mimpi dan memberinya kabar gembira bahwa putranya adalah pemilik kewibawaan dan penghormatan.", "no": 16},
{"ar": "اَلشَّهْرُ السَّادِسُ أَتَاهَا فِي الْمَنَامِ مُوْسَى الْكَلِيْمُ، وَأَعْلَمَهَا بِرُتْبَةِ مُحَمَّدٍ وَجَاهِهِ الْعَظِيْمِ", "lt": "Asy-syahrus-sâdisu atâhâ fil-manâmi mûsal-kalîm, wa a‘lamahâ biritbati muḥammadin wa jâhihil-‘adhîm", "id": "Pada bulan keenam, Musa Al-Kalim datang kepadanya dalam mimpi dan memberitahunya tentang derajat Muhammad dan kedudukannya yang agung.", "no": 17},
{"ar": "اَلشَّهْرُ السَّابِعُ أَتَاهَا فِي الْمَنَامِ دَاوُدُ، وَأَعْلَمَهَا أَنَّهَا حَمَلَتْ بِصَاحِبِ الْمَقَامِ الْمَحْمُوْدِ، وَالْحَوْضِ الْمَوْرُوْدِ، وَاللِّوَاءِ الْمَعْقُوْدِ، وَالْكَرَمِ وَالْجُوْدِ", "lt": "Asy-syahrus-sâbi‘u atâhâ fil-manâmi dâwud, wa a‘lamahâ annahâ ḥamalat bishâḥibil-maqâmil-maḥmûd, wal-ḥaudlil-maurûd, wal-liwâ'il-ma‘qûd, wal-karami wal-jûd", "id": "Pada bulan ketujuh, Dawud datang kepadanya dalam mimpi dan memberitahunya bahwa ia mengandung pemilik Maqam Mahmud, telaga yang didatangi (umatnya), panji yang terikat, serta kemuliaan dan kedermawanan.", "no": 18},
{"ar": "وَأَخْبَرَهَا أَنَّ ابْنَهَا صَاحِبُ الْمَقَامِ الْمَحْمُوْدِ", "lt": "Wa akhbarahâ annabnahâ shâḥibul-maqâmil-maḥmûd", "id": "Ia mengabarkan kepadanya bahwa putranya adalah pemilik Maqam Mahmud.", "no": 19},
{"ar": "اَلشَّهْرُ الثَّامِنُ أَتَاهَا فِي الْمَنَامِ سُلَيْمَانُ، وَأَخْبَرَهَا أَنَّهَا حَمَلَتْ بِنَبِيِّ آخِرِ الزَّمَانِ", "lt": "Asy-syahruts-tsâminu atâhâ fil-manâmi sulaimân, wa akhbarahâ annahâ ḥamalat binabiyyi âkhiriz-zamân", "id": "Pada bulan kedelapan, Sulaiman datang kepadanya dalam mimpi dan mengabarkan bahwa ia sedang mengandung nabi akhir zaman.", "no": 20},
{"ar": "اَلشَّهْرُ التَّاسِعُ أَتَاهَا فِي الْمَنَامِ عِيْسَى الْمَسِيْحُ، وَقَالَ لَهَا: إِنَّكِ قَدْ خُصِصْتِ بِمُظْهِرِ الدِّيْنِ الصَّحِيْحِ، وَاللِّسَانِ الْفَصِيْحِ", "lt": "Asy-syahrut-tâsi‘u atâhâ fil-manâmi ‘îsal-masîḥ, wa qâla lahâ: innaki qad khushishti bimudh-hirid-dînish-shaḥîḥ, wal-lisânil-fashîḥ", "id": "Pada bulan kesembilan, Isa Al-Masih datang kepadanya dalam mimpi dan berkata: Sesungguhnya engkau telah diistimewakan dengan (mengandung) penampak agama yang benar, pemilik lisan yang fasih.", "no": 21},
{"ar": "وَكُلُّ وَاحِدٍ مِنْهُمْ يَقُوْلُ لَهَا فِيْ نَوْمِهَا: يَا آمِنَةُ، إِذَا وَضَعْتِ شَمْسَ الْفَلَاحِ وَالْهُدَى فَسَمِّيْهِ مُحَمَّدًا", "lt": "Wa kullu wâḥidin minhum yaqûlu lahâ fî naumihâ: yâ âminah, idzâ wadla‘ti syamsal-falâḥi wal-hudâ fasammîhi muḥammadâ", "id": "Masing-masing dari mereka berkata kepadanya dalam tidurnya: Wahai Aminah, bila engkau telah melahirkan matahari keberuntungan dan petunjuk, namailah ia Muhammad.", "no": 22},
{"ar": "فَلَمَّا اشْتَدَّ بِهَا طَلْقُ النِّفَاسِ، وَلَمْ يَعْلَمْ بِهَا أَحَدٌ مِنَ النَّاسِ، بَسَطَتْ أَكُفَّ شَكْوَاهَا إِلَى مَنْ يَعْلَمُ سِرَّهَا وَنَجْوَاهَا", "lt": "Falammasy-tadda bihâ ṭalqun-nifâs, wa lam ya‘lam bihâ aḥadun minan-nâs, basaṭat akuffa syakwâhâ ilâ man ya‘lamu sirrahâ wa najwâhâ", "id": "Ketika rasa sakit melahirkan semakin kuat, sementara tidak seorang pun mengetahui keadaannya, ia menengadahkan tangan pengaduan kepada (Allah) Yang mengetahui rahasia dan bisikan hatinya.", "no": 23},
{"ar": "يَا عَالِمَ السِّرِّ مِنَّا ۞ لَا تَهْتِكِ السِّتْرَ عَنَّا ۞ فَاعْفُنَا وَاعْفُ عَنَّا ۞ وَاغْفِرْ لَنَا حَيْثُ كُنَّا", "lt": "Yâ ‘âlimas-sirri minnâ ۞ lâ tahtikis-sitra ‘annâ ۞ fa‘funâ wa‘fu ‘annâ ۞ waghfir lanâ ḥaitsu kunnâ", "id": "(Berhenti sejenak dan berdoa sambil mengangkat tangan:) Wahai Yang mengetahui rahasia kami, janganlah Engkau singkap tabir (aib) kami; maafkanlah kami, ampunilah kesalahan kami, dan ampunilah kami di mana pun kami berada.", "no": 24},
{"ar": "فَإِذَا هِيَ بِآسِيَةَ امْرَأَةِ فِرْعَوْنَ وَمَرْيَمَ ابْنَةِ عِمْرَانَ وَجَمَاعَةٍ مِنَ الْحُوْرِ الْحِسَانِ، قَدْ أَضَاءَ مِنْ جَمَالِهِنَّ الْمَكَانُ، فَذَهَبَ عَنْهَا مَا تَجِدُ مِنَ الْأَحْزَانِ", "lt": "Fa idzâ hiya bi'âsiyatamra'ati fir‘auna wa maryamabnati ‘imrâna wa jamâ‘atin minal-ḥûril-ḥisân, qad adlâ'a min jamâlihinnal-makân, fadzahaba ‘anhâ mâ tajidu minal-aḥzân", "id": "Tiba-tiba ia didatangi Asiyah istri Fir'aun, Maryam putri Imran, dan sekelompok bidadari yang cantik, yang keindahan mereka menerangi tempat itu, maka hilanglah kesedihan yang ia rasakan. (Taudlihul Maram, Syekh Husain bin Habib)", "no": 25}]},
{judul:"Wulidal Habib",isi:[
{"ar": "اَللهُ لِيْ اَللهُ لِيْ نِعْمَ الْمَوْلَى ۞ صَلُّوْا عَلَى هٰذَا النَّبِيِّ مُحَمَّدْ", "lt": "Allâhu lî allâhu lî ni‘mal-maulâ ۞ shallû ‘alâ hâdzan-nabiyyi muḥammad", "id": "Allah bagiku, Allah bagiku, sebaik-baik pelindung; bershalawatlah kepada Nabi ini, Muhammad.", "no": 1},
{"ar": "وُلِدَ الْحَبِيْبُ وَخَدُّهُ مُتَوَرِّدُ ۞ وَالنُّوْرُ مِنْ وَجَنَاتِهِ يَتَوَقَّدُ", "lt": "Wulidal-ḥabîbu wa khadduhû mutawarridu ۞ wan-nûru min wajanâtihî yatawaqqadu", "id": "Telah lahir sang kekasih dengan pipi yang kemerahan bagai mawar, dan cahaya memancar dari kedua pipinya.", "no": 2},
{"ar": "وُلِدَ الْحَبِيْبُ وَمِثْلُهُ لَا يُوْلَدُ ۞ وُلِدَ الْحَبِيْبُ وَخَدُّهُ مُتَوَرِّدُ", "lt": "Wulidal-ḥabîbu wa mitsluhû lâ yûladu ۞ wulidal-ḥabîbu wa khadduhû mutawarridu", "id": "Telah lahir sang kekasih, dan tiada yang lahir seperti dirinya; telah lahir sang kekasih dengan pipi yang kemerahan.", "no": 3},
{"ar": "وُلِدَ الَّذِيْ لَوْلَاهُ مَا عُشِقَ النَّقَا ۞ كَلَّا وَلَا ذُكِرَ الْحِمَى وَالْمَعْهَدُ", "lt": "Wulidal-ladzî laulâhu mâ ‘usyiqan-naqâ ۞ kallâ wa lâ dzukiral-ḥimâ wal-ma‘hadu", "id": "Telah lahir (Nabi) yang seandainya bukan karenanya, bukit pasir tidak akan dirindukan, dan tidak akan disebut-sebut tanah haram dan tempat-tempat kenangan.", "no": 4},
{"ar": "وُلِدَ الَّذِيْ لَوْلَاهُ مَا ذُكِرَتْ قُبَا ۞ أَصْلًا وَلَا كَانَ الْمُحَصَّبُ يُقْصَدُ", "lt": "Wulidal-ladzî laulâhu mâ dzukirat qubâ ۞ ashlan wa lâ kânal-muḥashshabu yuqshadu", "id": "Telah lahir (Nabi) yang seandainya bukan karenanya, Quba tidak akan disebut-sebut sama sekali, dan Muhashshab tidak akan dituju.", "no": 5},
{"ar": "هٰذَا الْوَفِيُّ بِعَهْدِهِ هٰذَا الَّذِيْ ۞ مَنْ قَدُّهُ يَا صَاحِ غُصْنٌ أَمْلَدُ", "lt": "Hâdzal-wafiyyu bi‘ahdihî hâdzal-ladzî ۞ man qadduhû yâ shâḥi ghushnun amladu", "id": "Inilah yang setia pada janjinya, inilah dia, wahai sahabat, yang perawakannya bagaikan dahan yang lembut.", "no": 6},
{"ar": "هٰذَا الَّذِيْ خُلِعَتْ عَلَيْهِ مَلَابِسٌ ۞ وَنَفَائِسٌ فَنَظِيْرُهُ لَا يُوْجَدُ", "lt": "Hâdzal-ladzî khuli‘at ‘alaihi malâbisun ۞ wa nafâ'isun fanadhîruhû lâ yûjadu", "id": "Inilah yang dipakaikan kepadanya busana-busana dan perhiasan-perhiasan berharga, maka tiada yang menyamainya.", "no": 7},
{"ar": "هٰذَا الَّذِيْ قَالَتْ مَلَائِكَةُ السَّمَا ۞ هٰذَا مَلِيْحُ الْكَوْنِ هٰذَا أَحْمَدُ", "lt": "Hâdzal-ladzî qâlat malâ'ikatus-samâ ۞ hâdzâ malîḥul-kauni hâdzâ aḥmadu", "id": "Inilah yang tentangnya para malaikat langit berkata: Inilah yang paling rupawan di alam semesta, inilah Ahmad.", "no": 8},
{"ar": "إِنْ كَانَ مُعْجِزُ يُوْسُفَ بِقَمِيْصِهِ ۞ تَاللهِ ذَا الْمَوْلُوْدُ مِنْهُ أَزْيَدُ", "lt": "In kâna mu‘jizu yûsufa biqamîshihî ۞ tallâhi dzal-maulûdu minhu azyadu", "id": "Jika mukjizat Yusuf ada pada bajunya, demi Allah, bayi yang lahir ini memiliki (mukjizat) yang lebih banyak darinya.", "no": 9},
{"ar": "أَوْ كَانَ إِبْرَاهِيْمُ أُعْطِيَ رُشْدَهُ ۞ تَاللهِ ذَا الْمَوْلُوْدُ مِنْهُ أَرْشَدُ", "lt": "Au kâna ibrâhîmu u‘ṭiya rusydahû ۞ tallâhi dzal-maulûdu minhu arsyadu", "id": "Atau jika Ibrahim diberi petunjuk (kebijaksanaan), demi Allah, bayi yang lahir ini lebih terbimbing darinya.", "no": 10},
{"ar": "يَا مَوْلِدَ الْمُخْتَارِ كَمْ لَكَ مِنْ ثَنَا ۞ وَمَدَائِحٍ تَعْلُوْ وَذِكْرٍ يُوْجَدُ", "lt": "Yâ maulidal-mukhtâri kam laka min tsanâ ۞ wa madâ'iḥin ta‘lû wa dzikrin yûjadu", "id": "Wahai kelahiran (Nabi) pilihan, betapa banyak pujian, sanjungan yang menjulang, dan sebutan yang ada untukmu.", "no": 11},
{"ar": "يَا عَاشِقِيْنَ تَوَلَّهُوْا فِيْ حُبِّهِ ۞ هٰذَا هُوَ الْحَسَنُ الْجَمِيْلُ الْمُفْرَدُ", "lt": "Yâ ‘âsyiqîna tawallahû fî ḥubbihî ۞ hâdzâ huwal-ḥasanul-jamîlul-mufradu", "id": "Wahai para pecinta, larutlah dalam mencintainya; inilah dia yang tampan, indah, dan tiada duanya.", "no": 12},
{"ar": "ثُمَّ الصَّلَاةُ عَلَى النَّبِيِّ وَآلِهِ ۞ فِيْ كُلِّ يَوْمٍ مَاضِيٍ وَمُجَدَّدُ", "lt": "Tsummash-shalâtu ‘alan-nabiyyi wa âlihî ۞ fî kulli yaumin mâdlin wa mujaddadu", "id": "Kemudian shalawat atas Nabi dan keluarganya, pada setiap hari yang telah lalu dan yang akan datang.", "no": 13},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 14}]},
{judul:"Kelahiran Sang Kekasih",isi:[
{"ar": "وَوَضَعَتِ الْحَبِيْبَ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مُكَحَّلُ الْعُيُوْنِ، مَقْطُوْعُ السُّرَّةِ وَمَخْتُوْنٌ", "lt": "Wa wadla‘atil-ḥabîba muḥammadan shallallâhu ‘alaihi wa sallama wa huwa mukaḥḥalul-‘uyûn, maqṭû‘us-surrati wa makhtûn", "id": "Maka ia melahirkan sang kekasih, Muhammad ﷺ, dalam keadaan matanya bercelak, tali pusarnya telah terpotong, dan telah dikhitan.", "no": 1},
{"ar": "أَخَذَتْهُ الْمَلَائِكَةُ الْأَبْرَارُ فَطَافُوْا بِهِ فِيْ جَمِيْعِ الْأَقْطَارِ، وَعَرَّفُوْا بِهِ أَهْلَ السَّمٰوَاتِ وَالْأَرْضِ وَالْبِحَارِ، وَرَجَعُوْا بِالْمُفَضَّلِ عَلَى الْكَوْنَيْنِ إِلَى أُمِّهِ آمِنَةَ فِيْ أَسْرَعَ مِنْ طَرْفَةِ عَيْنٍ", "lt": "Akhadzat-hul-malâ'ikatul-abrâru faṭâfû bihî fî jamî‘il-aqṭâr, wa ‘arrafû bihî ahlas-samâwâti wal-ardli wal-biḥâr, wa raja‘û bil-mufadldlali ‘alal-kaunaini ilâ ummihî âminata fî asra‘a min ṭarfati ‘ain", "id": "Para malaikat yang berbakti mengambilnya, lalu membawanya berkeliling ke seluruh penjuru, memperkenalkannya kepada penghuni langit, bumi, dan lautan. Kemudian mereka mengembalikan (Nabi) yang diutamakan di atas dua alam itu kepada ibunya, Aminah, lebih cepat dari sekejap mata.", "no": 2},
{"ar": "خَفَقَتْ فِي الْأَكْوَانِ أَعْلَامُ عُلُوْمِهِ، دُقَّتِ الْبَشَائِرُ لِقُدُوْمِهِ، جَاءَ الْهَنَا، زَالَ الْعَنَا، حَصَلَ الْغِنَى، نِلْنَا الْمُنَى، طَابَتِ الْقُلُوْبُ، غُفِرَتِ الذُّنُوْبُ، سُتِرَتِ الْعُيُوْبُ، كُشِفَتِ الْكُرُوْبُ، بِبَرَكَةِ سَيِّدِنَا مُحَمَّدٍ الْحَبِيْبِ الْمَحْبُوْبِ", "lt": "Khafaqat fil-akwâni a‘lâmu ‘ulûmih, duqqatil-basyâ'iru liqudûmih, jâ'al-hanâ, zâlal-‘anâ, ḥashalal-ghinâ, nilnal-munâ, ṭâbatil-qulûb, ghufiratidz-dzunûb, sutiratil-‘uyûb, kusyifatil-kurûb, bibarakati sayyidinâ muḥammadinil-ḥabîbil-maḥbûb", "id": "Berkibarlah di alam semesta panji-panji keluhurannya, ditabuh tanda-tanda kabar gembira atas kedatangannya. Kebahagiaan datang, kesusahan sirna, kecukupan tercapai, cita-cita kita raih, hati menjadi tenteram, dosa-dosa diampuni, aib-aib ditutupi, dan kesusahan-kesusahan disingkirkan, berkat junjungan kita Muhammad, kekasih yang dicintai.", "no": 3},
{"ar": "أَلْفَ صَلُّوْا عَلَى النَّبِيِّ خَاتَمِ الرُّسُلِ الْكِرَامِ", "lt": "Alfa shallû ‘alan-nabiyyi khâtamir-rusulil-kirâm", "id": "Bershalawatlah seribu kali kepada Nabi, penutup para rasul yang mulia.", "no": 4}]},
{judul:"Ahmadu Hadil-Ladzi",isi:[
{"ar": "أَحْمَدُ هَادِيْ الَّذِي الْمَوْجُوْدِ عَلَى الْأَنَامِ ۞ حَصَلَ الْقَصْدُ وَالْمُرَادُ وَصَفَى الْوَقْتُ وَالْوِدَادُ", "lt": "Aḥmadu hâdîl-ladzil-maujûdi ‘alal-anâm ۞ ḥashalal-qashdu wal-murâdu wa shafal-waqtu wal-widâd", "id": "Ahmad adalah pemberi petunjuk yang hadir bagi seluruh makhluk; (dengannya) tercapai tujuan dan maksud, dan jernihlah waktu serta kasih sayang.", "no": 1},
{"ar": "وَبِرُؤْيَا مُحَمَّدٍ فَرِحَتْ أَنْفُسُ الْعِبَادِ ۞ عَنْ غَرَامِيْ وَلَوْعَتِيْ لَا يُحَرِّكُنِي الْمَلَامُ", "lt": "Wa biru'yâ muḥammadin fariḥat anfusul-‘ibâd ۞ ‘an gharâmî wa lau‘atî lâ yuḥarrikunil-malâm", "id": "Dengan memandang Muhammad, jiwa para hamba bergembira; celaan tidak akan menggoyahkanku dari cinta dan rinduku.", "no": 2},
{"ar": "ذَاكَ دِيْنِيْ وَمِلَّتِيْ ذَاكَ لِيْ غَايَةُ الْمُرَامِ ۞ مِحْنَتِيْ فِيْهِ لَذَّتِيْ صَلْوَتِيْ لِلْهَوَى الْحَرَامِ", "lt": "Dzâka dînî wa millatî dzâka lî ghâyatul-murâm ۞ miḥnatî fîhi ladzdzatî shalwatî lil-hawal-ḥarâm", "id": "Itulah agamaku dan jalanku, itulah puncak cita-citaku; cobaanku dalam (mencintai)nya adalah kenikmatanku, dan pelipur laraku dari hawa nafsu yang haram.", "no": 3},
{"ar": "مَا فُتِنَ أَحَدٌ كَفِتْنَتِيْ فَيَسْدُوْنِيْ بِلَا كَلَامِ", "lt": "Mâ futina aḥadun kafitnatî fayasdûnî bilâ kalâm", "id": "Tidak ada seorang pun yang terpikat seperti keterpikatanku, hingga aku tak mampu berkata-kata.", "no": 4}]},
{judul:"Sakkanallahu 'Isyqati",isi:[
{"ar": "هٰذَا كَفَنِيْ مِنْ قَدِيْمِ دَهْرِيْ ۞ عَلَيْهِ عَامِيْ قَدْ مَضَى وَشَهْرِيْ", "lt": "Hâdzâ kafanî min qadîmi dahrî ۞ ‘alaihi ‘âmî qad madlâ wa syahrî", "id": "Inilah (cinta yang menjadi) kain kafanku sejak dahulu kala; untuknya telah berlalu tahun-tahun dan bulan-bulanku.", "no": 1},
{"ar": "سَكَّنَ اللهُ عِشْقَتِيْ ۞ فِيْ فُؤَادِيْ مَعَ الْعِظَامِ", "lt": "Sakkanallâhu ‘isyqatî ۞ fî fu'âdî ma‘al-‘idhâm", "id": "Allah telah menempatkan cintaku di dalam hatiku dan menyatu dengan tulang-tulangku.", "no": 2},
{"ar": "وَشَفَا سُقْمُ فُرْقَتِيْ ۞ بِالرَّشَا شَمْهَرِ الْقَوَامِ", "lt": "Wa syafâ suqmu furqatî ۞ bir-rasyâ syamharil-qawâm", "id": "Dan sembuhlah sakit perpisahanku dengan (memandang) sang kekasih yang tinggi semampai.", "no": 3},
{"ar": "مَا مُنَا قَلْبِيَ الْجَرِيْحِ ۞ غَيْرُ نَظْرَةٍ مِنَ الْحَبِيْبِ", "lt": "Mâ munâ qalbiyal-jarîḥi ۞ ghairu nadhratin minal-ḥabîbi", "id": "Tiada yang didambakan hatiku yang terluka selain satu pandangan dari sang kekasih.", "no": 4},
{"ar": "وَالْوِصَالُ مِنْ صَحِيْحٍ ۞ ذَلَّ عَلَى فَأْتِنِيْ مِنْ قَرِيْبِ", "lt": "Wal-wishâlu min shaḥîḥin ۞ dzalla ‘alâ fa'tinî min qarîbi", "id": "Pertemuan dari (cinta) yang tulus telah menunjukkan: datanglah kepadaku dari dekat.", "no": 5},
{"ar": "إِنَّ حَجِّيْ وَعُمْرَتِيْ رُؤْيَتِيْ رَوْضَةَ الْمَقَامِ", "lt": "Inna ḥajjî wa ‘umratî ru'yatî raudlatal-maqâm", "id": "Sesungguhnya haji dan umrahku adalah memandang Raudhah (makam beliau).", "no": 6},
{"ar": "هُمْ جِلَا نُوْرِ مُقْلَتِيْ ۞ وَبِهِمْ يَحْصُلُ التَّمَامُ", "lt": "Hum jilâ nûri muqlatî ۞ wa bihim yaḥshulut-tamâm", "id": "Merekalah penerang cahaya mataku, dan dengan merekalah kesempurnaan tercapai.", "no": 7},
{"ar": "قَرَّ فُؤَادِيْ فِي الْغَزَالِ الْحَرَامِ ۞ إِنْ كُنْتَ مِثْلِيْ يَا نَدِيْمُ مُوْلَعَا", "lt": "Qarra fu'âdî fil-ghazâlil-ḥarâm ۞ in kunta mitslî yâ nadîmu mûla‘â", "id": "Hatiku tenang pada kijang (kekasih) yang terlarang (untuk disakiti); jika engkau seperti aku, wahai teman, (engkau pun) tergila-gila.", "no": 8},
{"ar": "اَلْمَلِيْحُ يَفْعَلُ الْمَلِيْحَ عَاشِقَةً لَا يُحِبْ ۞ يَا نَدِيْمُ بِرَحْمَةٍ قِفْ بِنَا هٰذِهِ الْخِيَامْ", "lt": "Al-malîḥu yaf‘alul-malîḥa ‘âsyiqatan lâ yuḥib ۞ yâ nadîmu biraḥmatin qif binâ hâdzihil-khiyâm", "id": "Yang rupawan berbuat kebaikan; wahai teman, dengan kasih sayang berhentilah bersama kami di kemah-kemah ini.", "no": 9},
{"ar": "زَارَنِيْ ثُمَّ مُسْمِرِيْ وَانْقَضَتْ مُدَّةُ الْأَيَّامْ ۞ بَاتَ عِنْدِيْ مُسَامِرِيْ هٰكَذَا هٰكَذَا الْوِفَاقُ", "lt": "Zâranî tsumma musmirî wanqadlat muddatul-ayyâm ۞ bâta ‘indî musâmirî hâkadzâ hâkadzal-wifâq", "id": "Ia mengunjungiku dan menemaniku bercakap hingga habis masa yang ada; teman bercakapku bermalam di sisiku, beginilah, beginilah persatuan (hati).", "no": 10},
{"ar": "لَا بِحَوْلِيْ وَقُوَّتِيْ مَذْهَبُ الْعَجْزِ وَالسَّلَامْ ۞ وَنِلْتُ مَا أَرْجُوْهُ مِنْ سُعَادِيْ", "lt": "Lâ biḥaulî wa quwwatî madzhabul-‘ajzi was-salâm ۞ wa niltu mâ arjûhu min su‘âdî", "id": "(Semua itu) bukan karena daya dan kekuatanku; jalanku adalah mengakui kelemahan dan berserah diri. Aku pun meraih apa yang kuharapkan dari kekasihku.", "no": 11},
{"ar": "بِالْفَضْلِ وَالْإِحْسَانِ لِأَزْهَادِيْ", "lt": "Bil-fadlli wal-iḥsâni li'azhâdî", "id": "Dengan karunia dan kebaikan bagi orang-orang zuhud(ku).", "no": 12},
{"ar": "يَا إِلٰهِيْ وَسَيِّدِيْ ۞ لَا تُخَيِّبْ لَنَا الْمُرَادْ", "lt": "Yâ ilâhî wa sayyidî ۞ lâ tukhayyib lanal-murâd", "id": "Wahai Tuhanku dan Junjunganku, janganlah Engkau gagalkan harapan kami.", "no": 13},
{"ar": "يَا إِلٰهِيْ وَسَيِّدِيْ ۞ دَمِّرِ الْبَغْيَ وَالْفَسَادْ", "lt": "Yâ ilâhî wa sayyidî ۞ dammiril-baghya wal-fasâd", "id": "Wahai Tuhanku dan Junjunganku, hancurkanlah kezaliman dan kerusakan.", "no": 14},
{"ar": "يَا إِلٰهِيْ وَسَيِّدِيْ ۞ أَصْلِحِ الْأَمْرَ يَا جَوَّادْ", "lt": "Yâ ilâhî wa sayyidî ۞ ashliḥil-amra yâ jawwâd", "id": "Wahai Tuhanku dan Junjunganku, perbaikilah urusan (kami), wahai Yang Maha Pemurah.", "no": 15},
{"ar": "يَا إِلٰهِيْ بِأَحْمَدِ ۞ هَبْ بِنَصْرِهِ لَنَا الْمُرَادْ", "lt": "Yâ ilâhî bi'aḥmadi ۞ hab binashrihî lanal-murâd", "id": "Wahai Tuhanku, demi Ahmad, anugerahkanlah kepada kami apa yang kami harapkan dengan pertolongan(-Mu) melaluinya.", "no": 16},
{"ar": "يَا إِلٰهِيْ بِأَحْمَدِ ۞ أَسْقِنَا الْغَيْثَ فِي الْبِلَادْ", "lt": "Yâ ilâhî bi'aḥmadi ۞ asqinal-ghaitsa fil-bilâd", "id": "Wahai Tuhanku, demi Ahmad, turunkanlah hujan kepada kami di negeri-negeri.", "no": 17},
{"ar": "يَا إِلٰهِيْ بِأَحْمَدِ ۞ رَحْمَتَكْ تُكْرِمُ الْعِبَادْ", "lt": "Yâ ilâhî bi'aḥmadi ۞ raḥmatak tukrimul-‘ibâd", "id": "Wahai Tuhanku, demi Ahmad, (limpahkanlah) rahmat-Mu yang memuliakan para hamba.", "no": 18}]},
{judul:"Sifat Fisik Nabi",isi:[
{"ar": "رَمَقَتْ آمِنَةُ مُحَمَّدًا بِالْبَصَرِ، فَإِذَا فَرْقُهُ كَالصُّبْحِ إِذَا أَسْفَرَ، وَشَعْرُهُ كَاللَّيْلِ إِذَا سَجَى وَاعْتَكَرَ، وَوَجْهُهُ أَضْوَأُ مِنَ الشَّمْسِ وَأَنْوَرُ، أَمَا سَمِعْتَ كَيْفَ انْشَقَّ لَهُ الْقَمَرُ", "lt": "Ramaqat âminatu muḥammadan bil-bashar, fa idzâ farquhû kash-shubḥi idzâ asfar, wa sya‘ruhû kal-laili idzâ sajâ wa‘takar, wa wajhuhû adlwa'u minasy-syamsi wa anwar, amâ sami‘ta kaifansyaqqa lahul-qamar", "id": "Aminah memandang Muhammad dengan matanya; ternyata belahan rambutnya bagaikan subuh yang bersinar, rambutnya bagaikan malam yang tenang dan pekat, dan wajahnya lebih bercahaya dan lebih terang daripada matahari. Tidakkah engkau mendengar bagaimana bulan terbelah untuknya?", "no": 1},
{"ar": "أَزَجُّ الْحَاجِبَيْنِ، أَكْحَلُ الْعَيْنَيْنِ، أَقْنَى الْأَنْفِ، دَقِيْقُ الشَّفَتَيْنِ، كَأَنَّمَا يَتَبَسَّمُ عَنْ نَضِيْدِ الدُّرَرِ", "lt": "Azajjul-ḥâjibain, akḥalul-‘ainain, aqnal-anf, daqîqusy-syafatain, ka'annamâ yatabassamu ‘an nadlîdid-durar", "id": "Kedua alisnya melengkung panjang, kedua matanya hitam bagai bercelak, hidungnya mancung, kedua bibirnya tipis, seakan-akan ketika tersenyum tampak untaian mutiara.", "no": 2},
{"ar": "عُنُقُهُ كَأَنَّهُ إِبْرِيْقُ فِضَّةٍ وَقَدْ فَاقَ عَلَى جِيْدِ الْغَزَالِ، وَقَدُّهُ أَرْشَقُ مِنَ الْغُصْنِ الرَّطِيْبِ إِذَا خَطَرَ، بَيْنَ كَتِفَيْهِ خَاتَمُ النُّبُوَّةِ، فَيَا فَوْزَ مَنْ عَايَنَهُ وَنَظَرَ", "lt": "‘Unuquhû ka'annahû ibrîqu fidldlatin wa qad fâqa ‘alâ jîdil-ghazâl, wa qadduhû arsyaqu minal-ghushnir-raṭîbi idzâ khaṭar, baina katifaihi khâtamun-nubuwwah, fayâ fauza man ‘âyanahû wa nadhar", "id": "Lehernya bagaikan kendi perak, bahkan lebih indah daripada leher kijang; perawakannya lebih semampai daripada dahan yang lembut ketika bergoyang. Di antara kedua bahunya ada cap kenabian; alangkah beruntungnya orang yang menyaksikan dan memandangnya.", "no": 3},
{"ar": "فَهٰذِهِ قِطْعَةٌ مِنْ أَوْصَافِ جَمَالِهِ، وَأَمَّا كُلُّ كَمَالِهِ فَلَا يُحَدُّ لِوَاصِفٍ وَلَا يُحْصَرُ", "lt": "Fahâdzihî qiṭ‘atun min aushâfi jamâlih, wa ammâ kullu kamâlihî falâ yuḥaddu liwâshifin wa lâ yuḥshar", "id": "Inilah sepenggal dari sifat-sifat keindahannya; adapun seluruh kesempurnaannya, tidak dapat dibatasi dan dihitung oleh orang yang menyifatinya.", "no": 4},
{"ar": "فِيْ مِثْلِ حُسْنِكَ تُعْذَرُ الْعُشَّاقُ ۞ وَتَمُدُّ خَاضِعَةً لَكَ الْأَعْنَاقُ", "lt": "Fî mitsli ḥusnika tu‘dzarul-‘usysyâqu ۞ wa tamuddu khâdli‘atan lakal-a‘nâqu", "id": "Dalam (menghadapi) keindahan sepertimu, para pecinta dapat dimaklumi, dan leher-leher pun terulur tunduk kepadamu.", "no": 5},
{"ar": "قَدْ فَاقَ حُسْنُكَ لِلْوُجُوْدِ بِأَسْرِهِ ۞ حَتَّى أَضَاءَ بِنُوْرِكَ الْآفَاقُ", "lt": "Qad fâqa ḥusnuka lil-wujûdi bi'asrihî ۞ ḥattâ adlâ'a binûrikal-âfâqu", "id": "Keindahanmu telah mengungguli seluruh alam semesta, hingga cakrawala bercahaya karena cahayamu.", "no": 6}]},
{judul:"Kabar Kelahiran kepada Abdul Muthalib",isi:[
{"ar": "وَرَوَى مُحَمَّدُ بْنُ سَعْدٍ عَنْ جَمَاعَةٍ مِنْ أَهْلِ الْعِلْمِ أَنَّ آمِنَةَ لَمَّا حَمَلَتْ بِرَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: لَقَدْ عَلِقْتُ بِهِ فَمَا وَجَدْتُ لَهُ مَشَقَّةً وَلَا تَعَبًا", "lt": "Wa rawâ muḥammadubnu sa‘din ‘an jamâ‘atin min ahlil-‘ilmi anna âminata lammâ ḥamalat birasûlillâhi shallallâhu ‘alaihi wa sallama qâlat: laqad ‘aliqtu bihî famâ wajadtu lahû masyaqqatan wa lâ ta‘abâ", "id": "Muhammad bin Sa'ad meriwayatkan dari sejumlah ulama bahwa Aminah, ketika mengandung Rasulullah ﷺ, berkata: Aku telah mengandungnya, namun aku tidak merasakan kesulitan dan kelelahan karenanya.", "no": 1},
{"ar": "وَأَنَّهُ لَمَّا فُصِلَ عَنْهَا خَرَجَ مَعَهُ نُوْرٌ أَضَاءَتْ لَهُ قُصُوْرُ الشَّامِ وَمَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، وَوَقَعَ عَلَى الْأَرْضِ مُعْتَمِدًا عَلَى يَدَيْهِ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَزَادَهُ فَضْلًا وَشَرَفًا لَدَيْهِ", "lt": "Wa annahû lammâ fushila ‘anhâ kharaja ma‘ahû nûrun adlâ'at lahû qushûrusy-syâmi wa mâ bainal-masyriqi wal-maghrib, wa waqa‘a ‘alal-ardli mu‘tamidan ‘alâ yadaih, shallallâhu ‘alaihi wa sallama wa zâdahû fadllan wa syarafan ladaih", "id": "Ketika beliau lahir darinya, keluar bersamanya cahaya yang menerangi istana-istana Syam dan seluruh yang ada di antara timur dan barat. Beliau jatuh ke bumi dengan bertumpu pada kedua tangannya. Semoga Allah melimpahkan shalawat dan salam kepadanya, serta menambah keutamaan dan kemuliaannya di sisi-Nya.", "no": 2},
{"ar": "وَرَوَى يَزِيْدُ بْنُ عَبْدِ اللهِ بْنِ وَهْبٍ عَنْ عَمَّتِهِ أَنَّ آمِنَةَ لَمَّا وَضَعَتْ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَرْسَلَتْ إِلَى جَدِّهِ عَبْدِ الْمُطَّلِبِ، فَجَاءَهُ الْبَشِيْرُ وَهُوَ جَالِسٌ فِي الْحِجْرِ، فَأَخْبَرَهُ أَنَّ آمِنَةَ وَلَدَتْ غُلَامًا، فَسُرَّ بِذٰلِكَ سُرُوْرًا كَثِيْرًا", "lt": "Wa rawâ yazîdubnu ‘abdillâhibni wahbin ‘an ‘ammatihî anna âminata lammâ wadla‘at rasûlallâhi shallallâhu ‘alaihi wa sallama arsalat ilâ jaddihî ‘abdil-muṭṭalib, fajâ'ahul-basyîru wa huwa jâlisun fil-ḥijr, fa akhbarahû anna âminata waladat ghulâmâ, fasurra bidzâlika surûran katsîrâ", "id": "Yazid bin Abdullah bin Wahb meriwayatkan dari bibinya bahwa Aminah, setelah melahirkan Rasulullah ﷺ, mengirim utusan kepada kakeknya, Abdul Muthalib. Pembawa kabar gembira datang ketika ia sedang duduk di Hijr (Ismail), lalu mengabarkan bahwa Aminah telah melahirkan seorang anak laki-laki. Ia pun sangat gembira.", "no": 3},
{"ar": "وَقَامَ هُوَ وَمَنْ مَعَهُ فَدَخَلَ عَلَيْهَا فَأَخْبَرَتْهُ بِكُلِّ مَا رَأَتْهُ وَمَا قِيْلَ لَهَا وَمَا أُمِرَتْ بِهِ، فَأَخَذَهُ جَدُّهُ عَبْدُ الْمُطَّلِبِ فَأَدْخَلَهُ الْكَعْبَةَ، وَقَامَ عِنْدَهَا يَدْعُو اللهَ وَيَشْكُرُهُ عَزَّ وَجَلَّ عَلَى مَا أَعْطَاهُ", "lt": "Wa qâma huwa wa man ma‘ahû fadakhala ‘alaihâ fa akhbarat-hu bikulli mâ ra'at-hu wa mâ qîla lahâ wa mâ umirat bih, fa akhadzahû jadduhû ‘abdul-muṭṭalibi fa adkhalahul-ka‘bah, wa qâma ‘indahâ yad‘ullâha wa yasykuruhû ‘azza wa jalla ‘alâ mâ a‘ṭâh", "id": "Ia bersama orang-orang yang menyertainya bangkit dan menemui Aminah. Aminah menceritakan semua yang ia lihat, yang dikatakan kepadanya, dan yang diperintahkan kepadanya. Lalu kakeknya, Abdul Muthalib, mengambilnya dan membawanya masuk ke Ka'bah, kemudian berdiri di sana berdoa kepada Allah dan bersyukur kepada-Nya ‘Azza wa Jalla atas apa yang Dia anugerahkan kepadanya.", "no": 4},
{"ar": "وَرُوِيَ أَنَّهُ قَالَ يَوْمَئِذٍ شِعْرًا", "lt": "Wa ruwiya annahû qâla yauma'idzin syi‘râ", "id": "Diriwayatkan bahwa pada hari itu ia (Abdul Muthalib) mengucapkan syair: (Ath-Thabaqat Al-Kubra; Simthun Nujum Al-'Awali)", "no": 5},
{"ar": "صَلَّى عَلَيْكَ اللهُ يَا عَدْنَانِيْ ۞ يَا مُصْطَفَى يَا صَفْوَةَ الرَّحْمٰنِ", "lt": "Shallâ ‘alaikallâhu yâ ‘adnânî ۞ yâ mushṭafâ yâ shafwatar-raḥmâni", "id": "Semoga Allah melimpahkan shalawat kepadamu, wahai keturunan Adnan, wahai (Nabi) pilihan, wahai pilihan Ar-Rahman.", "no": 6},
{"ar": "اَلْحَمْدُ لِلّٰهِ الَّذِيْ أَعْطَانِيْ ۞ هٰذَا الْغُلَامَ الطَّيِّبَ الْأَرْدَانِ", "lt": "Al-ḥamdu lillâhil-ladzî a‘ṭânî ۞ hâdzal-ghulâmaṭ-ṭayyibal-ardâni", "id": "Segala puji bagi Allah yang telah menganugerahkan kepadaku anak laki-laki yang harum pakaiannya ini.", "no": 7},
{"ar": "قَدْ سَادَ فِي الْمَهْدِ عَلَى الْغِلْمَانِ ۞ أُعِيْذُهُ بِالْبَيْتِ ذِي الْأَرْكَانِ", "lt": "Qad sâda fil-mahdi ‘alal-ghilmâni ۞ u‘îdzuhû bil-baiti dzil-arkâni", "id": "Sejak dalam buaian ia telah mengungguli anak-anak lain; aku memohonkan perlindungan untuknya dengan (Tuhan) Baitullah yang memiliki rukun-rukun.", "no": 8},
{"ar": "حَتَّى أَرَاهُ بَالِغَ الْبُنْيَانِ ۞ أَنْتَ الَّذِيْ سُمِّيْتَ فِي الْقُرْآنِ", "lt": "Ḥattâ arâhu bâlighal-bunyâni ۞ antal-ladzî summîta fil-qur'âni", "id": "Hingga aku melihatnya tumbuh dewasa sempurna. Engkaulah yang disebut namanya di dalam Al-Qur'an,", "no": 9},
{"ar": "أَحْمَدُ مَكْتُوْبٌ عَلَى الْجِنَانِ ۞ صَلَّى عَلَيْكَ اللهُ فِي الْأَحْيَانِ", "lt": "Aḥmadu maktûbun ‘alal-jinâni ۞ shallâ ‘alaikallâhu fil-aḥyâni", "id": "(nama) Ahmad tertulis di pintu-pintu surga. Semoga Allah melimpahkan shalawat kepadamu setiap saat.", "no": 10},
{"ar": "أَحْمَدُهُ فِي السِّرِّ وَالْبُرْهَانِ ۞ حَقًّا عَلَى الْإِسْلَامِ وَالْإِيْمَانِ", "lt": "Aḥmaduhû fis-sirri wal-burhâni ۞ ḥaqqan ‘alal-islâmi wal-îmâni", "id": "Aku memuji-Nya secara rahasia dan terang-terangan, dengan sebenar-benarnya, atas (nikmat) Islam dan iman.", "no": 11},
{"ar": "يَا رَبَّنَا بِالْمُصْطَفَى الْعَدْنَانِ ۞ اغْفِرْ ذُنُوْبِيْ ثُمَّ أَصْلِحْ شَأْنِيْ", "lt": "Yâ rabbanâ bil-mushṭafal-‘adnâni ۞ ighfir dzunûbî tsumma ashliḥ sya'nî", "id": "Wahai Tuhan kami, demi (Nabi) pilihan keturunan Adnan, ampunilah dosa-dosaku, kemudian perbaikilah keadaanku.", "no": 12},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 13}]},
{judul:"Fa Subhana Man Abraza",isi:[
{"ar": "فَسُبْحَانَ مَنْ أَبْرَزَ فِيْ شَهْرِ رَبِيْعٍ الْأَوَّلِ طَلْعَةَ قَمَرِ الْوُجُوْدِ، فَمَا أَجْمَلَهَا مِنْ طَلْعَةٍ وَأَبْهَاهَا، وَمَا أَحْسَنَهَا مِنْ مَحَاسِنَ وَأَحْلَاهَا", "lt": "Fasubḥâna man abraza fî syahri rabî‘il-awwali ṭal‘ata qamaril-wujûd, famâ ajmalahâ min ṭal‘atin wa abhâhâ, wa mâ aḥsanahâ min maḥâsina wa aḥlâhâ", "id": "Maha Suci Allah yang menampakkan pada bulan Rabiul Awal terbitnya rembulan semesta; betapa indah dan cemerlang terbitnya itu, dan betapa baik serta manis keindahan-keindahannya.", "no": 1},
{"ar": "حَمَلَتْ بِهِ آمِنَةُ فَجَاءَهَا آدَمُ وَهَنَّاهَا، وَوَقَفَ نُوْحٌ عَلَى بَابِهَا وَنَادَاهَا", "lt": "Ḥamalat bihî âminatu fajâ'ahâ âdamu wa hannâhâ, wa waqafa nûḥun ‘alâ bâbihâ wa nâdâhâ", "id": "Aminah mengandungnya, maka Adam datang kepadanya dan mengucapkan selamat; Nuh berdiri di depan pintunya dan memanggilnya;", "no": 2},
{"ar": "وَأَتَاهَا الْخَلِيْلُ يُبَشِّرُهَا بِمَا أَتَاهَا، وَقَصَدَ حِلَّتَهَا مُوْسَى الْكَلِيْمُ وَسَلَّمَ عَلَيْهَا وَحَيَّاهَا، كُلُّ ذٰلِكَ لِأَجْلِ الْمَوْلُوْدِ الَّذِيْ تَشَرَّفَتْ بِهِ الْأَرْضُ وَثَرَاهَا", "lt": "Wa atâhal-khalîlu yubasysyiruhâ bimâ atâhâ, wa qashada ḥillatahâ mûsal-kalîmu wa sallama ‘alaihâ wa ḥayyâhâ, kullu dzâlika li'ajlil-maulûdil-ladzî tasyarrafat bihil-ardlu wa tsarâhâ", "id": "dan Al-Khalil (Ibrahim) datang memberinya kabar gembira atas apa yang dianugerahkan kepadanya; Musa Al-Kalim menuju tempat tinggalnya, mengucapkan salam dan penghormatan kepadanya. Semua itu demi bayi yang dengannya bumi dan tanahnya menjadi mulia.", "no": 3},
{"ar": "وَجَاءَتِ الطُّيُوْرُ مِنْ أَوْكَارِهَا وَفِنَاهَا، وَخَرَجَتِ الْحُوْرُ الْعِيْنُ وَعَلَيْهِنَّ خِلَعُ السُّرُوْرِ وَحُلَاهَا، وَهُنَّ يُنَادِيْنَ: مَا هٰذَا النُّوْرُ الَّذِيْ مَلَأَ الْبِقَاعَ وَكَسَاهَا", "lt": "Wa jâ'atiṭ-ṭuyûru min aukârihâ wa finâhâ, wa kharajatil-ḥûrul-‘înu wa ‘alaihinna khila‘us-surûri wa ḥulâhâ, wa hunna yunâdîn: mâ hâdzan-nûrul-ladzî mala'al-biqâ‘a wa kasâhâ", "id": "Burung-burung datang dari sarang dan halamannya; bidadari-bidadari keluar dengan mengenakan jubah dan perhiasan kegembiraan, seraya berseru: Cahaya apakah ini yang memenuhi dan menyelimuti seluruh penjuru?", "no": 4},
{"ar": "فَقَالَ جِبْرِيْلُ: قَدْ وُلِدَ مَنْ فَاقَ الْبَرِيَّةَ وَمَا عَدَاهَا، وَخَرَّتْ لِمَوْلِدِهِ الْأَصْنَامُ، وَهُدِمَتْ صَوَامِعُ الْكُهَّانِ وَزَالَ بِنَاهَا", "lt": "Faqâla jibrîl: qad wulida man fâqal-bariyyata wa mâ ‘adâhâ, wa kharrat limaulidihil-ashnâm, wa hudimat shawâmi‘ul-kuhhâni wa zâla binâhâ", "id": "Jibril menjawab: Telah lahir dia yang mengungguli seluruh makhluk dan selainnya. Berhala-berhala tersungkur karena kelahirannya, tempat-tempat pemujaan para dukun runtuh dan bangunannya lenyap.", "no": 5},
{"ar": "وَحَمَلَهُ جِبْرِيْلُ عَلَى يَدَيْهِ وَهُوَ يُقَبِّلُ بَيْنَ عَيْنَيْهِ، وَيَقُوْلُ لَهُ: أَنْتَ حٰمٓ، أَنْتَ يٰسٓ، أَنْتَ طٰهٰ، أَنْتَ وَلِيُّ النُّفُوْسِ الْمُؤْمِنَاتِ، أَنْتَ مَوْلَاهَا", "lt": "Wa ḥamalahû jibrîlu ‘alâ yadaihi wa huwa yuqabbilu baina ‘ainaih, wa yaqûlu lah: anta ḥâ mîm, anta yâ sîn, anta ṭâ hâ, anta waliyyun-nufûsil-mu'minât, anta maulâhâ", "id": "Jibril menggendongnya di atas kedua tangannya sambil mencium di antara kedua matanya, dan berkata kepadanya: Engkaulah Ha Mim, engkaulah Ya Sin, engkaulah Thaha; engkaulah pelindung jiwa-jiwa yang beriman, engkaulah pemimpinnya.", "no": 6}]},
{judul:"Badat Lana fi Rabi'in",isi:[
{"ar": "اَللّٰهُ اللّٰهُ اللّٰهُ اللّٰهُ اللّٰهُ اللّٰهُ ۞ اَللّٰهُ اللّٰهُ يَا خَالِقَ الْبَشَرِ", "lt": "Allâhu allâhu allâhu allâhu allâhu allâh ۞ allâhu allâhu yâ khâliqal-basyari", "id": "Allah, Allah, Allah, Allah, Allah, Allah; Allah, Allah, wahai Pencipta manusia.", "no": 1},
{"ar": "بَدَتْ لَنَا فِيْ رَبِيْعٍ طَلْعَةُ الْقَمَرِ ۞ مِنْ وَجْهِ مَنْ فَاقَ كُلَّ الْبَدْوِ وَالْحَضَرِ", "lt": "Badat lanâ fî rabî‘in ṭal‘atul-qamari ۞ min wajhi man fâqa kullal-badwi wal-ḥadlari", "id": "Di bulan Rabi' tampak bagi kami terbitnya rembulan, dari wajah dia yang mengungguli seluruh penduduk desa dan kota.", "no": 2},
{"ar": "جَلَوْهُ فِي الْكَوْنِ وَالْأَمْلَاكُ تَحْجُبُهُ ۞ فِيْ طَلْعَةِ الْحُسْنِ بَيْنَ التِّيْهِ وَالْخَفَرِ", "lt": "Jalauhu fil-kauni wal-amlâku taḥjubuhû ۞ fî ṭal‘atil-ḥusni bainat-tîhi wal-khafari", "id": "Mereka menampakkannya di alam semesta sementara para malaikat mengawalnya, dalam keindahan yang memancar antara keagungan dan rasa malu.", "no": 3},
{"ar": "وَكَانَ فِيْ مِثْلِ هٰذَا الشَّهْرِ مَوْلِدُهُ ۞ أَكْرِمْ بِمَوْلِدِ خَيْرِ الْخَلْقِ وَالْبَشَرِ", "lt": "Wa kâna fî mitsli hâdzasy-syahri mauliduhû ۞ akrim bimaulidi khairil-khalqi wal-basyari", "id": "Kelahirannya terjadi pada bulan seperti bulan ini; alangkah mulianya kelahiran makhluk dan manusia terbaik.", "no": 4},
{"ar": "تَجَمَّعَ الْحُسْنُ فِيْهِ فَهُوَ وَاحِدَةٌ ۞ جَلَوْهُ فِيْ صُوْرَةٍ فَاقَتْ عَلَى الصُّوَرِ", "lt": "Tajamma‘al-ḥusnu fîhi fahuwa wâḥidatun ۞ jalauhu fî shûratin fâqat ‘alash-shuwari", "id": "Keindahan terkumpul padanya sehingga ia tiada duanya; mereka menampakkannya dalam rupa yang mengungguli segala rupa.", "no": 5},
{"ar": "مَتَى أَرَى رَبْعَهُ يَا سَعْدُ اِسْعَ لَهُ ۞ سَعْيًا عَلَى الرَّأْسِ بَلْ سَعْيًا عَلَى الْبَصَرِ", "lt": "Matâ arâ rab‘ahû yâ sa‘du is‘a lahû ۞ sa‘yan ‘alar-ra'si bal sa‘yan ‘alal-bashari", "id": "Kapankah aku melihat kediamannya? Wahai Sa'ad, bersegeralah menujunya, berjalan dengan kepala, bahkan berjalan dengan mata.", "no": 6},
{"ar": "إِنْ لَمْ أَزُرْ قَبْرَهُ يَا سَعْدُ فِيْ عُمُرِيْ ۞ مِنْ بَعْدِ هٰذَا الْجَفَا يَا ضَيْعَةَ الْعُمُرِ", "lt": "In lam azur qabrahû yâ sa‘du fî ‘umurî ۞ min ba‘di hâdzal-jafâ yâ dlai‘atal-‘umuri", "id": "Wahai Sa'ad, jika dalam hidupku aku tidak menziarahi makamnya setelah lama berjauhan ini, alangkah sia-sianya umurku.", "no": 7},
{"ar": "تَقَسَّمَ الْحُبُّ فِيْهِ كُلَّ جَارِحَةٍ ۞ فَالْوَجْدُ لِلْقَلْبِ وَالْأَجْفَانُ لِلسَّهَرِ", "lt": "Taqassamal-ḥubbu fîhi kulla jâriḥatin ۞ fal-wajdu lil-qalbi wal-ajfânu lis-sahari", "id": "Cinta kepadanya terbagi ke seluruh anggota tubuh: kerinduan untuk hati, dan kelopak mata untuk berjaga.", "no": 8},
{"ar": "صَلَّى عَلَيْهِ إِلٰهُ الْعَرْشِ مَا صَدَحَتْ ۞ حَمَائِمُ الْوُرْقِ فِي الْآصَالِ وَالْبُكَرِ", "lt": "Shallâ ‘alaihi ilâhul-‘arsyi mâ shadaḥat ۞ ḥamâ'imul-wurqi fil-âshâli wal-bukari", "id": "Semoga Tuhan pemilik Arsy melimpahkan shalawat kepadanya selama burung-burung merpati berkicau di waktu petang dan pagi.", "no": 9},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 10}]},
{judul:"Fa Lamma Ana Awanu Maulidihi",isi:[
{"ar": "فَلَمَّا آنَ أَوَانُ مَوْلِدِهِ الْكَرِيْمِ، وَحَانَ مَقْدَمُهُ الشَّرِيْفُ الْعَظِيْمُ، صَاحَ شَاوُوْشُ الْإِشَارَةِ بِالْبِشَارَةِ لِأَهْلِ الْأَرْضِ أَجْمَعِيْنَ: ﴿وَمَا أَرْسَلْنٰكَ إِلَّا رَحْمَةً لِّلْعٰلَمِيْنَ﴾", "lt": "Falammâ âna awânu maulidihil-karîm, wa ḥâna maqdamuhusy-syarîful-‘azhîm, shâḥa syâwûsyul-isyârati bil-bisyârati li'ahlil-ardli ajma‘în: wa mâ arsalnâka illâ raḥmatal-lil-‘âlamîn", "id": "Ketika telah tiba saat kelahirannya yang mulia dan telah dekat kedatangannya yang agung lagi luhur, sang penyeru isyarat menyerukan kabar gembira kepada seluruh penduduk bumi: \"Dan tidaklah Kami mengutusmu melainkan sebagai rahmat bagi semesta alam.\" (QS. Al-Anbiya: 107)", "no": 1},
{"ar": "فَعِنْدَ ذٰلِكَ حَفَّتْ بِأُمِّهِ آمِنَةَ الْمَلَائِكَةُ الْأَبْرَارُ، تَحْجُبُهَا بِأَجْنِحَتِهَا عَنْ أَعْيُنِ الْأَغْيَارِ، فَوَقَفَ عَنْ يَمِيْنِهَا مِيْكَائِيْلُ، وَبَيْنَ يَدَيْهَا جِبْرِيْلُ، وَلَهُمْ زَجَلٌ بِالتَّسْبِيْحِ وَالتَّقْدِيْسِ وَالتَّهْلِيْلِ لِلْمَلِكِ الْجَلِيْلِ", "lt": "Fa‘inda dzâlika ḥaffat bi'ummihî âminatal-malâ'ikatul-abrâr, taḥjubuhâ bi'ajniḥatihâ ‘an a‘yunil-aghyâr, fawaqafa ‘an yamînihâ mîkâ'îl, wa baina yadaihâ jibrîl, wa lahum zajalun bit-tasbîḥi wat-taqdîsi wat-tahlîli lil-malikil-jalîl", "id": "Saat itu para malaikat yang berbakti mengelilingi ibunya, Aminah, menutupinya dengan sayap-sayap mereka dari pandangan orang lain. Mikail berdiri di sebelah kanannya dan Jibril di hadapannya, sementara mereka bergemuruh dengan tasbih, taqdis, dan tahlil kepada Raja Yang Maha Agung.", "no": 2},
{"ar": "وَأَقْبَلَتِ الْحُوْرُ الْعِيْنُ إِلَى أُمِّهِ آمِنَةَ الْكَرِيْمَةِ، تُبَشِّرُهَا بِأَنَّهَا مِنْ جَمِيْعِ الْمَخَاوِفِ آمِنَةٌ، وَتَنُوْبُ عَنِ الْقَوَابِلِ الْبَشَرِيَّةِ بِالسَّعَادَةِ الْأَبَدِيَّةِ وَالْغُرَّةِ الْقَمَرِيَّةِ وَالطَّلْعَةِ الْمُحَمَّدِيَّةِ", "lt": "Wa aqbalatil-ḥûrul-‘înu ilâ ummihî âminatal-karîmah, tubasysyiruhâ bi'annahâ min jamî‘il-makhâwifi âminah, wa tanûbu ‘anil-qawâbilil-basyariyyati bis-sa‘âdatil-abadiyyati wal-ghurratil-qamariyyati waṭ-ṭal‘atil-muḥammadiyyah", "id": "Para bidadari datang kepada ibunya yang mulia, Aminah, memberinya kabar gembira bahwa ia aman dari segala yang ditakutkan. Mereka menggantikan para bidan manusia, dengan membawa kebahagiaan abadi, wajah bercahaya laksana rembulan, dan kemunculan Muhammad.", "no": 3},
{"ar": "أَخَذَهَا الْمَخَاضُ وَاشْتَدَّ بِهَا آلَامُهُ، فَوَلَدَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَأَنَّهُ الْبَدْرُ فِيْ تَمَامِهِ", "lt": "Akhadzahal-makhâdlu wasytadda bihâ âlâmuh, fawaladatin-nabiyya shallallâhu ‘alaihi wa sallama ka'annahul-badru fî tamâmih", "id": "Rasa sakit melahirkan datang kepadanya dan nyerinya semakin kuat, lalu ia melahirkan Nabi ﷺ, seakan-akan beliau bulan purnama yang sempurna. (Di sini hadirin berdiri - Mahallul Qiyam - sebagai penghormatan dan pemuliaan kepada beliau ﷺ, karena berdiri ketika disebut kelahirannya yang mulia dianggap baik oleh para imam, baik secara riwayat maupun pandangan.)", "no": 4}]},
{judul:"Mahallul Qiyam",isi:[
{"ar": "صَلَّى اللهُ عَلَى مُحَمَّدٍ ۞ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ", "lt": "Shallallâhu ‘alâ muḥammad ۞ shallallâhu ‘alaihi wa sallam", "id": "Semoga Allah melimpahkan shalawat kepada Muhammad; semoga Allah melimpahkan shalawat dan salam kepadanya.", "no": 1},
{"ar": "بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ", "lt": "Bismillâhir-raḥmânir-raḥîm", "id": "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang.", "no": 2},
{"ar": "يَا نَبِيْ سَلَامٌ عَلَيْكَ ۞ يَا رَسُوْلْ سَلَامٌ عَلَيْكَ", "lt": "Yâ nabî salâm ‘alaika ۞ yâ rasûl salâm ‘alaika", "id": "Wahai Nabi, salam sejahtera untukmu; wahai Rasul, salam sejahtera untukmu.", "no": 3},
{"ar": "يَا حَبِيْبْ سَلَامٌ عَلَيْكَ ۞ صَلَوَاتُ اللهِ عَلَيْكَ", "lt": "Yâ ḥabîb salâm ‘alaika ۞ shalawâtullâh ‘alaika", "id": "Wahai kekasih, salam sejahtera untukmu; shalawat Allah tercurah untukmu.", "no": 4},
{"ar": "أَشْرَقَ الْبَدْرُ عَلَيْنَا ۞ فَاخْتَفَتْ مِنْهُ الْبُدُوْرُ", "lt": "Asyraqal-badru ‘alainâ ۞ fakhtafat minhul-budûr", "id": "Telah terbit bulan purnama di tengah kami, maka pudarlah purnama-purnama lain karenanya.", "no": 5},
{"ar": "مِثْلَ حُسْنِكْ مَا رَأَيْنَا ۞ قَطُّ يَا وَجْهَ السُّرُوْرِ", "lt": "Mitsla ḥusnik mâ ra'ainâ ۞ qaṭṭu yâ wajhas-surûr", "id": "Belum pernah kami melihat keindahan seperti keindahanmu, wahai wajah yang menggembirakan.", "no": 6},
{"ar": "أَنْتَ شَمْسٌ أَنْتَ بَدْرٌ ۞ أَنْتَ نُوْرٌ فَوْقَ نُوْرٍ", "lt": "Anta syamsun anta badrun ۞ anta nûrun fauqa nûr", "id": "Engkau mentari, engkau purnama; engkau cahaya di atas cahaya.", "no": 7},
{"ar": "أَنْتَ إِكْسِيْرٌ وَغَالِيْ ۞ أَنْتَ مِصْبَاحُ الصُّدُوْرِ", "lt": "Anta iksîrun wa ghâlî ۞ anta mishbâḥush-shudûr", "id": "Engkau penawar yang amat berharga; engkau pelita di dalam dada.", "no": 8},
{"ar": "يَا حَبِيْبِيْ يَا مُحَمَّدْ ۞ يَا عَرُوْسَ الْخَافِقَيْنِ", "lt": "Yâ ḥabîbî yâ muḥammad ۞ yâ ‘arûsal-khâfiqain", "id": "Wahai kekasihku, wahai Muhammad; wahai mempelai timur dan barat.", "no": 9},
{"ar": "يَا مُؤَيَّدْ يَا مُمَجَّدْ ۞ يَا إِمَامَ الْقِبْلَتَيْنِ", "lt": "Yâ mu'ayyad yâ mumajjad ۞ yâ imâmal-qiblatain", "id": "Wahai yang dikuatkan (Allah), wahai yang dimuliakan; wahai imam dua kiblat.", "no": 10},
{"ar": "مَنْ رَأَى وَجْهَكَ يَسْعَدْ ۞ يَا كَرِيْمَ الْوَالِدَيْنِ", "lt": "Man ra'â wajhaka yas‘ad ۞ yâ karîmal-wâlidain", "id": "Siapa yang melihat wajahmu pasti berbahagia, wahai yang mulia kedua orang tuanya.", "no": 11},
{"ar": "حَوْضُكَ الصَّافِي الْمُبَرَّدْ ۞ وِرْدُنَا يَوْمَ النُّشُوْرِ", "lt": "Ḥaudlukash-shâfil-mubarrad ۞ wirdunâ yauman-nusyûr", "id": "Telagamu yang jernih lagi sejuk adalah tempat minum kami pada hari kebangkitan.", "no": 12},
{"ar": "مَا رَأَيْنَا الْعِيْسَ حَنَّتْ ۞ بِالسُّرَى إِلَّا إِلَيْكَ", "lt": "Mâ ra'ainal-‘îsa ḥannat ۞ bis-surâ illâ ilaik", "id": "Tidak pernah kami melihat unta-unta rindu berjalan di malam hari melainkan menuju kepadamu.", "no": 13},
{"ar": "وَالْغَمَامَةُ قَدْ أَظَلَّتْ ۞ وَالْمَلَا صَلَّوْا عَلَيْكَ", "lt": "Wal-ghamâmatu qad azhallat ۞ wal-malâ shallau ‘alaik", "id": "Awan telah menaungimu, dan para pembesar bershalawat kepadamu.", "no": 14},
{"ar": "وَأَتَاكَ الْعُوْدُ يَبْكِيْ ۞ وَتَذَلَّلْ بَيْنَ يَدَيْكَ", "lt": "Wa atâkal-‘ûdu yabkî ۞ wa tadzallal baina yadaik", "id": "Batang kayu datang kepadamu sambil menangis dan merendahkan diri di hadapanmu.", "no": 15},
{"ar": "وَاسْتَجَارَتْ يَا حَبِيْبِيْ ۞ عِنْدَكَ الظَّبْيُ النَّفُوْرُ", "lt": "Wastajârat yâ ḥabîbî ۞ ‘indakazh-zhabyun-nafûr", "id": "Wahai kekasihku, kijang yang mudah lari pun meminta perlindungan kepadamu.", "no": 16},
{"ar": "عِنْدَمَا شَدُّوا الْمَحَامِلْ ۞ وَتَنَادَوْا لِلرَّحِيْلِ", "lt": "‘Indamâ syaddul-maḥâmil ۞ wa tanâdau lir-raḥîl", "id": "Ketika mereka mengikat tandu-tandu dan saling memanggil untuk berangkat,", "no": 17},
{"ar": "جِئْتُهُمْ وَالدَّمْعُ سَائِلْ ۞ قُلْتُ قِفْ لِيْ يَا دَلِيْلُ", "lt": "Ji'tuhum wad-dam‘u sâ'il ۞ qultu qif lî yâ dalîl", "id": "aku mendatangi mereka dengan air mata berlinang, dan aku berkata: Berhentilah untukku, wahai penunjuk jalan,", "no": 18},
{"ar": "وَتَحَمَّلْ لِيْ رَسَائِلْ ۞ أَيُّهَا الشَّوْقُ الْجَزِيْلُ", "lt": "Wa taḥammal lî rasâ'il ۞ ayyuhasy-syauqul-jazîl", "id": "dan bawalah pesan-pesanku, wahai kerinduan yang mendalam,", "no": 19},
{"ar": "نَحْوَ هَاتِيْكَ الْمَنَازِلْ ۞ فِي الْعَشِيِّ وَالْبُكُوْرِ", "lt": "Naḥwa hâtîkal-manâzil ۞ fil-‘asyiyyi wal-bukûr", "id": "menuju tempat-tempat tinggal itu, di waktu petang dan pagi.", "no": 20},
{"ar": "كُلُّ مَنْ فِي الْكَوْنِ هَامُوْا ۞ فِيْكَ يَا بَاهِي الْجَبِيْنِ", "lt": "Kullu man fil-kauni hâmû ۞ fîka yâ bâhil-jabîn", "id": "Semua yang ada di alam semesta tergila-gila kepadamu, wahai yang bercahaya dahinya.", "no": 21},
{"ar": "وَلَهُمْ فِيْكَ غَرَامٌ ۞ وَاشْتِيَاقٌ وَحَنِيْنٌ", "lt": "Wa lahum fîka gharâmun ۞ wasytiyâqun wa ḥanîn", "id": "Mereka memiliki cinta yang mendalam kepadamu, kerinduan, dan dambaan.", "no": 22},
{"ar": "فِيْ مَعَانِيْكَ الْأَنَامُ ۞ قَدْ تَبَدَّتْ حَائِرِيْنَ", "lt": "Fî ma‘ânîkal-anâmu ۞ qad tabaddat ḥâ'irîn", "id": "Dalam memahami keistimewaanmu, umat manusia tampak kebingungan.", "no": 23},
{"ar": "أَنْتَ لِلرُّسْلِ خِتَامُ ۞ أَنْتَ لِلْمَوْلَى شَكُوْرُ", "lt": "Anta lir-rusli khitâmu ۞ anta lil-maulâ syakûr", "id": "Engkau penutup para rasul; engkau hamba yang sangat bersyukur kepada Tuhan.", "no": 24},
{"ar": "عَبْدُكَ الْمِسْكِيْنُ يَرْجُوْ ۞ فَضْلَكَ الْجَمَّ الْغَفِيْرَ", "lt": "‘Abdukal-miskînu yarjû ۞ fadllakal-jammal-ghafîr", "id": "Hambamu yang papa ini mengharapkan karuniamu yang melimpah ruah.", "no": 25},
{"ar": "فِيْكَ قَدْ أَحْسَنْتُ ظَنِّيْ ۞ يَا بَشِيْرُ يَا نَذِيْرُ", "lt": "Fîka qad aḥsantu zhannî ۞ yâ basyîru yâ nadzîr", "id": "Kepadamu aku telah berbaik sangka, wahai pembawa kabar gembira, wahai pemberi peringatan.", "no": 26},
{"ar": "فَأَغِثْنِيْ وَأَجِرْنِيْ ۞ يَا مُجِيْرُ مِنَ السَّعِيْرِ", "lt": "Fa aghitsnî wa ajirnî ۞ yâ mujîru minas-sa‘îr", "id": "Maka tolonglah aku dan lindungilah aku, wahai pelindung dari api neraka Sa'ir.", "no": 27},
{"ar": "يَا غِيَاثِيْ يَا مَلَاذِيْ ۞ فِيْ مُهِمَّاتِ الْأُمُوْرِ", "lt": "Yâ ghiyâtsî yâ malâdzî ۞ fî muhimmâtil-umûr", "id": "Wahai penolongku, wahai tempat berlindungku dalam urusan-urusan yang genting.", "no": 28},
{"ar": "سَعِدَ عَبْدٌ قَدْ تَمَلَّى ۞ وَانْجَلَى عَنْهُ الْحَزِيْنُ", "lt": "Sa‘ida ‘abdun qad tamallâ ۞ wanjalâ ‘anhul-ḥazîn", "id": "Berbahagialah hamba yang telah puas memandangmu, dan sirnalah kesedihan darinya.", "no": 29},
{"ar": "فِيْكَ يَا بَدْرٌ تَجَلَّى ۞ فَلَكَ الْوَصْفُ الْحَسِيْنُ", "lt": "Fîka yâ badrun tajallâ ۞ falakal-washful-ḥasîn", "id": "Padamu, wahai purnama, (keindahan) tampak nyata, maka bagimu sifat-sifat yang indah.", "no": 30},
{"ar": "لَيْسَ أَزْكَى مِنْكَ أَصْلًا ۞ قَطُّ يَا جَدَّ الْحُسَيْنِ", "lt": "Laisa azkâ minka ashlan ۞ qaṭṭu yâ jaddal-ḥusain", "id": "Sama sekali tidak ada yang lebih suci asal-usulnya daripadamu, wahai kakek Al-Husain.", "no": 31},
{"ar": "فَعَلَيْكَ اللهُ صَلَّى ۞ دَائِمًا طُوْلَ الدُّهُوْرِ", "lt": "Fa ‘alaikallâhu shallâ ۞ dâ'iman ṭûlad-duhûr", "id": "Semoga Allah melimpahkan shalawat kepadamu selamanya sepanjang masa.", "no": 32},
{"ar": "يَا وَلِيَّ الْحَسَنَاتِ ۞ يَا رَفِيْعَ الدَّرَجَاتِ", "lt": "Yâ waliyyal-ḥasanât ۞ yâ rafî‘ad-darajât", "id": "Wahai Pemilik segala kebaikan, wahai Yang Maha Tinggi derajat-Nya,", "no": 33},
{"ar": "كَفِّرْ عَنِّي الذُّنُوْبَ ۞ وَاغْفِرْ عَنِّي السَّيِّئَاتِ", "lt": "Kaffir ‘annidz-dzunûb ۞ waghfir ‘annis-sayyi'ât", "id": "hapuskanlah dosa-dosaku dan ampunilah kesalahan-kesalahanku.", "no": 34},
{"ar": "أَنْتَ غَفَّارُ الْخَطَايَا ۞ وَالذُّنُوْبِ الْمُوْبِقَاتِ", "lt": "Anta ghaffârul-khaṭâyâ ۞ wadz-dzunûbil-mûbiqât", "id": "Engkau Maha Pengampun segala kesalahan dan dosa-dosa yang membinasakan.", "no": 35},
{"ar": "أَنْتَ سَتَّارُ الْمَسَاوِيْ ۞ وَمُقِيْلُ الْعَثَرَاتِ", "lt": "Anta sattârul-masâwî ۞ wa muqîlul-‘atsarât", "id": "Engkau penutup segala keburukan dan pemaaf segala ketergelinciran.", "no": 36},
{"ar": "عَالِمُ السِّرِّ وَأَخْفَى ۞ مُسْتَجِيْبُ الدَّعَوَاتِ", "lt": "‘Âlimus-sirri wa akhfâ ۞ mustajîbud-da‘awât", "id": "Engkau mengetahui yang rahasia dan yang lebih tersembunyi, Engkau pengabul segala doa.", "no": 37},
{"ar": "رَبِّ فَارْحَمْنَا جَمِيْعًا ۞ وَامْحُ عَنَّا السَّيِّئَاتِ", "lt": "Rabbi farḥamnâ jamî‘an ۞ wamḥu ‘annas-sayyi'ât", "id": "Wahai Tuhanku, rahmatilah kami semua dan hapuskanlah keburukan-keburukan kami.", "no": 38},
{"ar": "رَبِّ فَارْحَمْنَا جَمِيْعًا ۞ بِجَمِيْعِ الصَّالِحَاتِ", "lt": "Rabbi farḥamnâ jamî‘an ۞ bijamî‘ish-shâliḥât", "id": "Wahai Tuhanku, rahmatilah kami semua dengan seluruh amal saleh.", "no": 39},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 40}]},
{judul:"Fa Lamma Asyraqa Nuruhu",isi:[
{"ar": "فَلَمَّا أَشْرَقَ نُوْرُهُ فِي الْوُجُوْدِ، أَذْعَنَ اللهَ بِالسُّجُوْدِ، وَلَمْ يُخْلَقْ مِثْلَهُ مَوْلُوْدٌ، ثُمَّ أَوْمَى بِإِصْبَعِهِ إِلَى السَّمَاءِ، فَوُلِدَ مَخْتُوْنًا مُكَحَّلًا مَدْهُوْنًا، مُعَطَّرًا مُكَرَّمًا", "lt": "Falammâ asyraqa nûruhû fil-wujûd, adz‘anallâha bis-sujûd, wa lam yukhlaq mitsluhû maulûd, tsumma aumâ bi'ishba‘ihî ilas-samâ', fawulida makhtûnan mukaḥḥalan madhûnâ, mu‘aṭṭaran mukarramâ", "id": "Ketika cahayanya telah memancar di alam wujud, beliau tunduk kepada Allah dengan bersujud; tidak pernah diciptakan bayi yang menyamainya. Kemudian beliau berisyarat dengan jarinya ke langit. Beliau lahir dalam keadaan sudah dikhitan, bercelak, berminyak, harum, dan dimuliakan.", "no": 1},
{"ar": "وَخَرَجَ مِنْ ثَغْرِهِ نُوْرٌ أَضَاءَ لَهُ قُصُوْرُ بُصْرَى مِنْ أَرْضِ الشَّامِ، وَخَرَّتْ لِهَيْبَتِهِ جَمِيْعُ الصُّلْبَانِ وَالْأَصْنَامِ، وَأَصْبَحَ كُلُّ جَبَّارٍ بَعْدَ عِزَّتِهِ ذَلِيْلًا، وَمُنِعَتِ الشَّيَاطِيْنُ أَنْ تَسْتَرِقَ السَّمْعَ فَلَمْ تَجِدْ بَعْدَ ذٰلِكَ إِلَى السَّمَاءِ وُصُوْلًا", "lt": "Wa kharaja min tsaghrihî nûrun adlâ'a lahû qushûru bushrâ min ardlisy-syâm, wa kharrat lihaibatihî jamî‘ush-shulbâni wal-ashnâm, wa ashbaḥa kullu jabbârin ba‘da ‘izzatihî dzalîlâ, wa muni‘atisy-syayâṭînu an tastariqas-sam‘a falam tajid ba‘da dzâlika ilas-samâ'i wushûlâ", "id": "Dari mulutnya keluar cahaya yang menerangi istana-istana Bushra di negeri Syam. Seluruh salib dan berhala tersungkur karena kewibawaannya; setiap penguasa yang sewenang-wenang menjadi hina setelah kejayaannya; dan setan-setan dicegah mencuri dengar (berita langit), sehingga sesudah itu mereka tidak lagi menemukan jalan ke langit.", "no": 2},
{"ar": "فَلَمَّا بَدَتْ أَنْوَارُ غُرَّتِهِ الْبَهِيَّةِ، وَأَشْرَقَتْ شَمْسُ طَلْعَتِهِ الْعُلْوِيَّةِ، أَضَاءَتْ بِمَوْلِدِهِ ظُلَمُ الْحَنَادِسِ، وَانْشَقَّ إِيْوَانُ كِسْرَى، وَخَمَدَتْ نَارُ فَارِسَ، وَكُسِرَتِ الصُّلْبَانُ تَعْظِيْمًا لِقُدُوْمِهِ وَتَوْقِيْرًا", "lt": "Falammâ badat anwâru ghurratihil-bahiyyah, wa asyraqat syamsu ṭal‘atihil-‘ulwiyyah, adlâ'at bimaulidihî zhulamul-ḥanâdis, wansyaqqa îwânu kisrâ, wa khamadat nâru fâris, wa kusirat ash-shulbânu ta‘zhîman liqudûmihî wa tauqîrâ", "id": "Ketika cahaya wajahnya yang cemerlang tampak dan mentari kemunculannya yang luhur terbit, kegelapan malam yang pekat menjadi terang karena kelahirannya. Istana Kisra retak, api Persia padam, dan salib-salib patah sebagai pengagungan dan penghormatan atas kedatangannya.", "no": 3},
{"ar": "وَنَادَى الْمُنَادِيْ فِي الْأَكْوَانِ تَنْبِيْهًا لِأُمَّتِهِ عَلَى كَرَامَتِهِ وَتَذْكِيْرًا: ﴿يٰٓأَيُّهَا النَّبِيُّ إِنَّآ أَرْسَلْنٰكَ شَاهِدًا وَّمُبَشِّرًا وَّنَذِيْرًا ۝ وَّدَاعِيًا إِلَى اللّٰهِ بِإِذْنِهٖ وَسِرَاجًا مُّنِيْرًا ۝ وَبَشِّرِ الْمُؤْمِنِيْنَ بِأَنَّ لَهُمْ مِّنَ اللّٰهِ فَضْلًا كَبِيْرًا﴾", "lt": "Wa nâdal-munâdî fil-akwâni tanbîhan li'ummatihî ‘alâ karâmatihî wa tadzkîrâ: yâ ayyuhan-nabiyyu innâ arsalnâka syâhidan wa mubasysyiran wa nadzîrâ, wa dâ‘iyan ilallâhi bi'idznihî wa sirâjan munîrâ, wa basysyiril-mu'minîna bi'anna lahum minallâhi fadllan kabîrâ", "id": "Penyeru berseru di seluruh alam untuk mengingatkan umatnya akan kemuliaannya: \"Wahai Nabi, sesungguhnya Kami mengutusmu sebagai saksi, pembawa kabar gembira, dan pemberi peringatan; sebagai penyeru kepada Allah dengan izin-Nya dan sebagai pelita yang menerangi. Dan sampaikanlah kabar gembira kepada orang-orang mukmin bahwa mereka akan memperoleh karunia yang besar dari Allah.\" (QS. Al-Ahzab: 45-47)", "no": 4},
{"ar": "فَلَكُمْ لَهُ مِنْ آيَةٍ مَشْهُوْرَةٍ ۞ نَصُّ الْكِتَابِ بِهَا غَدَا مَشْهُوْرَا", "lt": "Falakum lahû min âyatin masyhûratin ۞ nashshul-kitâbi bihâ ghadâ masyhûrâ", "id": "Betapa banyak tanda kenabian yang masyhur padanya, yang dengannya nash Al-Qur'an menjadi terkenal.", "no": 5},
{"ar": "خَمِدَتْ لَهُ نَارُ الْمَجُوْسِ وَنُكِّسَتْ ۞ أَصْنَامُهُمْ وَدَعَوْا هُنَاكَ ثُبُوْرَا", "lt": "Khamidat lahû nârul-majûsi wa nukkisat ۞ ashnâmuhum wa da‘au hunâka tsubûrâ", "id": "Karenanya api kaum Majusi padam dan berhala-berhala mereka terjungkal, dan di sana mereka meratapi kebinasaan.", "no": 6},
{"ar": "وَأَتَى يُبَشِّرُهَا بِالْهِدَايَةِ وَالتُّقَى ۞ فَلِذَاكَ يُدْعَى هَادِيًا وَبَشِيْرَا", "lt": "Wa atâ yubasysyiruhâ bil-hidâyati wat-tuqâ ۞ falidzâka yud‘â hâdiyan wa basyîrâ", "id": "Beliau datang membawa kabar gembira berupa hidayah dan takwa, karena itu beliau disebut pemberi petunjuk dan pembawa kabar gembira.", "no": 7},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَزِدْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa zid wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, tambahan (rahmat), dan keberkahan kepadanya.", "no": 8}]},
{judul:"Wa Lamma Wulida: Penyusuan",isi:[
{"ar": "وَلَمَّا وُلِدَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَأَلَ الْوَحْشُ وَالطَّيْرُ رِضَاعَهُ، وَسَأَلَتِ الْمَلَائِكَةُ تَرْبِيَتَهُ", "lt": "Wa lammâ wulida shallallâhu ‘alaihi wa sallama sa'alal-waḥsyu waṭ-ṭairu ridlâ‘ah, wa sa'alatil-malâ'ikatu tarbiyatah", "id": "Ketika beliau ﷺ lahir, binatang buas dan burung-burung meminta untuk menyusuinya, dan para malaikat meminta untuk mengasuhnya.", "no": 1},
{"ar": "فَقَالَ اللهُ عَزَّ وَجَلَّ: أَنَا قَادِرٌ أَنْ أُرَبِّيَهُ مِنْ غَيْرِ رِضَاعٍ وَلَا سَبَبٍ، وَلٰكِنْ سَبَقَتْ كَلِمَتِيْ وَتَمَّتْ حِكْمَتِيْ، وَكَتَبْتُ عَلَى نَفْسِيْ فِي الْأَزَلِ أَنْ لَا يُرْضِعَ هٰذِهِ الْجَوْهَرَةَ الْيَتِيْمَةَ غَيْرُ أَمَتِيْ حَلِيْمَةَ", "lt": "Faqâlallâhu ‘azza wa jalla: ana qâdirun an urabbiyahû min ghairi ridlâ‘in wa lâ sabab, wa lâkin sabaqat kalimatî wa tammat ḥikmatî, wa katabtu ‘alâ nafsî fil-azali an lâ yurdli‘a hâdzihil-jauharatal-yatîmata ghairu amatî ḥalîmah", "id": "Maka Allah ‘Azza wa Jalla berfirman: Aku mampu mengasuhnya tanpa susuan dan tanpa perantara apa pun. Akan tetapi, firman-Ku telah mendahului dan hikmah-Ku telah sempurna; Aku telah menetapkan atas diri-Ku sejak azali bahwa tidak ada yang menyusui permata yatim ini selain hamba-Ku, Halimah.", "no": 2}]},
{judul:"Shalatullah 'alal-Hadi Muhammad",isi:[
{"ar": "حَبِيْبِيْ يَا حَبِيْبِيْ يَا طَبِيْبِيْ ۞ حَبِيْبِيْ أَنْتَ قَصْدِيْ وَمُرَادِيْ", "lt": "Ḥabîbî yâ ḥabîbî yâ ṭabîbî ۞ ḥabîbî anta qashdî wa murâdî", "id": "Kekasihku, wahai kekasihku, wahai penawar (sakit)ku; kekasihku, engkaulah tujuan dan dambaanku.", "no": 1},
{"ar": "صَلَاةُ اللهِ عَلَى الْهَادِيْ مُحَمَّدْ ۞ شَفِيْعِ الْخَلْقِ فِيْ يَوْمِ الْقِيَامَةِ", "lt": "Shalâtullâhi ‘alal-hâdî muḥammad ۞ syafî‘il-khalqi fî yaumil-qiyâmah", "id": "Shalawat Allah semoga tercurah kepada sang pemberi petunjuk, Muhammad, pemberi syafaat bagi makhluk pada hari kiamat.", "no": 2},
{"ar": "فَطُرْقُ الْوَصْلِ أَضْحَتْ مُسْتَقِيْمَةً ۞ وَأَسْرَارُ الْهَوَى عِنْدِيْ مُقِيْمَةٌ", "lt": "Faṭurqul-washli adlḥat mustaqîmatan ۞ wa asrârul-hawâ ‘indî muqîmah", "id": "Jalan-jalan menuju pertemuan telah menjadi lurus, dan rahasia-rahasia cinta tetap tinggal padaku.", "no": 3},
{"ar": "فَلَا تَخْشَى صُدُوْدًا مِنْ حَبِيْبٍ ۞ لَهُ نِعَمٌ بِمَا أَوْلَى عَمِيْمَةٌ", "lt": "Falâ takhsyâ shudûdan min ḥabîbin ۞ lahû ni‘amun bimâ aulâ ‘amîmah", "id": "Janganlah takut berpaling dari kekasih yang memiliki nikmat-nikmat merata atas apa yang ia berikan.", "no": 4},
{"ar": "إِذَا زَلَّاتُ عَبْدٍ بَاعَدَتْهُ ۞ تُقَرِّبُهُ عَوَاطِفُهُ الرَّحِيْمَةُ", "lt": "Idzâ zallâtu ‘abdin bâ‘adat-hu ۞ tuqarribuhû ‘awâṭifuhur-raḥîmah", "id": "Apabila kesalahan-kesalahan seorang hamba menjauhkannya, kasih sayangnya yang penuh rahmat akan mendekatkannya.", "no": 5},
{"ar": "وَإِنْ عَثَرَ الْعَجُوْلُ بِسُوْءِ فِعْلٍ ۞ يُلَاطِفُهُ بِأَوْصَافٍ كَرِيْمَةٍ", "lt": "Wa in ‘atsaral-‘ajûlu bisû'i fi‘lin ۞ yulâṭifuhû bi'aushâfin karîmah", "id": "Jika orang yang tergesa-gesa tergelincir karena perbuatan buruk, beliau memperlakukannya dengan lembut melalui sifat-sifatnya yang mulia.", "no": 6},
{"ar": "وَإِنْ يَشْكُ الْغَرَامَ حَلِيْفُ شَوْقٍ ۞ يُقَرِّبُهُ وَيَجْعَلُهُ نَدِيْمَةً", "lt": "Wa in yasykul-gharâma ḥalîfu syauqin ۞ yuqarribuhû wa yaj‘aluhû nadîmah", "id": "Jika orang yang dilanda rindu mengadukan cintanya, beliau mendekatkannya dan menjadikannya teman karibnya.", "no": 7},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَزِدْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa zid wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, tambahan (rahmat), dan keberkahan kepadanya.", "no": 8}]},
{judul:"Halimah As-Sa'diyyah",isi:[
{"ar": "قَالَ أَهْلُ السِّيَرِ رَضِيَ اللهُ عَنْهُمْ: وَكَانَ أَهْلُ مَكَّةَ مِنْ عَادَاتِهِمْ أَنْ يُخْرِجُوْا بِالْأَطْفَالِ إِلَى الْمَرَاضِعِ", "lt": "Qâla ahlus-siyari radliyallâhu ‘anhum: wa kâna ahlu makkata min ‘âdâtihim an yukhrijû bil-aṭfâli ilal-marâdli‘", "id": "Para ahli sejarah (sirah) - semoga Allah meridai mereka - berkata: Termasuk kebiasaan penduduk Makkah adalah membawa bayi-bayi mereka kepada para ibu susu.", "no": 1},
{"ar": "قَالَتْ حَلِيْمَةُ: فَأَصَابَتْنَا فِيْ بَنِيْ سَعْدٍ سَنَةٌ مُغْلِيَةٌ لِعَدَمِ الْغَيْثِ، فَجِئْنَا إِلَى مَكَّةَ نَحْوُ أَرْبَعِيْنَ امْرَأَةً، مَعَ كُلِّ امْرَأَةٍ مِنَّا بَعْلُهَا، نَلْتَمِسُ الرُّضَعَاءَ", "lt": "Qâlat ḥalîmah: fa ashâbatnâ fî banî sa‘din sanatun mughliyatun li‘adamil-ghaits, faji'nâ ilâ makkata naḥwu arba‘îna imra'ah, ma‘a kullimra'atin minnâ ba‘luhâ, naltamisur-rudla‘â'", "id": "Halimah berkata: Kami di Bani Sa'd tertimpa tahun paceklik karena tidak turun hujan. Kami, sekitar empat puluh perempuan, datang ke Makkah; setiap perempuan disertai suaminya, untuk mencari bayi-bayi yang akan disusui.", "no": 2},
{"ar": "وَخَرَجَ أَهْلُ مَكَّةَ بِأَطْفَالِهِمْ إِلَى الْمَرَاضِعِ، فَوَضَعُوْهُمْ حَوْلَ الْكَعْبَةِ، فَسَبَقَتْنِي النِّسَاءُ إِلَى كُلِّ رَضِيْعٍ بِمَكَّةَ، وَتَأَخَّرْتُ أَنَا لِضَعْفِيْ وَضَعْفِ أَتَانِيْ وَقِلَّةِ سَيْرِهَا، وَجِئْتُ أَنَا فَلَمْ أَجِدْ شَيْئًا مِنَ الرُّضَعَاءِ", "lt": "Wa kharaja ahlu makkata bi'aṭfâlihim ilal-marâdli‘, fawadla‘ûhum ḥaulal-ka‘bah, fasabaqatnin-nisâ'u ilâ kulli radlî‘in bimakkah, wa ta'akhkhartu ana lidla‘fî wa dla‘fi atânî wa qillati sairihâ, wa ji'tu ana falam ajid syai'an minar-rudla‘â'", "id": "Penduduk Makkah keluar membawa bayi-bayi mereka kepada para ibu susu dan meletakkan mereka di sekitar Ka'bah. Para perempuan lain mendahuluiku mendapatkan setiap bayi di Makkah, sedangkan aku terlambat karena kelemahanku, lemahnya keledaiku, dan lambat jalannya. Ketika aku datang, aku tidak menemukan seorang bayi pun.", "no": 3},
{"ar": "وَسَمِعَتْ آمِنَةُ بِقُدُوْمِنَا، فَقَالَتْ لِعَبْدِ الْمُطَّلِبِ: انْظُرْ لِمَوْلُوْدِكَ هٰذَا مُرْضِعَةً مِنْ بَنِيْ سَعْدٍ، فَقَدْ قَدِمَ الْمَرَاضِعُ السَّعْدِيَّاتُ، انْظُرْ لِمَوْلُوْدِكَ مُرْضِعَةً مِنْ أَشْرَفِ الْبَرِيَّاتِ", "lt": "Wa sami‘at âminatu biqudûminâ, faqâlat li‘abdil-muṭṭalib: unzhur limaulûdika hâdzâ murdli‘atan min banî sa‘d, faqad qadimal-marâdli‘us-sa‘diyyât, unzhur limaulûdika murdli‘atan min asyrafil-bariyyât", "id": "Aminah mendengar kedatangan kami, lalu berkata kepada Abdul Muthalib: Carikanlah untuk bayimu ini seorang ibu susu dari Bani Sa'd, karena para ibu susu dari Bani Sa'd telah datang. Carikanlah untuk bayimu ibu susu dari makhluk yang paling mulia.", "no": 4},
{"ar": "فَخَرَجَ عَبْدُ الْمُطَّلِبِ، فَبَيْنَمَا هُوَ يَمْشِيْ إِذْ سَمِعَ هَاتِفًا يَقُوْلُ لَهُ: انْظُرْ حَلِيْمَةَ السَّعْدِيَّةَ", "lt": "Fakharaja ‘abdul-muṭṭalib, fabainamâ huwa yamsyî idz sami‘a hâtifan yaqûlu lah: unzhur ḥalîmatas-sa‘diyyah", "id": "Abdul Muthalib pun keluar. Ketika ia sedang berjalan, tiba-tiba ia mendengar suara tanpa rupa berkata kepadanya: Carilah Halimah As-Sa'diyyah.", "no": 5},
{"ar": "تُرْضِعُ ابْنَ آمِنَةَ الْأَمِيْنَةِ مُحَمَّدًا ۞ خَيْرَ الْأَنَامِ وَصَفْوَةَ الْجَبَّارِ", "lt": "Turdli‘ubna âminatal-amînati muḥammadan ۞ khairal-anâmi wa shafwatal-jabbâri", "id": "Dialah yang akan menyusui putra Aminah yang terpercaya, yakni Muhammad, manusia terbaik dan pilihan Allah Yang Maha Perkasa.", "no": 6},
{"ar": "فَمَا لَهُ إِلَّا حَلِيْمَةُ مُرْضِعَةٌ ۞ نِعْمَ النَّبِيُّ الْمُصْطَفَى الْمُخْتَارُ", "lt": "Famâ lahû illâ ḥalîmatu murdli‘atun ۞ ni‘man-nabiyyul-mushṭafal-mukhtâru", "id": "Tiada ibu susu baginya selain Halimah; sebaik-baik nabi adalah dia yang terpilih lagi diutamakan.", "no": 7},
{"ar": "لَا تُسَلِّمُوْهُ إِلَى سِوَاهَا إِنَّهُ ۞ أَمْرٌ وَحُكْمٌ جَاءَ مِنْ قَهَّارِ", "lt": "Lâ tusallimûhu ilâ siwâhâ innahû ۞ amrun wa ḥukmun jâ'a min qahhâri", "id": "Janganlah kalian serahkan dia kepada selain Halimah, karena itu adalah perintah dan ketetapan yang datang dari Allah Yang Maha Perkasa. (Subulul Huda war-Rasyad, Imam Ash-Shalihi Asy-Syami)", "no": 8},
{"ar": "قَالَتْ حَلِيْمَةُ السَّعْدِيَّةُ: ثُمَّ إِنِّيْ مَرَرْتُ بِعَبْدِ الْمُطَّلِبِ، فَسَأَلْتُهُ عَنْ رَضِيْعٍ، فَقَالَ لِيْ: مَا اسْمُكِ وَمَا عَرَبُكِ؟ فَقُلْتُ: اسْمِيْ حَلِيْمَةُ السَّعْدِيَّةُ، فَتَبَسَّمَ ضَاحِكًا وَتَهَلَّلَ وَجْهُهُ فَرَحًا، فَقَالَ: بَخٍ بَخٍ لَكِ يَا حَلِيْمَةُ السَّعْدِيَّةُ، هَلْ لَكِ فِيْ إِرْضَاعِ غُلَامٍ يَتِيْمٍ تَسْعَدِيْنَ بِهِ إِنْ شَاءَ اللهُ تَعَالَى", "lt": "Qâlat ḥalîmatus-sa‘diyyah: tsumma innî marartu bi‘abdil-muṭṭalib, fasa'altuhû ‘an radlî‘, faqâla lî: masmuki wa mâ ‘arabuki? Faqultu: ismî ḥalîmatus-sa‘diyyah, fatabassama dlâḥikan wa tahallala wajhuhû faraḥâ, faqâla: bakhin bakhin laki yâ ḥalîmatus-sa‘diyyah, hal laki fî irdlâ‘i ghulâmin yatîmin tas‘adîna bihî in syâ'allâhu ta‘âlâ", "id": "Halimah As-Sa'diyyah berkata: Kemudian aku melewati Abdul Muthalib dan bertanya kepadanya tentang bayi yang akan disusui. Ia bertanya kepadaku: Siapa namamu dan dari kabilah mana engkau? Aku menjawab: Namaku Halimah As-Sa'diyyah. Ia pun tersenyum hingga tertawa dan wajahnya berseri-seri gembira, lalu berkata: Bagus, bagus sekali untukmu, wahai Halimah As-Sa'diyyah. Maukah engkau menyusui seorang anak yatim yang dengannya engkau akan berbahagia, insya Allah Ta'ala?", "no": 9},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 10},
{"ar": "فَازَتْ حَلِيْمَةُ مِنْ رِضَاعِ مُحَمَّدٍ ۞ خَيْرِ الْوَرَى طُرًّا بِأَعْظَمِ مَقْصَدِ", "lt": "Fâzat ḥalîmatu min ridlâ‘i muḥammadin ۞ khairil-warâ ṭurran bi'a‘zhami maqshadi", "id": "Halimah beruntung karena menyusui Muhammad, makhluk terbaik seluruhnya, dengan tujuan yang paling agung.", "no": 11},
{"ar": "وَرَأَتْ مِنَ الْبَرَكَاتِ حِيْنَ مَضَتْ بِهِ ۞ فَالسَّعْدُ قَارَنَهَا بِطَلْعَةِ أَحْمَدِ", "lt": "Wa ra'at minal-barakâti ḥîna madlat bihî ۞ fas-sa‘du qâranahâ biṭal‘ati aḥmadi", "id": "Ia melihat berbagai keberkahan ketika pergi membawanya; kebahagiaan menyertainya dengan kehadiran Ahmad.", "no": 12},
{"ar": "قَدْ دَرَّ مِنْهَا الثَّدْيُ عِنْدَ رِضَاعِهِ ۞ أَمِنَتْ بِهِ مِنْ كُلِّ جُهْدٍ مُجْهِدِ", "lt": "Qad darra minhats-tsadyu ‘inda ridlâ‘ihî ۞ aminat bihî min kulli juhdin mujhidi", "id": "Air susunya mengalir deras ketika menyusuinya, dan karenanya ia aman dari segala kesulitan yang memberatkan.", "no": 13},
{"ar": "وَأَتَانُهَا لِلرَّكْبِ قَدْ سَبَقَتْ بِهَا ۞ فَرَحًا وَتِيْهًا بِالرَّسُوْلِ الْأَمْجَدِ", "lt": "Wa atânuhâ lir-rakbi qad sabaqat bihâ ۞ faraḥan wa tîhan bir-rasûlil-amjadi", "id": "Keledainya mendahului rombongan kafilah membawanya, karena gembira dan bangga membawa Rasul yang paling mulia.", "no": 14},
{"ar": "أَغْنَامُهَا كَانَتْ شِبَاعًا كُلَّمَا ۞ سَرَحَتْ تَجُوْدُ لَهَا بِدَرٍّ مُزْبِدِ", "lt": "Aghnâmuhâ kânat syibâ‘an kullamâ ۞ saraḥat tajûdu lahâ bidarrin muzbidi", "id": "Kambing-kambingnya selalu kenyang; setiap kali digembalakan, kambing-kambing itu memberinya susu melimpah berbusa.", "no": 15},
{"ar": "وَرَأَتْ مِنَ الْخَيْرَاتِ وَهْيَ تَحُفُّهَا ۞ وَالنَّاسُ فِيْ مَحْلٍ وَعَيْشٍ أَنْكَدِ", "lt": "Wa ra'at minal-khairâti wahya taḥuffuhâ ۞ wan-nâsu fî maḥlin wa ‘aisyin ankadi", "id": "Ia melihat berbagai kebaikan meliputinya, sementara orang-orang lain berada dalam kekeringan dan kehidupan yang paling sulit.", "no": 16},
{"ar": "نَالَتْ بِهِ كُلَّ الْمَسَرَّةِ وَالْهَنَا ۞ فَهُوَ الَّذِيْ قَدْ سَادَ كُلَّ مُسَوَّدِ", "lt": "Nâlat bihî kullal-masarrati wal-hanâ ۞ fahuwal-ladzî qad sâda kulla musawwadi", "id": "Karenanya ia memperoleh segala kegembiraan dan kebahagiaan; dialah yang telah memimpin setiap pemimpin.", "no": 17},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 18}]},
{judul:"Halimah di Rumah Aminah",isi:[
{"ar": "قَالَتْ حَلِيْمَةُ: فَجِئْتُ إِلَى بَيْتِ أُمِّهِ آمِنَةَ، وَهِيَ امْرَأَةٌ هِلَالِيَّةٌ تَزْهَرُ كَالْكَوْكَبِ الدُّرِّيِّ، فَسَأَلْتُهَا عَنْهُ، فَقَالَتْ: أَنْتُمْ يَا أَهْلَ الْبَادِيَةِ تَطْلُبُوْنَ مَنْ تَجِدُوْنَ رِفْدَهُ، وَهٰذَا طِفْلٌ يَتِيْمٌ مَاتَ أَبُوْهُ وَكُنْتُ بِهِ حَامِلًا، فَكَفَلَهُ جَدُّهُ عَبْدُ الْمُطَّلِبِ", "lt": "Qâlat ḥalîmah: faji'tu ilâ baiti ummihî âminah, wa hiya imra'atun hilâliyyatun tazharu kal-kaukabid-durriyy, fasa'altuhâ ‘anh, faqâlat: antum yâ ahlal-bâdiyati taṭlubûna man tajidûna rifdah, wa hâdzâ ṭiflun yatîmun mâta abûhu wa kuntu bihî ḥâmilâ, fakafalahû jadduhû ‘abdul-muṭṭalib", "id": "Halimah berkata: Aku datang ke rumah ibunya, Aminah, seorang perempuan bercahaya laksana bulan sabit yang berkilau seperti bintang gemerlap. Aku bertanya kepadanya tentang bayi itu. Ia berkata: Kalian penduduk pedalaman mencari bayi yang bisa memberi kalian imbalan, padahal ini anak yatim yang ayahnya wafat ketika aku sedang mengandungnya; ia diasuh oleh kakeknya, Abdul Muthalib.", "no": 1},
{"ar": "قَالَتْ حَلِيْمَةُ: فَرَجَعْتُ إِلَى بَعْلِيْ لِأُشَاوِرَهُ فِيْهِ، فَقَالَ: أَرِيْنِيْ هٰذَا الْغُلَامَ. قَالَ: فَتَقَدَّمْتُ أَنَا وَبَعْلِيْ إِلَى بَيْتِ آمِنَةَ، فَقُلْنَا: هَلُمِّيْ بِهِ إِلَيْنَا، فَأَتَتْ بِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَدْهُوْنًا مُدْرَجًا فِيْ ثَوْبِ صُوْفٍ أَبْيَضَ وَتَحْتَهُ حَرِيْرَةٌ خَضْرَاءُ، فَإِذَا وَجْهُهُ يُضِيْءُ كَالْقَمَرِ لَيْلَةَ الْبَدْرِ", "lt": "Qâlat ḥalîmah: faraja‘tu ilâ ba‘lî li'usyâwirahû fîh, faqâla: arînî hâdzal-ghulâm. Qâla: fataqaddamtu ana wa ba‘lî ilâ baiti âminah, faqulnâ: halummî bihî ilainâ, fa atat bihî shallallâhu ‘alaihi wa sallama madhûnan mudrajan fî tsaubi shûfin abyadla wa taḥtahû ḥarîratun khadlrâ', fa idzâ wajhuhû yudlî'u kal-qamari lailatal-badr", "id": "Halimah berkata: Aku kembali kepada suamiku untuk bermusyawarah tentangnya. Ia berkata: Perlihatkan kepadaku anak itu. Lalu aku dan suamiku pergi ke rumah Aminah dan berkata: Bawalah ia kemari kepada kami. Ia pun membawa beliau ﷺ dalam keadaan berminyak, terbungkus kain wol putih dengan alas kain sutra hijau di bawahnya. Ternyata wajahnya bersinar seperti bulan pada malam purnama.", "no": 2},
{"ar": "فَنَظَرَ بَعْلِيْ فِيْ وَجْهِهِ، فَفَتَحَ عَيْنَيْهِ فَخَرَجَ مِنْهُمَا نُوْرٌ سَاطِعٌ وَضِيَاءٌ لَامِعٌ، فَحَارَ عَقْلِيْ وَعَقْلُ بَعْلِيْ، فَقَالَ: وَيْحَكِ يَا حَلِيْمَةُ، هٰذَا الْمَوْلُوْدُ هُوَ كُلُّ الْمُنَى وَالْمَقْصُوْدِ", "lt": "Fanazhara ba‘lî fî wajhih, fafataḥa ‘ainaihi fakharaja minhumâ nûrun sâṭi‘un wa dliyâ'un lâmi‘, faḥâra ‘aqlî wa ‘aqlu ba‘lî, faqâla: waiḥaki yâ ḥalîmah, hâdzal-maulûdu huwa kullul-munâ wal-maqshûd", "id": "Suamiku memandang wajahnya, lalu beliau membuka kedua matanya dan keluarlah dari keduanya cahaya yang memancar dan sinar yang berkilau. Akalku dan akal suamiku pun tercengang. Suamiku berkata: Wahai Halimah, bayi inilah segala harapan dan tujuan.", "no": 3},
{"ar": "فَقُلْتُ لَهُ: وَهُوَ يَتِيْمٌ، فَمَاذَا نَصْنَعُ بِهِ؟ فَقَالَ: خُذِيْهِ، فَلَعَلَّ اللهَ بِبَرَكَتِهِ يَرْزُقُنَا إِنْ شَاءَ اللهُ تَعَالَى، فَكَانَ كَذٰلِكَ", "lt": "Faqultu lah: wa huwa yatîm, famâdzâ nashna‘u bih? Faqâla: khudzîh, fala‘allallâha bibarakatihî yarzuqunâ in syâ'allâhu ta‘âlâ, fakâna kadzâlik", "id": "Aku berkata kepadanya: Tetapi ia yatim, apa yang akan kita perbuat dengannya? Ia menjawab: Ambillah dia, semoga dengan keberkahannya Allah memberi kita rezeki, insya Allah Ta'ala. Dan memang demikianlah yang terjadi.", "no": 4},
{"ar": "قَالَتْ حَلِيْمَةُ: فَأَخَذْتُهُ وَلَيْسَ فِيْ ثَدْيِيْ لَبَنٌ، وَوَلَدِيْ طُوْلَ اللَّيْلِ يُقْلِقُنِيْ مِنْ شِدَّةِ الْجُوْعِ، فَلَمَّا حَمَلْتُ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَتَانِيْ ضَعِيْفَةٌ فَقَوِيَتْ، وَزَالَ عَنِّيْ مَا أَجِدُ مِنَ الْأَلَمِ", "lt": "Qâlat ḥalîmah: fa akhadztuhû wa laisa fî tsadyî laban, wa waladî ṭûlal-laili yuqliqunî min syiddatil-jû‘, falammâ ḥamaltu muḥammadan shallallâhu ‘alaihi wa sallama wa atânî dla‘îfatun faqawiyat, wa zâla ‘annî mâ ajidu minal-alam", "id": "Halimah berkata: Aku mengambilnya sementara di payudaraku tidak ada air susu, dan anakku sepanjang malam membuatku gelisah karena sangat lapar. Ketika aku menggendong Muhammad ﷺ, keledaiku yang lemah menjadi kuat, dan hilanglah rasa sakit yang kurasakan.", "no": 5},
{"ar": "ثُمَّ وَضَعْتُ ثَدْيِيْ فِيْ فِيْهِ، فَثَارَ اللَّبَنُ حَتَّى فَاضَ وَتَبَدَّدَ، وَسَمِعْتُ قَائِلًا يَقُوْلُ: طُوْبَى لَكِ أَيَّتُهَا السَّعْدِيَّةُ، بِالطَّلْعَةِ الْهَاشِمِيَّةِ، وَالْغُرَّةِ الْقَمَرِيَّةِ، وَالْهِمَّةِ الْقُرَشِيَّةِ، سَعْدُكِ يَا حَلِيْمَةُ بِالدُّرَّةِ الْيَتِيْمَةِ", "lt": "Tsumma wadla‘tu tsadyî fî fîh, fatsâral-labanu ḥattâ fâdla wa tabaddad, wa sami‘tu qâ'ilan yaqûl: ṭûbâ laki ayyatuhas-sa‘diyyah, biṭ-ṭal‘atil-hâsyimiyyah, wal-ghurratil-qamariyyah, wal-himmatil-qurasyiyyah, sa‘duki yâ ḥalîmatu bid-durratil-yatîmah", "id": "Kemudian aku letakkan payudaraku di mulutnya, maka air susu memancar hingga meluap dan berlimpah. Aku mendengar seseorang berkata: Beruntunglah engkau, wahai perempuan Bani Sa'd, dengan wajah Bani Hasyim, dahi bercahaya laksana rembulan, dan cita-cita Quraisy. Kebahagiaanmu, wahai Halimah, adalah dengan permata yang tiada bandingnya.", "no": 6}]},
{judul:"Ta'allama Linahul-Ghushnu",isi:[
{"ar": "اَللّٰهُ اللّٰهُ اللّٰهُ خَالِقُنَا ۞ اَللّٰهُ اللّٰهُ اللّٰهُ رَازِقُنَا", "lt": "Allâhu allâhu allâhu khâliqunâ ۞ allâhu allâhu allâhu râziqunâ", "id": "Allah, Allah, Allah Pencipta kami; Allah, Allah, Allah Pemberi rezeki kami.", "no": 1},
{"ar": "إِلٰهِيْ يَا إِلٰهِيْ يَا إِلٰهِيْ ۞ إِلٰهِيْ تَوْبَةً قَبْلَ الْمَمَاتِ", "lt": "Ilâhî yâ ilâhî yâ ilâhî ۞ ilâhî taubatan qablal-mamâti", "id": "Tuhanku, wahai Tuhanku, wahai Tuhanku; Tuhanku, (anugerahkanlah) tobat sebelum mati.", "no": 2},
{"ar": "تَعَلَّمَ لِيْنَهُ الْغُصْنُ الْقَوِيْمُ ۞ وَمِنْ أَلْطَافِ مَعْنَاهُ النَّسِيْمُ", "lt": "Ta‘allama lînahul-ghushnul-qawîmu ۞ wa min alṭâfi ma‘nâhun-nasîmu", "id": "Dahan yang lurus belajar kelembutan darinya, dan angin sepoi-sepoi (belajar) dari kehalusan sifatnya.", "no": 3},
{"ar": "مَلِيْحٌ لَمْ يَحُزْ بَشَرٌ حُلَاهُ ۞ فَدَلَّ بِأَنَّهُ بَشَرٌ كَرِيْمُ", "lt": "Malîḥun lam yaḥuz basyarun ḥulâhu ۞ fadalla bi'annahû basyarun karîmu", "id": "Ia rupawan; tidak ada manusia yang memiliki perhiasan sepertinya, yang menunjukkan bahwa ia manusia yang mulia.", "no": 4},
{"ar": "وَسِيْمٌ فِيْ مَلَاحَتِهِ حَشِيْمٌ ۞ وَمَا فِي الْحُسْنِ قَطُّ لَهُ قَسِيْمُ", "lt": "Wasîmun fî malâḥatihî ḥasyîmun ۞ wa mâ fil-ḥusni qaṭṭu lahû qasîmu", "id": "Tampan, dan dalam ketampanannya ia berwibawa; tidak pernah ada yang menyamainya dalam keindahan.", "no": 5},
{"ar": "فَمَا كُلُّ الشَّقَاءِ سِوَى جَفَاهُ ۞ وَلَيْسَ سِوَى تَوَاصُلِهِ نَعِيْمُ", "lt": "Famâ kullusy-syaqâ'i siwâ jafâhu ۞ wa laisa siwâ tawâshulihî na‘îmu", "id": "Segala kesengsaraan tidak lain adalah jauh darinya, dan tiada kenikmatan selain bertemu dengannya.", "no": 6},
{"ar": "لَهُ فِيْ طَيْبَةٍ أَسْنَى مَقَامٍ ۞ لَدَيْهِ الْخَيْرُ أَجْمَعُهُ مُقِيْمُ", "lt": "Lahû fî ṭaibatin asnâ maqâmin ۞ ladaihil-khairu ajma‘uhû muqîmu", "id": "Di Thaibah (Madinah) ia memiliki kedudukan paling luhur; di sisinya seluruh kebaikan menetap.", "no": 7},
{"ar": "إِذَا غَنَّى بِهِ حَادِي الْمَطَايَا ۞ رَأَيْتَ النُّوْقَ مِنْ طَرَبٍ تَهِيْمُ", "lt": "Idzâ ghannâ bihî ḥâdil-maṭâyâ ۞ ra'aitan-nûqa min ṭarabin tahîmu", "id": "Apabila penggiring unta melantunkan namanya, engkau akan melihat unta-unta mabuk kepayang karena gembira.", "no": 8},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 9}]},
{judul:"Hubal Tertunduk",isi:[
{"ar": "قَالَتْ حَلِيْمَةُ: فَأَخَذْتُهُ وَدَخَلْتُ بِهِ عَلَى الْأَصْنَامِ، فَنَكَّسَ هُبَلُ رَأْسَهُ، وَخَرَّتِ الْأَصْنَامُ مِنْ أَمَاكِنِهَا", "lt": "Qâlat ḥalîmah: fa akhadztuhû wa dakhaltu bihî ‘alal-ashnâm, fanakkasa hubalu ra'sah, wa kharratil-ashnâmu min amâkinihâ", "id": "Halimah berkata: Aku membawanya masuk ke tempat berhala-berhala, maka Hubal menundukkan kepalanya dan berhala-berhala tersungkur dari tempatnya.", "no": 1},
{"ar": "فَجِئْتُ إِلَى الْحَجَرِ الْأَسْوَدِ لِأُقَبِّلَهُ، فَخَرَجَ الْحَجَرُ مِنْ مَكَانِهِ حَتَّى الْتَصَقَ بِوَجْهِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ", "lt": "Faji'tu ilal-ḥajaril-aswadi li'uqabbilah, fakharajal-ḥajaru min makânihî ḥattal-tashaqa biwajhihî shallallâhu ‘alaihi wa sallam", "id": "Lalu aku mendatangi Hajar Aswad untuk menciumnya, maka batu itu keluar dari tempatnya hingga menempel pada wajah beliau ﷺ.", "no": 2},
{"ar": "فَأَخْبَرْتُ بَعْلِيْ بِذٰلِكَ، فَقَالَ: أَلَمْ أَقُلْ لَكِ إِنَّهُ مُبَارَكٌ؟ خُذِيْهِ وَانْصَرِفِيْ بِنَا", "lt": "Fa akhbartu ba‘lî bidzâlik, faqâla: alam aqul laki innahû mubârak? Khudzîhi wansharifî binâ", "id": "Aku memberitahukan hal itu kepada suamiku, dan ia berkata: Bukankah sudah kukatakan kepadamu bahwa ia penuh berkah? Bawalah dia dan mari kita pulang.", "no": 3},
{"ar": "قَالَتْ حَلِيْمَةُ: فَمَا انْصَرَفَ أَحَدٌ كَمَا انْصَرَفْنَا، وَلَا ظَفِرَ أَحَدٌ كَمَا ظَفِرْنَا. قَالَتْ: فَرَكِبْتُ الدَّابَّةَ الَّتِيْ جِئْتُ عَلَيْهَا، وَكَانَتْ ضَعِيْفَةً لَا تَسْتَطِيْعُ الْمَشْيَ، فَجَعَلَتِ الدَّابَّةُ تَسْبِقُ دَوَابَّ الْقَافِلَةِ كُلَّهَا، حَتَّى كَانَتِ النِّسَاءُ يَقُلْنَ لِيْ: أَمْسِكِيْ أَتَانَكِ عَنَّا يَا حَلِيْمَةُ", "lt": "Qâlat ḥalîmah: famanṣarafa aḥadun kamanṣarafnâ, wa lâ zhafira aḥadun kamâ zhafirnâ. Qâlat: farakibtud-dâbbatal-latî ji'tu ‘alaihâ, wa kânat dla‘îfatan lâ tastaṭî‘ul-masy-ya, faja‘alatid-dâbbatu tasbiqu dawâbbal-qâfilati kullahâ, ḥattâ kânatin-nisâ'u yaqulna lî: amsikî atânaki ‘annâ yâ ḥalîmah", "id": "Halimah berkata: Tidak ada seorang pun yang pulang seperti kami pulang, dan tidak ada yang beruntung seperti keberuntungan kami. Ia berkata: Aku menaiki tunggangan yang kubawa datang, yang tadinya lemah tidak kuat berjalan, namun kini ia mendahului semua tunggangan kafilah, hingga para perempuan berkata kepadaku: Tahanlah keledaimu agar menunggu kami, wahai Halimah.", "no": 4},
{"ar": "قَالَتْ: وَكُنْتُ لَا أَمُرُّ عَلَى شَجَرٍ وَلَا مَدَرٍ إِلَّا وَيَقُوْلُ: اَلسَّلَامُ عَلَيْكَ يَا خَيْرَ الْمُرْسَلِيْنَ، وَكُنَّا لَا نَنْزِلُ تَحْتَ شَجَرَةٍ يَابِسَةٍ إِلَّا اخْضَرَّتْ وَأَثْمَرَتْ لِوَقْتِهَا بِبَرَكَتِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ", "lt": "Qâlat: wa kuntu lâ amurru ‘alâ syajarin wa lâ madarin illâ wa yaqûl: as-salâmu ‘alaika yâ khairal-mursalîn, wa kunnâ lâ nanzilu taḥta syajaratin yâbisatin illakhdlarrat wa atsmarat liwaqtihâ bibarakatihî shallallâhu ‘alaihi wa sallam", "id": "Ia berkata: Setiap kali aku melewati pohon atau bongkahan tanah, ia pasti berkata: Salam sejahtera untukmu, wahai rasul terbaik. Setiap kali kami singgah di bawah pohon yang kering, seketika pohon itu menghijau dan berbuah berkat keberkahan beliau ﷺ.", "no": 5},
{"ar": "فَسِرْنَا حَتَّى أَتَيْنَا مَنَازِلَنَا وَعِنْدَنَا شُوَيْهَاتٌ عِجَافٌ ضِعَافٌ، فَأَخَذْتُ يَدَ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَوَضَعْتُهَا عَلَيْهِنَّ، فَدَرَرْنَ لِوَقْتِهِنَّ، وَمُنْذُ أَخَذْنَاهُ لَمْ يَكُنْ لَنَا مِصْبَاحٌ فِي اللَّيَالِي الْمُظْلِمَةِ إِلَّا نُوْرُ وَجْهِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ", "lt": "Fasirnâ ḥattâ ataina manâzilanâ wa ‘indanâ suwaihâtun ‘ijâfun dli‘âf, fa akhadztu yada muḥammadin shallallâhu ‘alaihi wa sallama wa wadla‘tuhâ ‘alaihinna, fadarar-na liwaqtihinn, wa mundzu akhadznâhu lam yakun lanâ mishbâḥun fil-layâlil-muzhlimati illâ nûru wajhihî shallallâhu ‘alaihi wa sallam", "id": "Kami terus berjalan hingga tiba di tempat tinggal kami. Kami memiliki beberapa ekor kambing kecil yang kurus dan lemah. Aku mengambil tangan Muhammad ﷺ dan meletakkannya pada kambing-kambing itu, seketika susunya mengalir deras. Sejak kami mengasuhnya, kami tidak memerlukan pelita di malam-malam yang gelap selain cahaya wajah beliau ﷺ.", "no": 6},
{"ar": "قَالَتْ حَلِيْمَةُ: وَكُنْتُ إِذَا أَعْطَيْتُهُ ثَدْيِيَ الْأَيْمَنَ شَرِبَ، وَإِذَا حَوَّلْتُهُ لِثَدْيِيَ الْأَيْسَرِ أَبَى، لِأَنَّ اللهَ تَبَارَكَ وَتَعَالَى أَلْهَمَهُ الْعَدْلَ حَتَّى فِي الرَّضَاعَةِ، عَلِمَ أَنَّ لَهُ شَرِيْكًا، فَنَاصَفَهُ عَدْلًا مِنْهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ", "lt": "Qâlat ḥalîmah: wa kuntu idzâ a‘ṭaituhû tsadyiyal-aimana syarib, wa idzâ ḥawwaltuhû litsadyiyal-aisari abâ, li'annallâha tabâraka wa ta‘âlâ alhamahul-‘adla ḥattâ fir-radlâ‘ah, ‘alima anna lahû syarîkâ, fanâshafahû ‘adlan minhu shallallâhu ‘alaihi wa sallam", "id": "Halimah berkata: Apabila aku memberinya payudaraku yang kanan, ia menyusu; dan apabila aku memindahkannya ke payudara yang kiri, ia menolak. Sebab Allah Tabaraka wa Ta'ala mengilhamkan keadilan kepadanya, bahkan dalam menyusu: ia tahu bahwa ia punya saudara sesusuan, maka ia berbagi separuh dengannya sebagai bentuk keadilan beliau ﷺ.", "no": 7},
{"ar": "قَالَتْ حَلِيْمَةُ: وَانْقَطَعَ الْغَيْثُ عَنَّا سَنَةً كَامِلَةً مِنَ السِّنِيْنَ، فَأَخَذْنَاهُ وَخَرَجْنَا بِهِ إِلَى الصَّحْرَاءِ، وَقُلْنَا: اَللّٰهُمَّ بِحُرْمَةِ هٰذَا الْمَوْلُوْدِ عَلَيْكَ إِلَّا مَا سَقَيْتَنَا الْغَيْثَ، يَا رَبَّنَا يَا مَعْبُوْدُ. قَالَتْ: فَإِذَا السَّمَاءُ قَدْ غَيَّمَتْ وَسَكَبَتْ مَاءً كَأَفْوَاهِ الْقِرَبِ", "lt": "Qâlat ḥalîmah: wanqaṭa‘al-ghaitsu ‘annâ sanatan kâmilatan minas-sinîn, fa akhadznâhu wa kharajnâ bihî ilash-shaḥrâ', wa qulnâ: allâhumma biḥurmati hâdzal-maulûdi ‘alaika illâ mâ saqaitanal-ghaits, yâ rabbanâ yâ ma‘bûd. Qâlat: fa idzas-samâ'u qad ghayyamat wa sakabat mâ'an ka'afwâhil-qirab", "id": "Halimah berkata: Hujan tidak turun kepada kami selama satu tahun penuh. Kami pun membawanya keluar ke padang pasir dan berdoa: Ya Allah, dengan kehormatan bayi ini di sisi-Mu, turunkanlah hujan kepada kami, wahai Tuhan kami, wahai Yang disembah. Ia berkata: Tiba-tiba langit menjadi mendung dan menumpahkan air seperti dari mulut-mulut kantong air.", "no": 8}]},
{judul:"Man Mitslu Ahmada",isi:[
{"ar": "اَللّٰهُ اللّٰهُ اللّٰهُ اللّٰهُ اللّٰهُ ۞ عِزًّا وَإِجْلَالًا", "lt": "Allâhu allâhu allâhu allâhu allâh ۞ ‘izzan wa ijlâlâ", "id": "Allah, Allah, Allah, Allah, Allah, Yang Maha Perkasa dan Maha Agung.", "no": 1},
{"ar": "مَنْ مِثْلُ أَحْمَدَ فِي الْكَوْنَيْنِ نَهْوَاهُ ۞ بَدْرٌ جَمِيْعُ الْوَرَى فِيْ حُسْنِهِ تَاهُوْا", "lt": "Man mitslu aḥmada fil-kaunaini nahwâhu ۞ badrun jamî‘ul-warâ fî ḥusnihî tâhû", "id": "Siapakah di dua alam yang seperti Ahmad, yang kami cintai? Ia purnama yang keindahannya membuat seluruh makhluk terpesona.", "no": 2},
{"ar": "مَنْ مِثْلُهُ وَإِلٰهُ الْعَرْشِ شَرَّفَهُ ۞ بِالْخَلْقِ وَالْخُلْقِ إِنَّ اللهَ أَعْطَاهُ", "lt": "Man mitsluhû wa ilâhul-‘arsyi syarrafahû ۞ bil-khalqi wal-khuluqi innallâha a‘ṭâhu", "id": "Siapakah yang menyamainya, padahal Tuhan pemilik Arsy telah memuliakannya dengan rupa dan akhlak yang Allah anugerahkan kepadanya?", "no": 3},
{"ar": "وَالشَّمْسُ تَخْجَلُ مِنْ أَنْوَارِ طَلْعَتِهِ ۞ حَارَتْ عُقُوْلُ الْوَرَى فِيْ وَصْفِ مَعْنَاهُ", "lt": "Wasy-syamsu takhjalu min anwâri ṭal‘atihî ۞ ḥârat ‘uqûlul-warâ fî washfi ma‘nâhu", "id": "Matahari pun malu kepada cahaya wajahnya; akal seluruh makhluk bingung dalam menggambarkan hakikatnya.", "no": 4},
{"ar": "تَبَارَكَ اللهُ مَا أَحْلَى شَمَائِلَهُ ۞ حَازَ الْجَمَالَ فَمَا أَبْهَى مُحَيَّاهُ", "lt": "Tabârakallâhu mâ aḥlâ syamâ'ilahû ۞ ḥâzal-jamâla famâ abhâ muḥayyâhu", "id": "Maha Suci Allah, betapa manis budi pekertinya; ia meraih keindahan, maka betapa cemerlang wajahnya.", "no": 5},
{"ar": "يَا عُرْبَ وَادِي النَّقَا يَا أَهْلَ كَاظِمَةٍ ۞ فِيْ حُبِّكُمْ قَمَرٌ فِي الْقَلْبِ مَأْوَاهُ", "lt": "Yâ ‘urba wâdin-naqâ yâ ahla kâzhimatin ۞ fî ḥubbikum qamarun fil-qalbi ma'wâhu", "id": "Wahai orang-orang Arab lembah Naqa, wahai penduduk Kazhimah, dalam cinta kalian ada rembulan yang bersemayam di dalam hati.", "no": 6},
{"ar": "هٰذَا مَلِيْحٌ وَكُلُّ النَّاسِ يَهْوَاهُ ۞ وَسَائِرُ الْخَلْقِ فِيْ أَوْصَافِهِ تَاهُوْا", "lt": "Hâdzâ malîḥun wa kullun-nâsi yahwâhu ۞ wa sâ'irul-khalqi fî aushâfihî tâhû", "id": "Inilah sosok yang rupawan; semua manusia mencintainya, dan seluruh makhluk terpesona oleh sifat-sifatnya.", "no": 7},
{"ar": "صَلَّى عَلَيْهِ إِلٰهُ الْعَرْشِ مَا طَلَعَتْ ۞ شَمْسٌ وَمَا حَثْحَثَ الْحَادِيْ مَطَايَاهُ", "lt": "Shallâ ‘alaihi ilâhul-‘arsyi mâ ṭala‘at ۞ syamsun wa mâ ḥatsḥatsal-ḥâdî maṭâyâhu", "id": "Semoga Tuhan pemilik Arsy melimpahkan shalawat kepadanya selama matahari terbit dan selama penggiring unta memacu tunggangannya.", "no": 8},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 9}]},
{judul:"Pembelahan Dada",isi:[
{"ar": "قَالَتْ حَلِيْمَةُ: فَمَا زَالَ عِنْدِيْ حَتَّى يَسَّرَ اللهُ عَلَيَّ الْخَيْرَاتِ وَالْبَرَكَاتِ وَالسَّعَادَاتِ بِبَرَكَتِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ", "lt": "Qâlat ḥalîmah: famâ zâla ‘indî ḥattâ yassarallâhu ‘alayyal-khairâti wal-barakâti was-sa‘âdâti bibarakatihî shallallâhu ‘alaihi wa sallam", "id": "Halimah berkata: Beliau terus bersamaku hingga Allah memudahkan bagiku berbagai kebaikan, keberkahan, dan kebahagiaan berkat keberkahan beliau ﷺ.", "no": 1},
{"ar": "ثُمَّ إِنَّهُ خَرَجَ يَوْمًا مَعَ أَخِيْهِ ضَمْرَةَ يَرْعَيَانِ غَنَمًا لَنَا حَوْلَ بُيُوْتِنَا، فَبَيْنَمَا أَنَا كَذٰلِكَ إِذْ بِابْنِيْ ضَمْرَةَ يَعْدُوْ وَقَدْ عَلَاهُ صُفْرَةٌ، وَهُوَ يُنَادِيْ: يَا أُمَّاهُ، أَلْحِقِيْ أَخِيْ مُحَمَّدًا، فَمَا أَظُنُّكِ تَجِدِيْنَهُ إِلَّا مَقْتُوْلًا، أَعَاذَهُ اللهُ مِنْ ذٰلِكَ", "lt": "Tsumma innahû kharaja yauman ma‘a akhîhi dlamrata yar‘ayâni ghanaman lanâ ḥaula buyûtinâ, fabainamâ ana kadzâlika idz bibnî dlamrata ya‘dû wa qad ‘alâhu shufrah, wa huwa yunâdî: yâ ummâh, alḥiqî akhî muḥammadâ, famâ azhunnuki tajidînahû illâ maqtûlâ, a‘âdzahullâhu min dzâlik", "id": "Suatu hari beliau keluar bersama saudaranya, Dlamrah, menggembalakan kambing kami di sekitar rumah. Ketika aku sedang di rumah, tiba-tiba anakku Dlamrah datang berlari dengan wajah pucat pasi sambil berseru: Wahai ibu, susullah saudaraku Muhammad! Aku kira engkau tidak akan menemukannya kecuali dalam keadaan terbunuh. Semoga Allah melindunginya dari hal itu.", "no": 2},
{"ar": "قَالَتْ حَلِيْمَةُ: فَأَسْرَعْنَا إِلَيْهِ فَإِذَا هُوَ شَاخِصٌ بِبَصَرِهِ إِلَى السَّمَاءِ، فَلَمَّا رَآنِيْ تَبَسَّمَ ضَاحِكًا، فَضَمَمْتُهُ إِلَى صَدْرِيْ وَقَبَّلْتُ بَيْنَ عَيْنَيْهِ، فَقُلْتُ لَهُ: حَبِيْبِيْ فَدَتْكَ نَفْسِيْ، مَا الَّذِيْ أَصَابَكَ يَا بُنَيَّ؟", "lt": "Qâlat ḥalîmah: fa asra‘nâ ilaihi fa idzâ huwa syâkhishun bibasharihî ilas-samâ', falammâ ra'ânî tabassama dlâḥikâ, fadlamamtuhû ilâ shadrî wa qabbaltu baina ‘ainaih, faqultu lah: ḥabîbî fadatka nafsî, mal-ladzî ashâbaka yâ bunayy?", "id": "Halimah berkata: Kami bergegas menuju kepadanya, ternyata ia sedang menatap ke langit. Ketika melihatku, ia tersenyum hingga tertawa. Aku memeluknya ke dadaku dan mencium di antara kedua matanya, lalu bertanya: Kekasihku, jiwaku sebagai tebusanmu, apa yang menimpamu, wahai anakku?", "no": 3},
{"ar": "فَقَالَ لَهَا: جَاءَنِيْ ثَلَاثَةُ نَفَرٍ، فَأَخْبَرَهَا أَنَّهُمْ شَقُّوْا صَدْرِيْ وَأَخْرَجُوْا قَلْبِيْ وَغَسَلُوْهُ وَرَدُّوْهُ إِلَى مَكَانِهِ، وَالْتَأَمَ صَدْرِيْ بِقُدْرَةِ اللهِ سُبْحَانَهُ وَتَعَالَى مِنْ غَيْرِ أَلَمٍ", "lt": "Faqâla lahâ: jâ'anî tsalâtsatu nafar, fa akhbarahâ annahum syaqqû shadrî wa akhrajû qalbî wa ghasalûhu wa raddûhu ilâ makânih, waltâ'ama shadrî biqudratillâhi subḥânahû wa ta‘âlâ min ghairi alam", "id": "Beliau berkata kepadanya: Tiga orang datang kepadaku. Lalu beliau memberitahunya bahwa mereka membelah dadaku, mengeluarkan hatiku, mencucinya, lalu mengembalikannya ke tempatnya, dan dadaku kembali tertutup dengan kekuasaan Allah Subhanahu wa Ta'ala tanpa rasa sakit.", "no": 4}]},
{judul:"Ya Maulidan Qad Hawa",isi:[
{"ar": "اَللّٰهُ اللّٰهُ اللّٰهُ اللّٰهُ اللّٰهُ اللّٰهُ اللّٰهُ اللّٰهُ ۞ عِزًّا وَإِقْبَالًا", "lt": "Allâhu allâhu allâhu allâhu allâhu allâhu allâhu allâh ۞ ‘izzan wa iqbâlâ", "id": "Allah, Allah, Allah, Allah, Allah, Allah, Allah, Allah, (Yang memberi) kemuliaan dan keberuntungan.", "no": 1},
{"ar": "يَا مَوْلِدًا قَدْ حَوَى عِزًّا وَإِقْبَالًا ۞ بِوَصْلِهِ يَبْلُغُ الْمُشْتَاقُ آمَالًا", "lt": "Yâ maulidan qad ḥawâ ‘izzan wa iqbâlan ۞ biwashlihî yablughul-musytâqu âmâlâ", "id": "Wahai kelahiran yang menghimpun kemuliaan dan keberuntungan, dengan sampai kepadanya orang yang rindu meraih cita-citanya.", "no": 2},
{"ar": "يَا مُدَّعِي الْحُبِّ فِيْهِ وَهُوَ ذُوْ وَلَهٍ ۞ وَفِيْ هَوَاهُ جَفَا أَهْلًا وَأَطْلَالًا", "lt": "Yâ mudda‘il-ḥubbi fîhi wa huwa dzû walahin ۞ wa fî hawâhu jafâ ahlan wa aṭlâlâ", "id": "Wahai orang yang mengaku mencintainya dan dilanda kerinduan, yang demi cintanya meninggalkan keluarga dan kampung halaman,", "no": 3},
{"ar": "إِنْ كُنْتَ تَعْشَقُهُ مُتْ فِيْ مَحَبَّتِهِ ۞ مُوَلَّهَ الْقَلْبِ مُشْتَاقًا وَإِلَّا لَا", "lt": "In kunta ta‘syaquhû mut fî maḥabbatihî ۞ muwallahal-qalbi musytâqan wa illâ lâ", "id": "jika engkau benar-benar mencintainya, matilah dalam mencintainya dengan hati yang mabuk rindu; jika tidak, maka (pengakuanmu) tidak benar.", "no": 4},
{"ar": "النُّوْقُ تَعْشَقُهُ وَجْدًا وَتَقْصِدُهُ ۞ شَوْقًا وَتَطْلُبُ مِنْ رُؤْيَاهُ إِجْلَالًا", "lt": "An-nûqu ta‘syaquhû wajdan wa taqshiduhû ۞ syauqan wa taṭlubu min ru'yâhu ijlâlâ", "id": "Unta-unta pun mencintainya dengan penuh rindu, menujunya dengan rindu, dan mencari kemuliaan dengan melihatnya.", "no": 5},
{"ar": "أَمَا تَرَاهَا إِذَا لَاحَتْ قِبَابُ قُبَا ۞ تَحُطُّ عَنْهَا حُدَاةُ الْعِيْسِ أَثْقَالًا", "lt": "Amâ tarâhâ idzâ lâḥat qibâbu qubâ ۞ taḥuṭṭu ‘anhâ ḥudâtul-‘îsi atsqâlâ", "id": "Tidakkah engkau lihat, ketika kubah-kubah Quba tampak, para penggiring unta menurunkan beban-beban darinya?", "no": 6},
{"ar": "مُشْتَاقَةٌ عَشِقَتْ مَنْ لَا شَبِيْهَ لَهُ ۞ يُقَطِّعُ الشَّوْقُ مِنْهَا فِيْهِ أَوْصَالًا", "lt": "Musytâqatun ‘asyiqat man lâ syabîha lahû ۞ yuqaṭṭi‘usy-syauqu minhâ fîhi aushâlâ", "id": "Ia rindu dan mencintai sosok yang tiada bandingnya, hingga kerinduan kepadanya seakan memutus-mutus persendiannya.", "no": 7},
{"ar": "إِيَّاكَ وَالْعَذْلَ مَنْ فِي الْكَوْنِ يُشْبِهُهُ ۞ قَدْ فَاقَ فِي الْحُسْنِ أَشْكَالًا وَأَمْثَالًا", "lt": "Iyyâka wal-‘adzla man fil-kauni yusybihuhû ۞ qad fâqa fil-ḥusni asykâlan wa amtsâlâ", "id": "Jauhilah mencela (orang yang mencintainya); siapa di alam ini yang menyerupainya? Ia telah mengungguli dalam keindahan segala rupa dan bandingan.", "no": 8},
{"ar": "إِنْ جِئْتَ بَانَ النَّقَا أَوْ جِئْتَ مَرْبَعَهُ ۞ فَحُطَّ يَا حَادِيَ الْأَظْعَانِ أَحْمَالًا", "lt": "In ji'ta bânan-naqâ au ji'ta marba‘ahû ۞ faḥuṭṭa yâ ḥâdiyal-azh‘âni aḥmâlâ", "id": "Jika engkau sampai di pohon Ban di bukit Naqa atau sampai di kediamannya, maka turunkanlah beban-beban, wahai penggiring rombongan unta.", "no": 9},
{"ar": "ضَاعَ الزَّمَانُ وَلَمْ أَنْظُرْ مَنَازِلَهُ ۞ وَمَا رَأَيْتُ بِذَاكَ الشِّعْبِ أَطْلَالًا", "lt": "Dlâ‘az-zamânu wa lam anzhur manâzilahû ۞ wa mâ ra'aitu bidzâkasy-syi‘bi aṭlâlâ", "id": "Waktu telah berlalu sia-sia, sementara aku belum melihat tempat tinggalnya, dan belum melihat bekas-bekas rumah di lembah itu.", "no": 10},
{"ar": "ذَنْبِيْ يُقَيِّدُنِيْ وَالصَّدُّ يُقْعِدُنِيْ ۞ وَقَدْ حَمَلْتُ مِنَ الْأَوْزَارِ أَثْقَالًا", "lt": "Dzanbî yuqayyidunî wash-shaddu yuq‘idunî ۞ wa qad ḥamaltu minal-auzâri atsqâlâ", "id": "Dosaku membelengguku dan penghalang membuatku tertahan, sementara aku telah memikul beban-beban dosa yang berat.", "no": 11},
{"ar": "لٰكِنَّنِيْ فِيْ غَدٍ أَرْجُوْهُ يَشْفَعُ لِيْ ۞ وَحُسْنُ ظَنِّيْ بِخَيْرِ الْخَلْقِ مَا زَالَا", "lt": "Lâkinnanî fî ghadin arjûhu yasyfa‘u lî ۞ wa ḥusnu zhannî bikhairil-khalqi mâ zâlâ", "id": "Akan tetapi, esok (di akhirat) aku berharap ia memberiku syafaat; dan baik sangkaku kepada makhluk terbaik tidak pernah sirna.", "no": 12},
{"ar": "وَقَدْ لَجَوْنَا إِلَى بَابِ الْكَرِيْمِ وَمَنْ ۞ يَلْجُوْا إِلَيْهِ يَرَى رُحْبًا وَإِقْبَالًا", "lt": "Wa qad lajaunâ ilâ bâbil-karîmi wa man ۞ yaljû ilaihi yarâ ruḥban wa iqbâlâ", "id": "Kami telah berlindung di pintu Yang Maha Pemurah; siapa yang berlindung kepada-Nya akan mendapati sambutan hangat dan penerimaan.", "no": 13},
{"ar": "بِحَقِّهِ يَا إِلٰهِيْ جُدْ لَنَا كَرَمًا ۞ بِالْعَفْوِ وَالصَّفْحِ إِكْرَامًا وَإِجْلَالًا", "lt": "Biḥaqqihî yâ ilâhî jud lanâ karaman ۞ bil-‘afwi wash-shafḥi ikrâman wa ijlâlâ", "id": "Demi haknya, wahai Tuhanku, anugerahkanlah kepada kami dengan kemurahan-Mu ampunan dan maaf, sebagai pemuliaan dan penghormatan.", "no": 14},
{"ar": "هُوَ النَّبِيُّ الَّذِيْ طَابَ الْوُجُوْدُ بِهِ ۞ وَفِيْهِ خَالَفْتُ لُوَّامًا وَعُذَّالًا", "lt": "Huwan-nabiyyul-ladzî ṭâbal-wujûdu bihî ۞ wa fîhi khâlaftu luwwâman wa ‘udzdzâlâ", "id": "Dialah Nabi yang dengannya alam wujud menjadi harum; dan demi dia aku menentang para pencela dan pengecam.", "no": 15},
{"ar": "صَلَّى عَلَيْهِ إِلٰهُ الْعَرْشِ ثُمَّ عَلَى ۞ آلِهِ وَالصَّحْبِ آبَادًا وَآزَالًا", "lt": "Shallâ ‘alaihi ilâhul-‘arsyi tsumma ‘alâ ۞ âlihî wash-shaḥbi âbâdan wa âzâlâ", "id": "Semoga Tuhan pemilik Arsy melimpahkan shalawat kepadanya, kemudian kepada keluarga dan para sahabatnya, untuk selama-lamanya.", "no": 16},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 17}]},
{judul:"Wa Sammahu Rabbul-'Alamina Muhammadan",isi:[
{"ar": "وَسَمَّاهُ رَبُّ الْعَالَمِيْنَ مُحَمَّدًا ۞ عَلَى وَصْفِهِ الْمَحْمُوْدِ وَهْوَ بِهِ يَدْرِيْ", "lt": "Wa sammâhu rabbul-‘âlamîna muḥammadan ۞ ‘alâ washfihil-maḥmûdi wahwa bihî yadrî", "id": "Tuhan semesta alam menamainya Muhammad sesuai sifatnya yang terpuji, dan Dia Maha Mengetahui tentangnya.", "no": 1},
{"ar": "وَمَا غَسَلَ الْأَمْلَاكُ مِنْ بَطْنِهِ أَذًى ۞ وَلٰكِنَّهُمْ زَادُوْهُ طُهْرًا عَلَى طُهْرِ", "lt": "Wa mâ ghasalal-amlâku min baṭnihî adzan ۞ wa lâkinnahum zâdûhu ṭuhran ‘alâ ṭuhri", "id": "Para malaikat tidaklah membersihkan kotoran dari perutnya, akan tetapi mereka menambahkan kesucian di atas kesuciannya.", "no": 2},
{"ar": "فَهُوَ أَعْظَمُ الْأَنْبِيَاءِ قَدْرًا، وَأَكْبَرُهُمْ هِمَّةً وَفَخْرًا، لَوْلَاهُ مَا خَلَقَ اللهُ مَلَكًا، وَلَا أَدَارَ فَلَكًا، وَلَا أَطْلَعَ بَدْرًا", "lt": "Fahuwa a‘zhamul-anbiyâ'i qadrâ, wa akbaruhum himmatan wa fakhrâ, laulâhu mâ khalaqallâhu malakâ, wa lâ adâra falakâ, wa lâ aṭla‘a badrâ", "id": "Beliau adalah nabi yang paling agung kedudukannya, paling besar cita-cita dan kebanggaannya. Seandainya bukan karena beliau, Allah tidak akan menciptakan malaikat, tidak memutar falak, dan tidak menerbitkan bulan purnama.", "no": 3},
{"ar": "أَسْرَى بِهِ إِلَيْهِ فِي الظَّلَامِ لِيَخُصَّهُ بِنَيْلِ الْمَرَامِ، فَسُبْحَانَ الَّذِيْ أَسْرَى بِهِ لَيْلَةَ الْإِسْرَاءِ، وَخَاطَبَهُ بِلِسَانِ أُنْسِهِ عَلَى بِسَاطِ قُدْسِهِ، فَأَوْحَى إِلَيْهِ مِنْهُ سِرًّا وَجَهْرًا", "lt": "Asrâ bihî ilaihi fizh-zhalâmi liyakhushshahû binailil-marâm, fasubḥânal-ladzî asrâ bihî lailatal-isrâ', wa khâṭabahû bilisâni unsihî ‘alâ bisâṭi qudsih, fa auḥâ ilaihi minhu sirran wa jahrâ", "id": "Allah memperjalankannya kepada-Nya di kegelapan malam untuk mengistimewakannya dengan tercapainya cita-cita. Maha Suci Dzat yang memperjalankannya pada malam Isra, yang berbicara kepadanya dengan bahasa keakraban-Nya di atas hamparan kesucian-Nya, lalu mewahyukan kepadanya secara rahasia dan terang-terangan.", "no": 4},
{"ar": "صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعَلَى آلِهِ وَأَصْحَابِهِ سَادَاتِ الدُّنْيَا وَمُلُوْكِ الْأُخْرَى", "lt": "Shallallâhu ‘alaihi wa sallama wa ‘alâ âlihî wa ashḥâbihî sâdâtid-dunyâ wa mulûkil-ukhrâ", "id": "Semoga Allah melimpahkan shalawat dan salam kepadanya, serta kepada keluarga dan para sahabatnya, para pemimpin di dunia dan para raja di akhirat.", "no": 5}]},
{judul:"Shallal-Ilahu 'alan-Nuril-Ladzi Zhahara",isi:[
{"ar": "مَوْلَايَ صَلِّ وَسَلِّمْ دَائِمًا دَهَرَا ۞ عَلَى الْحَبِيْبِ عَلَا فَوْقَ الْعُلَى وَسَرَى", "lt": "Maulâya shalli wa sallim dâ'iman daharâ ۞ ‘alal-ḥabîbi ‘alâ fauqal-‘ulâ wa sarâ", "id": "Wahai Tuhanku, limpahkanlah shalawat dan salam selamanya sepanjang masa kepada sang kekasih, yang naik melampaui ketinggian dan berjalan di malam hari (Isra).", "no": 1},
{"ar": "صَلَّى الْإِلٰهُ عَلَى النُّوْرِ الَّذِيْ ظَهَرَا ۞ لَنَا بِشَهْرِ رَبِيْعِ الْأَوَّلِ اشْتَهَرَا", "lt": "Shallal-ilâhu ‘alan-nûril-ladzî zhaharâ ۞ lanâ bisyahri rabî‘il-awwalisytaharâ", "id": "Semoga Tuhan melimpahkan shalawat kepada cahaya yang tampak bagi kami dan termasyhur di bulan Rabiul Awal.", "no": 2},
{"ar": "أَضَاءَتِ الْأَرْضُ نُوْرًا يَوْمَ مَوْلِدِهِ ۞ وَأَصْبَحَ الْكَوْنُ مِنْ أَنْفَاسِهِ عَطِرَا", "lt": "Adlâ'atil-ardlu nûran yauma maulidihî ۞ wa ashbaḥal-kaunu min anfâsihî ‘aṭirâ", "id": "Bumi bersinar terang pada hari kelahirannya, dan alam semesta menjadi harum oleh hembusan napasnya.", "no": 3},
{"ar": "هُوَ الَّذِيْ نَارَتِ الدُّنْيَا بِطَلْعَتِهِ ۞ وَسِرُّهُ فِيْ قُلُوْبِ الْعَارِفِيْنَ سَرَى", "lt": "Huwal-ladzî nâratid-dunyâ biṭal‘atihî ۞ wa sirruhû fî qulûbil-‘ârifîna sarâ", "id": "Dialah yang dengan kehadirannya dunia menjadi terang, dan rahasianya mengalir di hati orang-orang arif.", "no": 4},
{"ar": "مِنْ بَطْنِ آمِنَةَ لِلْعَالَمِيْنَ بَدَا ۞ مَوْلُوْدُ حُسْنٍ سَنَاهُ يُخْجِلُ الْقَمَرَا", "lt": "Min baṭni âminata lil-‘âlamîna badâ ۞ maulûdu ḥusnin sanâhu yukhjilul-qamarâ", "id": "Dari rahim Aminah tampak bagi semesta alam bayi yang indah, yang sinarnya membuat rembulan malu.", "no": 5},
{"ar": "جَاءَتْ مَلَائِكَةُ الرَّحْمٰنِ تَشْهَدُهُ ۞ كَيْمَا تُمَتِّعُ مِنْ أَنْوَارِهِ النَّظَرَا", "lt": "Jâ'at malâ'ikatur-raḥmâni tasyhaduhû ۞ kaimâ tumatti‘u min anwârihin-nazharâ", "id": "Para malaikat Ar-Rahman datang menyaksikannya agar dapat menikmati pandangan dari cahaya-cahayanya.", "no": 6},
{"ar": "طَافُوْا بِهِ الْأَرْضَ وَالْأَكْوَانَ أَجْمَعَهَا ۞ لِيَشْهَدَ النَّاسُ سِرًّا كَانَ مُسْتَتِرَا", "lt": "Ṭâfû bihil-ardla wal-akwâna ajma‘ahâ ۞ liyasyhadan-nâsu sirran kâna mustatirâ", "id": "Mereka membawanya berkeliling bumi dan seluruh alam, agar manusia menyaksikan rahasia yang selama ini tersembunyi.", "no": 7},
{"ar": "وَأَخْبَرُوْا أُمَّهُ أَنَّ الَّذِيْ حَمَلَتْ ۞ بِفَخْرِهِ عَزَّ قَدْرُ الْبَيْتِ وَافْتَخَرَا", "lt": "Wa akhbarû ummahû annal-ladzî ḥamalat ۞ bifakhrihî ‘azza qadrul-baiti waftakharâ", "id": "Mereka mengabarkan kepada ibunya bahwa dengan kemuliaan bayi yang dikandungnya, kedudukan Baitullah menjadi mulia dan berbangga.", "no": 8},
{"ar": "هُوَ الَّذِيْ كُلُّ مَنْ فِي الْكَوْنِ يَعْشَقُهُ ۞ وَيَطْرَبُ الصَّبُّ مَعْنَاهُ إِذَا ذُكِرَا", "lt": "Huwal-ladzî kullu man fil-kauni ya‘syaquhû ۞ wa yaṭrabush-shabbu ma‘nâhu idzâ dzukirâ", "id": "Dialah yang dicintai oleh semua yang ada di alam semesta; orang yang rindu menjadi gembira apabila keistimewaannya disebut.", "no": 9},
{"ar": "هٰذَا يَتِيْمٌ فَقِيْرٌ زَانَهُ شَرَفٌ ۞ مِنْ أَجْلِهِ تُكْرَمُ الْأَيْتَامُ وَالْفُقَرَا", "lt": "Hâdzâ yatîmun faqîrun zânahû syarafun ۞ min ajlihî tukramul-aitâmu wal-fuqarâ", "id": "Inilah anak yatim yang papa, dihiasi kemuliaan; karena dialah anak-anak yatim dan orang-orang fakir dimuliakan.", "no": 10},
{"ar": "هٰذَا النَّبِيُّ الَّذِيْ لَوْلَا جَلَالَتُهُ ۞ لَمْ يُخْلَقِ الْخَلْقُ لَا جِنًّا وَلَا بَشَرَا", "lt": "Hâdzan-nabiyyul-ladzî laulâ jalâlatuhû ۞ lam yukhlaqil-khalqu lâ jinnan wa lâ basyarâ", "id": "Inilah Nabi yang seandainya bukan karena keagungannya, makhluk tidak akan diciptakan, baik jin maupun manusia.", "no": 11},
{"ar": "هٰذَا النَّبِيُّ الَّذِيْ مَنْ زَارَ حُجْرَتَهُ ۞ نَالَ الْهَنَا وَالْمُنَى وَالسُّؤْلَ وَالْوَطَرَا", "lt": "Hâdzan-nabiyyul-ladzî man zâra ḥujratahû ۞ nâlal-hanâ wal-munâ was-su'la wal-waṭarâ", "id": "Inilah Nabi yang siapa pun menziarahi kamarnya (makamnya) akan meraih kebahagiaan, cita-cita, permintaan, dan hajatnya.", "no": 12},
{"ar": "صَلَّى عَلَيْهِ إِلٰهُ الْعَرْشِ مَا سَجَعَتْ ۞ حَمَامَةٌ فَوْقَ غُصْنٍ مَائِسٍ سَحَرَا", "lt": "Shallâ ‘alaihi ilâhul-‘arsyi mâ saja‘at ۞ ḥamâmatun fauqa ghushnin mâ'isin saḥarâ", "id": "Semoga Tuhan pemilik Arsy melimpahkan shalawat kepadanya selama burung merpati berkicau di atas dahan yang bergoyang di waktu sahur.", "no": 13},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَزِدْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa zid wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, tambahan (rahmat), dan keberkahan kepadanya.", "no": 14}]},
{judul:"Kisah Tetangga Yahudi di Mesir",isi:[
{"ar": "قَالَ عَبْدُ الْوَاحِدِ بْنُ إِسْمَاعِيْلَ: كَانَ بِمِصْرَ رَجُلٌ يَصْنَعُ مَوْلِدًا لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كُلَّ عَامٍ، وَكَانَ إِلَى جَانِبِهِ رَجُلٌ يَهُوْدِيٌّ", "lt": "Qâla ‘abdul-wâḥidibnu ismâ‘îl: kâna bimishra rajulun yashna‘u maulidan lin-nabiyyi shallallâhu ‘alaihi wa sallama kulla ‘âm, wa kâna ilâ jânibihî rajulun yahûdiyy", "id": "Abdul Wahid bin Ismail berkata: Di Mesir ada seorang laki-laki yang setiap tahun menyelenggarakan peringatan maulid Nabi ﷺ, dan di sebelah rumahnya tinggal seorang laki-laki Yahudi.", "no": 1},
{"ar": "فَقَالَتْ زَوْجَةُ الْيَهُوْدِيِّ: مَا بَالُ جَارِنَا الْمُسْلِمِ يُنْفِقُ مَالًا جَزِيْلًا فِيْ مِثْلِ هٰذَا الشَّهْرِ؟ فَقَالَ لَهَا زَوْجُهَا: إِنَّهُ يَزْعُمُ أَنَّ نَبِيَّهُ وُلِدَ فِيْهِ، وَهُوَ يَفْعَلُ ذٰلِكَ فَرْحَةً بِهِ وَكَرَامَةً لَهُ وَلِمَوْلِدِهِ", "lt": "Faqâlat zaujatul-yahûdiyy: mâ bâlu jârinal-muslimi yunfiqu mâlan jazîlan fî mitsli hâdzasy-syahr? Faqâla lahâ zaujuhâ: innahû yaz‘umu anna nabiyyahû wulida fîh, wa huwa yaf‘alu dzâlika farḥatan bihî wa karâmatan lahû wa limaulidih", "id": "Istri orang Yahudi itu bertanya: Mengapa tetangga kita yang muslim itu membelanjakan harta yang banyak pada bulan seperti ini? Suaminya menjawab: Ia meyakini bahwa nabinya dilahirkan pada bulan ini, dan ia melakukannya karena gembira dengannya serta untuk memuliakan nabinya dan kelahirannya.", "no": 2},
{"ar": "قَالَ: فَسَكَتَا ثُمَّ نَامَا لَيْلَتَهُمَا، فَرَأَتِ امْرَأَةُ الْيَهُوْدِيِّ فِي الْمَنَامِ رَجُلًا جَمِيْلًا جَلِيْلًا عَلَيْهِ مَهَابَةٌ وَتَبْجِيْلٌ وَوَقَارٌ، فَدَخَلَ بَيْتَ جَارِهِ الْمُسْلِمِ، وَحَوْلَهُ جَمَاعَةٌ مِنْ أَصْحَابِهِ وَهُمْ يُبَجِّلُوْنَهُ وَيُعَظِّمُوْنَهُ", "lt": "Qâla: fasakatâ tsumma nâmâ lailatahumâ, fa ra'atimra'atul-yahûdiyyi fil-manâmi rajulan jamîlan jalîlan ‘alaihi mahâbah wa tabjîlun wa waqâr, fadakhala baita jârihil-muslim, wa ḥaulahû jamâ‘atun min ash-ḥâbihî wa hum yubajjilûnahû wa yu‘azhzhimûnah", "id": "Ia berkata: Keduanya pun diam, kemudian tidur pada malam itu. Dalam mimpi, istri orang Yahudi itu melihat seorang laki-laki yang tampan dan agung, penuh kewibawaan, penghormatan, dan ketenangan, masuk ke rumah tetangganya yang muslim; di sekelilingnya ada sekelompok sahabatnya yang memuliakan dan mengagungkannya.", "no": 3},
{"ar": "فَقَالَتْ لِرَجُلٍ مِنْهُمْ: مَنْ هٰذَا الرَّجُلُ الْجَمِيْلُ الْوَجْهِ؟ فَقَالَ لَهَا: هٰذَا رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، دَخَلَ هٰذَا الْمَنْزِلَ لِيُسَلِّمَ عَلَى أَهْلِهِ وَيَزُوْرَهُمْ لِفَرَحِهِمْ بِهِ", "lt": "Faqâlat lirajulin minhum: man hâdzar-rajulul-jamîlul-wajh? Faqâla lahâ: hâdzâ rasûlullâhi shallallâhu ‘alaihi wa sallam, dakhala hâdzal-manzila liyusallima ‘alâ ahlihî wa yazûrahum lifaraḥihim bih", "id": "Ia bertanya kepada salah seorang dari mereka: Siapakah laki-laki yang tampan wajahnya ini? Orang itu menjawab: Ini Rasulullah ﷺ. Beliau memasuki rumah ini untuk mengucapkan salam kepada penghuninya dan mengunjungi mereka karena kegembiraan mereka dengannya.", "no": 4},
{"ar": "فَقَالَتْ لَهُ: هَلْ يُكَلِّمُنِيْ إِذَا كَلَّمْتُهُ؟ قَالَ: نَعَمْ. فَأَتَتْ إِلَيْهِ وَقَالَتْ: يَا مُحَمَّدُ، فَقَالَ لَهَا: لَبَّيْكِ. فَقَالَتْ لَهُ: أَتُجِيْبُ لِمِثْلِيْ بِالتَّلْبِيَةِ وَأَنَا عَلَى غَيْرِ دِيْنِكَ وَمِنْ أَعْدَائِكَ؟", "lt": "Faqâlat lah: hal yukallimunî idzâ kallamtuh? Qâla: na‘am. Fa atat ilaihi wa qâlat: yâ muḥammad, faqâla lahâ: labbaiki. Faqâlat lah: atujîbu limitslî bit-talbiyati wa ana ‘alâ ghairi dînika wa min a‘dâ'ik?", "id": "Ia bertanya kepadanya: Apakah beliau mau berbicara denganku jika aku berbicara kepadanya? Ia menjawab: Ya. Maka ia mendatangi beliau dan berkata: Wahai Muhammad. Beliau menjawab: Labbaiki (aku penuhi panggilanmu). Ia bertanya: Engkau menjawab orang sepertiku dengan talbiyah, padahal aku bukan pemeluk agamamu dan termasuk musuh-musuhmu?", "no": 5},
{"ar": "فَقَالَ لَهَا: وَالَّذِيْ بَعَثَنِيْ بِالْحَقِّ نَبِيًّا، مَا أَجَبْتُ نِدَاءَكِ حَتَّى عَلِمْتُ أَنَّ اللهَ تَعَالَى قَدْ هَدَاكِ", "lt": "Faqâla lahâ: wal-ladzî ba‘atsanî bil-ḥaqqi nabiyyâ, mâ ajabtu nidâ'aki ḥattâ ‘alimtu annallâha ta‘âlâ qad hadâki", "id": "Beliau berkata kepadanya: Demi Dzat yang mengutusku dengan kebenaran sebagai nabi, aku tidak menjawab panggilanmu kecuali setelah aku tahu bahwa Allah Ta'ala telah memberimu hidayah.", "no": 6}]},
{judul:"Ta'alau Bina Nashthalih",isi:[
{"ar": "لَا إِلٰهَ إِلَّا اللهُ ۞ مُحَمَّدٌ رَسُوْلُ اللهِ", "lt": "Lâ ilâha illallâh ۞ muḥammadur-rasûlullâh", "id": "Tiada tuhan selain Allah; Muhammad utusan Allah.", "no": 1},
{"ar": "تَعَالَوْا بِنَا نَصْطَلِحْ ۞ فَبَابُ الرِّضَا قَدْ فُتِحْ", "lt": "Ta‘âlau binâ nashṭaliḥ ۞ fabâbur-ridlâ qad futiḥ", "id": "Marilah bersama kami berdamai (dengan Allah), karena pintu keridaan telah dibuka.", "no": 2},
{"ar": "وَدَاوُوا الْفُؤَادَ الَّذِيْ ۞ بِسَيْفِ الْهَوَى قَدْ جُرِحْ", "lt": "Wa dâwul-fu'âdal-ladzî ۞ bisaifil-hawâ qad juriḥ", "id": "Obatilah hati yang telah terluka oleh pedang cinta.", "no": 3},
{"ar": "أَيَا مُدَّعِيْ حُبِّنَا ۞ دَعِ الرُّوْحَ ثُمَّ اطَّرِحْ", "lt": "Ayâ mudda‘î ḥubbinâ ۞ da‘ir-rûḥa tsummaṭ-ṭariḥ", "id": "Wahai yang mengaku mencintai kami, relakanlah jiwamu, kemudian berserah dirilah.", "no": 4},
{"ar": "تَعَلَّقْ بِأَهْلِ الْهُدَى ۞ وَقُلْ لِلْعَذُوْلِ اسْتَرِحْ", "lt": "Ta‘allaq bi'ahlil-hudâ ۞ wa qul lil-‘adzûlistariḥ", "id": "Bergantunglah kepada ahli petunjuk, dan katakan kepada si pencela: Beristirahatlah (berhentilah mencela).", "no": 5},
{"ar": "وَلِيْ قَلْبٌ مِنْ حُبِّكُمْ ۞ عَلَى بَابِكُمْ مَا بَرِحْ", "lt": "Wa lî qalbun min ḥubbikum ۞ ‘alâ bâbikum mâ bariḥ", "id": "Aku memiliki hati yang, karena cinta kepada kalian, tidak pernah beranjak dari pintu kalian.", "no": 6},
{"ar": "أَلَا يَا نَبِيَّ الْهُدَى ۞ أَغِثْ مَنْ بِذِكْرِكَ يَصِحْ", "lt": "Alâ yâ nabiyyal-hudâ ۞ aghits man bidzikrika yashiḥ", "id": "Wahai Nabi pembawa petunjuk, tolonglah orang yang berseru dengan menyebut namamu.", "no": 7},
{"ar": "أَلَا يَا رَسُوْلَ الْكَرِيْمِ ۞ عَلَيْكَ صَلَاةٌ صَحِيْحْ", "lt": "Alâ yâ rasûlal-karîm ۞ ‘alaika shalâtun shaḥîḥ", "id": "Wahai utusan Tuhan Yang Maha Pemurah, untukmu shalawat yang tulus.", "no": 8},
{"ar": "وَشَوْقِيْ لَكُمْ مَا انْقَضَى ۞ وَحُبِّيْ لَكُمْ مَا بَرِحْ", "lt": "Wa syauqî lakum manqadlâ ۞ wa ḥubbî lakum mâ bariḥ", "id": "Kerinduanku kepada kalian tidak pernah usai, dan cintaku kepada kalian tidak pernah pergi.", "no": 9},
{"ar": "وَكَمْ لَامَنِيْ لَائِمٌ ۞ وَمَا بِسُلُوِّيْ فَرِحْ", "lt": "Wa kam lâmanî lâ'imun ۞ wa mâ bisuluwwî fariḥ", "id": "Betapa sering pencela mencelaku, namun ia tidak pernah bergembira melihatku melupakan (cinta ini).", "no": 10},
{"ar": "أَمَا تَرْحَمُوْا بَاكِيًا ۞ إِذَا ضَحِكَ الْمُنْشَرِحْ", "lt": "Amâ tarḥamû bâkiyan ۞ idzâ dlaḥikal-munsyariḥ", "id": "Tidakkah kalian mengasihi orang yang menangis ketika orang yang lapang hatinya tertawa?", "no": 11},
{"ar": "فَيَا سَعْدَ مَنْ حَبَّكُمْ ۞ فَفِي الْعَاقِبَةْ قَدْ رَبِحْ", "lt": "Fayâ sa‘da man ḥabbakum ۞ fafil-‘âqibah qad rabiḥ", "id": "Betapa bahagia orang yang mencintai kalian; pada akhirnya ia sungguh beruntung.", "no": 12},
{"ar": "تَرَنَّمْ بِذِكْرِ النَّبِيْ ۞ وَغَرِّدْ بِهِ ثُمَّ صِحْ", "lt": "Tarannam bidzikrin-nabî ۞ wa gharrid bihî tsumma shiḥ", "id": "Bersenandunglah dengan menyebut Nabi, berkicaulah dengannya, kemudian berserulah.", "no": 13},
{"ar": "أَلَا يَا نَبِيَّ الْهُدَى ۞ أَغِثْ مَنْ بِذِكْرِكَ يَلِحْ", "lt": "Alâ yâ nabiyyal-hudâ ۞ aghits man bidzikrika yaliḥ", "id": "Wahai Nabi pembawa petunjuk, tolonglah orang yang terus-menerus menyebut namamu.", "no": 14},
{"ar": "وَصَلِّ عَلَى الْمُصْطَفَى ۞ خِتَامِيْ وَمَنْ بِهِ فُتِحْ", "lt": "Wa shalli ‘alal-mushṭafâ ۞ khitâmî wa man bihî futiḥ", "id": "Limpahkanlah shalawat kepada (Nabi) pilihan, sebagai penutup (doa)ku, dan kepada dia yang dengannya (pintu kebaikan) dibuka.", "no": 15},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 16}]},
{judul:"Istri Yahudi Masuk Islam",isi:[
{"ar": "فَقَالَتْ: إِنَّكَ لَنَبِيٌّ كَرِيْمٌ، ﴿وَإِنَّكَ لَعَلٰى خُلُقٍ عَظِيْمٍ﴾، تَعِسَ مَنْ خَالَفَ أَمْرَكَ، وَخَابَ مَنْ جَهِلَ قَدْرَكَ", "lt": "Faqâlat: innaka lanabiyyun karîm, wa innaka la‘alâ khuluqin ‘azhîm, ta‘isa man khâlafa amrak, wa khâba man jahila qadrak", "id": "Ia berkata: Sesungguhnya engkau benar-benar nabi yang mulia, \"dan sesungguhnya engkau benar-benar berbudi pekerti yang agung\" (QS. Al-Qalam: 4). Celakalah orang yang menyelisihi perintahmu dan merugilah orang yang tidak mengenal kedudukanmu.", "no": 1},
{"ar": "اُمْدُدْ يَدَكَ، فَأَنَا أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللهُ، وَأَنَّكَ مُحَمَّدٌ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ", "lt": "Umdud yadak, fa ana asyhadu an lâ ilâha illallâh, wa annaka muḥammadur-rasûlullâhi shallallâhu ‘alaihi wa sallam", "id": "Ulurkanlah tanganmu, aku bersaksi bahwa tiada tuhan selain Allah dan bahwa engkau, Muhammad, adalah utusan Allah ﷺ.", "no": 2},
{"ar": "ثُمَّ إِنَّهَا عَاهَدَتِ اللهَ فِيْ سِرِّهَا أَنَّهَا إِذَا أَصْبَحَتْ تَتَصَدَّقُ بِجَمِيْعِ مَا تَمْلِكُهُ، وَتَصْنَعُ مَوْلِدًا لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرْحَةً بِإِسْلَامِهَا وَشُكْرًا لِلرُّؤْيَا الَّتِيْ رَأَتْهَا فِيْ مَنَامِهَا", "lt": "Tsumma innahâ ‘âhadatillâha fî sirrihâ annahâ idzâ ashbaḥat tatashaddaqu bijamî‘i mâ tamlikuh, wa tashna‘u maulidan lin-nabiyyi shallallâhu ‘alaihi wa sallama farḥatan bi'islâmihâ wa syukran lir-ru'yal-latî ra'at-hâ fî manâmihâ", "id": "Kemudian ia berjanji kepada Allah dalam hatinya bahwa apabila pagi tiba, ia akan menyedekahkan seluruh miliknya dan menyelenggarakan maulid Nabi ﷺ, sebagai ungkapan gembira atas keislamannya dan syukur atas mimpi yang dilihatnya.", "no": 3},
{"ar": "فَلَمَّا أَصْبَحَتْ رَأَتْ زَوْجَهَا قَدْ هَيَّأَ الْوَلِيْمَةَ وَهُوَ فِيْ هِمَّةٍ عَظِيْمَةٍ، فَتَعَجَّبَتْ مِنْ أَمْرِهِ وَقَالَتْ لَهُ: مَا لِيْ أَرَاكَ فِيْ هِمَّةٍ صَالِحَةٍ؟ فَقَالَ لَهَا: مِنْ أَجْلِ الَّذِيْ أَسْلَمْتِ عَلَى يَدَيْهِ الْبَارِحَةَ", "lt": "Falammâ ashbaḥat ra'at zaujahâ qad hayya'al-walîmata wa huwa fî himmatin ‘azhîmah, fata‘ajjabat min amrihî wa qâlat lah: mâ lî arâka fî himmatin shâliḥah? Faqâla lahâ: min ajlil-ladzî aslamti ‘alâ yadaihil-bâriḥah", "id": "Ketika pagi tiba, ia melihat suaminya telah menyiapkan jamuan dengan semangat yang besar. Ia heran dengan keadaannya dan bertanya: Mengapa aku melihatmu bersemangat dalam kebaikan? Suaminya menjawab: Demi dia yang di tangannya engkau masuk Islam semalam.", "no": 4},
{"ar": "فَقَالَتْ لَهُ: مَنْ كَشَفَ لَكَ عَنْ هٰذَا السِّرِّ الْمَصُوْنِ، وَمَنْ أَطْلَعَكَ عَلَيْهِ؟ فَقَالَ لَهَا: الَّذِيْ أَسْلَمْتُ بَعْدَكِ عَلَى يَدَيْهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، كَمَا عَرَّفَ بِاللهِ وَدَعَا إِلَيْهِ، فَهُوَ الْمُشَفَّعُ غَدًا فِيْمَنْ يُصَلِّيْ وَيُسَلِّمُ عَلَيْهِ", "lt": "Faqâlat lah: man kasyafa laka ‘an hâdzas-sirril-mashûn, wa man aṭla‘aka ‘alaih? Faqâla lahâ: al-ladzî aslamtu ba‘daki ‘alâ yadaihi shallallâhu ‘alaihi wa sallam, kamâ ‘arrafa billâhi wa da‘â ilaih, fahuwal-musyaffa‘u ghadan fî man yushallî wa yusallimu ‘alaih", "id": "Ia bertanya: Siapa yang menyingkapkan kepadamu rahasia yang tersimpan ini, dan siapa yang memberitahumu tentangnya? Suaminya menjawab: Dia yang di tangannya aku masuk Islam setelahmu ﷺ, sebagaimana beliau memperkenalkan Allah dan menyeru kepada-Nya. Beliaulah yang syafaatnya diterima kelak bagi orang yang bershalawat dan bersalam kepadanya.", "no": 5}]},
{judul:"Habibun Yugharul-Badru",isi:[
{"ar": "صَلَاةٌ وَتَسْلِيْمٌ وَأَزْكَى تَحِيَّةٍ ۞ عَلَى الْمُصْطَفَى الْمُخْتَارِ خَيْرِ الْبَرِيَّاتِ", "lt": "Shalâtun wa taslîmun wa azkâ taḥiyyatin ۞ ‘alal-mushṭafal-mukhtâri khairil-bariyyâti", "id": "Shalawat, salam, dan penghormatan yang paling suci semoga tercurah kepada (Nabi) pilihan yang terpilih, makhluk terbaik.", "no": 1},
{"ar": "حَبِيْبٌ يُغَارُ الْبَدْرُ مِنْ حُسْنِ وَجْهِهِ ۞ تَحَيَّرَتِ الْأَفْكَارُ فِيْ وَصْفِ مَعْنَاهُ", "lt": "Ḥabîbun yughârul-badru min ḥusni wajhihî ۞ taḥayyaratil-afkâru fî washfi ma‘nâhu", "id": "Seorang kekasih yang keindahan wajahnya membuat bulan purnama cemburu; pikiran bingung dalam melukiskan hakikatnya.", "no": 2},
{"ar": "حَبِيْبٌ تَجَلَّى لِلْقُلُوْبِ مُخَاطِبًا ۞ فَطَابُوْا بِهِ شُكْرًا وَفِيْ حُسْنِهِ تَاهُوْا", "lt": "Ḥabîbun tajallâ lil-qulûbi mukhâṭiban ۞ faṭâbû bihî syukran wa fî ḥusnihî tâhû", "id": "Seorang kekasih yang tampak bagi hati-hati seraya menyapa, maka mereka berbahagia dan bersyukur karenanya, dan terpesona oleh keindahannya.", "no": 3},
{"ar": "مَلِيْحٌ حَوَى كُلَّ الْقُلُوْبِ لِحُسْنِهِ ۞ فَرَاحَتْ وَرَاحَ الْقَلْبُ مِنْ بَعْضِ إِسْرَاهُ", "lt": "Malîḥun ḥawâ kullal-qulûbi liḥusnihî ۞ farâḥat wa râḥal-qalbu min ba‘dli isrâhu", "id": "Seorang rupawan yang menguasai semua hati dengan keindahannya; maka hati-hati itu pergi, dan hatiku pun pergi menjadi bagian dari tawanannya.", "no": 4},
{"ar": "رَضِيْتُ بِهِ مَوْلًى عَلَى كُلِّ حَالَةٍ ۞ فَقُلْ لِبَعِيْدِ الدَّارِ دَعْنِيْ وَإِيَّاهُ", "lt": "Radlîtu bihî maulan ‘alâ kulli ḥâlatin ۞ faqul liba‘îdid-dâri da‘nî wa iyyâhu", "id": "Aku rela dia menjadi pemimpinku dalam segala keadaan; maka katakanlah kepada orang yang jauh rumahnya: Biarkan aku bersamanya.", "no": 5},
{"ar": "يُوَاصِلُنِيْ طَوْرًا وَطَوْرًا يَصُدُّنِيْ ۞ وَهَا أَنَا رَاضٍ بِالَّذِيْ هُوَ يَهْوَاهُ", "lt": "Yuwâshilunî ṭauran wa ṭauran yashuddunî ۞ wa hâ ana râdlin bil-ladzî huwa yahwâhu", "id": "Kadang ia mendekatiku, kadang menjauhiku; dan aku rela dengan apa pun yang ia kehendaki.", "no": 6},
{"ar": "فَلَوْلَاهُ مَا طَابَ الْهَوَى لِمُتَيَّمٍ ۞ وَلَوْلَاهُ مَا حَنَّ الْحُدَاةُ لِحَاجِزٍ", "lt": "Falaulâhu mâ ṭâbal-hawâ limutayyamin ۞ wa laulâhu mâ ḥannal-ḥudâtu liḥâjizin", "id": "Kalau bukan karena dia, cinta tidak akan terasa indah bagi orang yang dimabuk cinta; kalau bukan karena dia, para penggiring unta tidak akan rindu kepada Hajiz,", "no": 7},
{"ar": "وَلَا اسْتَنْشَقَ الْعُشَّاقُ يَوْمًا خُزَامَاهُ", "lt": "Wa lastansyaqal-‘usysyâqu yauman khuzâmâhu", "id": "dan para pecinta tidak akan pernah menghirup harumnya bunga khuzama tempatnya.", "no": 8},
{"ar": "صَلَاةٌ وَتَسْلِيْمٌ عَلَى خَيْرِ مُرْسَلٍ ۞ مُحَمَّدٍ الدَّاعِيْ إِلَى سُبُلِ أَهْدَاهُ", "lt": "Shalâtun wa taslîmun ‘alâ khairi mursalin ۞ muḥammadinid-dâ‘î ilâ subuli ahdâhu", "id": "Shalawat dan salam semoga tercurah kepada rasul terbaik, Muhammad, penyeru menuju jalan-jalan yang paling lurus.", "no": 9}]},
{judul:"Fi Hubbi Sayyidina Muhammad",isi:[
{"ar": "اَللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ ۞ يَا رَبِّ صَلِّ عَلَيْهِ وَسَلِّمْ", "lt": "Allâhumma shalli ‘alâ muḥammad ۞ yâ rabbi shalli ‘alaihi wa sallim", "id": "Ya Allah, limpahkanlah shalawat kepada Muhammad; wahai Tuhanku, limpahkanlah shalawat dan salam kepadanya.", "no": 1},
{"ar": "فِيْ حُبِّ سَيِّدِنَا مُحَمَّدٍ ۞ نُوْرٌ لِبَدْرِ الْهُدَى مُتَمِّمْ", "lt": "Fî ḥubbi sayyidinâ muḥammadin ۞ nûrun libadril-hudâ mutammim", "id": "Dalam cinta kepada junjungan kita Muhammad ada cahaya yang menyempurnakan purnama petunjuk.", "no": 2},
{"ar": "قَلْبِيْ يَحِنُّ إِلَى مُحَمَّدٍ ۞ مَا زَالَ مِنْ وَجْدِهِ مُتَيَّمْ", "lt": "Qalbî yaḥinnu ilâ muḥammadin ۞ mâ zâla min wajdihî mutayyam", "id": "Hatiku rindu kepada Muhammad, senantiasa dimabuk cinta karena kerinduannya.", "no": 3},
{"ar": "مَا لِيْ حَبِيْبٌ سِوَى مُحَمَّدٍ ۞ خَيْرِ الرَّسُوْلِ النَّبِيِّ الْمُكَرَّمِ", "lt": "Mâ lî ḥabîbun siwâ muḥammadin ۞ khairir-rasûlin-nabiyyil-mukarram", "id": "Aku tidak memiliki kekasih selain Muhammad, rasul terbaik, nabi yang dimuliakan.", "no": 4},
{"ar": "شَوْقُ الْمُحِبِّ إِلَى مُحَمَّدٍ ۞ أَفْنَاهُ ثُمَّ بِهِ تَهَيَّمَ", "lt": "Syauqul-muḥibbi ilâ muḥammadin ۞ afnâhu tsumma bihî tahayyam", "id": "Kerinduan sang pecinta kepada Muhammad telah meleburkannya, lalu ia dimabuk cinta kepadanya.", "no": 5},
{"ar": "فِي الْحَشْرِ شَافِعُنَا مُحَمَّدٌ ۞ مُنْجِي الْخَلَائِقِ مِنْ جَهَنَّمَ", "lt": "Fil-ḥasyri syâfi‘unâ muḥammadun ۞ munjil-khalâ'iqi min jahannam", "id": "Di padang mahsyar, pemberi syafaat kami adalah Muhammad, penyelamat makhluk dari neraka Jahanam.", "no": 6},
{"ar": "مِيْلَادُ سَيِّدِنَا مُحَمَّدٍ ۞ أُمُّ الْقُرَى بَلَدٌ مُعَظَّمُ", "lt": "Mîlâdu sayyidinâ muḥammadin ۞ ummul-qurâ baladun mu‘azhzham", "id": "Tempat kelahiran junjungan kita Muhammad adalah Ummul Qura (Makkah), negeri yang diagungkan.", "no": 7},
{"ar": "أَحْيَا الدُّجَى زَمَنًا مُحَمَّدٌ ۞ مَوْلَاهُ سَلَّمَهُ وَكَلَّمَ", "lt": "Aḥyad-dujâ zamanan muḥammadun ۞ maulâhu sallamahû wa kallam", "id": "Muhammad menghidupkan malam-malam yang gelap (dengan ibadah) dalam waktu yang lama; Tuhannya memberinya salam dan berbicara kepadanya.", "no": 8},
{"ar": "أَدْعُوْكَ أَحْمَدُ يَا مُحَمَّدُ ۞ يَا سَيِّدَ الرُّسُلِ الْمُقَدَّمِ", "lt": "Ad‘ûka aḥmadu yâ muḥammadu ۞ yâ sayyidar-rusulil-muqaddam", "id": "Aku memanggilmu, wahai Ahmad, wahai Muhammad, wahai pemimpin para rasul yang dikedepankan.", "no": 9},
{"ar": "اِشْفَعْ إِلَى اللهِ يَا مُحَمَّدُ ۞ يَوْمَ الْقِيَامَةِ كَيْ أُنَعَّمَ", "lt": "Isyfa‘ ilallâhi yâ muḥammadu ۞ yaumal-qiyâmati kai una‘‘am", "id": "Berilah syafaat (untukku) kepada Allah, wahai Muhammad, pada hari kiamat agar aku mendapat kenikmatan.", "no": 10},
{"ar": "أَرْجُو الشَّفَاعَةَ مِنْ مُحَمَّدٍ ۞ لَوْ كُنْتُ أَرْتَكِبُ الْمُحَرَّمَ", "lt": "Arjusy-syafâ‘ata min muḥammadin ۞ lau kuntu artakibul-muḥarram", "id": "Aku mengharapkan syafaat dari Muhammad, sekalipun aku pernah melakukan yang diharamkan.", "no": 11},
{"ar": "مَنْجَى وَمَلْجَؤُنَا مُحَمَّدٌ ۞ يَوْمَ الْهَوَانِ بِهَا تَحَشَّمَ", "lt": "Manjâ wa malja'unâ muḥammadun ۞ yaumal-hawâni bihâ taḥasysyam", "id": "Tempat keselamatan dan perlindungan kami adalah Muhammad, pada hari kehinaan ketika (manusia) dalam kesempitan.", "no": 12},
{"ar": "وَالنُّوْرُ جَاءَ بِهِ مُحَمَّدٌ ۞ وَالْحَقُّ بَيَّنَ إِنْ تَكَلَّمَ", "lt": "Wan-nûru jâ'a bihî muḥammadun ۞ wal-ḥaqqu bayyana in takallam", "id": "Cahaya (petunjuk) dibawa oleh Muhammad, dan kebenaran menjadi jelas apabila ia berbicara.", "no": 13},
{"ar": "أَعْلَى السَّمَاءِ سَمَا مُحَمَّدٌ ۞ جِبْرِيْلُ قَالَ لَهُ تَقَدَّمَ", "lt": "A‘las-samâ'i samâ muḥammadun ۞ jibrîlu qâla lahû taqaddam", "id": "Muhammad naik ke langit yang paling tinggi; Jibril berkata kepadanya: Majulah.", "no": 14},
{"ar": "وَالْجُنْدُ حِيْنَ غَزَا مُحَمَّدٌ ۞ مِنْهُمْ مَلَائِكَةٌ تَسَوَّمُ", "lt": "Wal-jundu ḥîna ghazâ muḥammadun ۞ minhum malâ'ikatun tasawwam", "id": "Ketika Muhammad berperang, di antara pasukannya ada malaikat-malaikat yang bertanda.", "no": 15},
{"ar": "وَالدِّيْنَ أَظْهَرَهُ مُحَمَّدٌ ۞ وَالْكُفْرَ أَبْطَلَهُ فَهَدَّمَ", "lt": "Wad-dîna azhharahû muḥammadun ۞ wal-kufra abṭalahû fahaddam", "id": "Agama (Islam) dimenangkan oleh Muhammad, dan kekufuran ia batalkan lalu ia runtuhkan.", "no": 16},
{"ar": "صَلَّى الْإِلٰهُ عَلَى مُحَمَّدٍ ۞ وَالْآلِ كُلِّهِمِ وَسَلَّمَ", "lt": "Shallal-ilâhu ‘alâ muḥammadin ۞ wal-âli kullihimi wa sallam", "id": "Semoga Tuhan melimpahkan shalawat kepada Muhammad dan seluruh keluarganya, serta melimpahkan salam.", "no": 17},
{"ar": "وَصَلَّى اللهُ عَلَى مُحَمَّدٍ ۞ وَعَلَى صَحْبِهِ وَسَلَّمَ", "lt": "Wa shallallâhu ‘alâ muḥammadin ۞ wa ‘alâ shaḥbihî wa sallam", "id": "Semoga Allah melimpahkan shalawat kepada Muhammad dan kepada para sahabatnya, serta melimpahkan salam.", "no": 18},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 19}]},
{judul:"Doa Penutup",isi:[
{"ar": "صَدَقَ اللهُ الْعَلِيُّ الْعَظِيْمُ، وَبَلَّغَ رَسُوْلُهُ الْحَبِيْبُ الْكَرِيْمُ، وَنَحْنُ عَلَى ذٰلِكَ مِنَ الشَّاهِدِيْنَ، وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ", "lt": "Shadaqallâhul-‘aliyyul-‘azhîm, wa ballagha rasûluhul-ḥabîbul-karîm, wa naḥnu ‘alâ dzâlika minasy-syâhidîn, wal-ḥamdu lillâhi rabbil-‘âlamîn", "id": "Maha Benar Allah Yang Maha Tinggi lagi Maha Agung, dan Rasul-Nya, sang kekasih yang mulia, telah menyampaikan (risalah-Nya); kami termasuk orang-orang yang menyaksikan hal itu. Segala puji bagi Allah, Tuhan semesta alam.", "no": 1},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي الْأَوَّلِيْنَ، وَصَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي الْآخِرِيْنَ، وَصَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي النَّبِيِّيْنَ، وَصَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي الْمُرْسَلِيْنَ", "lt": "Allâhumma shalli wa sallim ‘alâ sayyidinâ muḥammadin fil-awwalîn, wa shalli wa sallim ‘alâ sayyidinâ muḥammadin fil-âkhirîn, wa shalli wa sallim ‘alâ sayyidinâ muḥammadin fin-nabiyyîn, wa shalli wa sallim ‘alâ sayyidinâ muḥammadin fil-mursalîn", "id": "Ya Allah, limpahkanlah shalawat dan salam kepada junjungan kami Muhammad di kalangan orang-orang terdahulu, di kalangan orang-orang terkemudian, di kalangan para nabi, dan di kalangan para rasul.", "no": 2},
{"ar": "وَصَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ فِيْ كُلِّ وَقْتٍ وَحِيْنٍ، وَصَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ فِي الْمَلَإِ الْأَعْلَى إِلَى يَوْمِ الدِّيْنِ", "lt": "Wa shalli wa sallim ‘alâ sayyidinâ muḥammadin fî kulli waqtin wa ḥîn, wa shalli wa sallim ‘alâ sayyidinâ muḥammadin fil-mala'il-a‘lâ ilâ yaumid-dîn", "id": "Limpahkanlah shalawat dan salam kepada junjungan kami Muhammad di setiap waktu dan saat, dan limpahkanlah shalawat dan salam kepada junjungan kami Muhammad di kalangan para malaikat yang tinggi hingga hari pembalasan.", "no": 3},
{"ar": "اَلسَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، اَلسَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللهِ الصَّالِحِيْنَ", "lt": "As-salâmu ‘alaika ayyuhan-nabiyyu wa raḥmatullâhi wa barakâtuh, as-salâmu ‘alainâ wa ‘alâ ‘ibâdillâhish-shâliḥîn", "id": "Salam sejahtera untukmu, wahai Nabi, beserta rahmat Allah dan keberkahan-Nya. Salam sejahtera untuk kami dan untuk hamba-hamba Allah yang saleh.", "no": 4},
{"ar": "اَللّٰهُمَّ بَلِّغْ رُوْحَ سَيِّدِنَا مُحَمَّدٍ مِنَّا تَحِيَّةً وَسَلَامًا، وَاجْزِهِ عَنَّا أَفْضَلَ مَا جَزَيْتَ نَبِيًّا عَنْ أُمَّتِهِ، وَآتِهِ الْوَسِيْلَةَ وَالْفَضِيْلَةَ وَالشَّرَفَ وَالدَّرَجَةَ الْعَالِيَةَ الرَّفِيْعَةَ، وَابْعَثْهُ الْمَقَامَ الْمَحْمُوْدَ الَّذِيْ وَعَدْتَهُ يَا أَرْحَمَ الرَّاحِمِيْنَ", "lt": "Allâhumma balligh rûḥa sayyidinâ muḥammadin minnâ taḥiyyatan wa salâmâ, wajzihî ‘annâ afdlala mâ jazaita nabiyyan ‘an ummatih, wa âtihil-wasîlata wal-fadlîlata wasy-syarafa wad-darajatal-‘âliyatar-rafî‘ah, wab‘atshul-maqâmal-maḥmûdal-ladzî wa‘adtahû yâ arḥamar-râḥimîn", "id": "Ya Allah, sampaikanlah kepada ruh junjungan kami Muhammad penghormatan dan salam dari kami. Balaslah beliau atas jasanya kepada kami dengan balasan terbaik yang pernah Engkau berikan kepada seorang nabi atas jasanya kepada umatnya. Berikanlah kepadanya wasilah, keutamaan, kemuliaan, dan derajat yang tinggi lagi luhur, dan bangkitkanlah ia di kedudukan terpuji yang telah Engkau janjikan kepadanya, wahai Yang Maha Penyayang di antara para penyayang.", "no": 5},
{"ar": "اَللّٰهُمَّ اجْعَلْنَا وَإِيَّاهُمْ مِمَّنْ يَسْتَوْجِبُ شَفَاعَتَهُ، وَيَرْتَجِيْ بِهِ مِنَ اللهِ رَحْمَتَهُ، وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ", "lt": "Allâhummaj‘alnâ wa iyyâhum mimman yastaujibu syafâ‘atah, wa yartajî bihî minallâhi raḥmatah, wal-ḥamdu lillâhi rabbil-‘âlamîn", "id": "Ya Allah, jadikanlah kami dan mereka termasuk orang-orang yang berhak mendapatkan syafaatnya dan yang mengharapkan rahmat Allah melaluinya. Segala puji bagi Allah, Tuhan semesta alam.", "no": 6},
{"ar": "اَللّٰهُمَّ بِحُرْمَةِ هٰذَا النَّبِيِّ الْكَرِيْمِ، وَآلِهِ وَأَصْحَابِهِ السَّالِكِيْنَ لِنَهْجِهِ الْقَوِيْمِ، اجْعَلْنَا مِنْ خِيَارِ أُمَّتِهِ، وَاسْتُرْنَا بِذَيْلِ حُرْمَتِهِ، وَاحْشُرْنَا غَدًا فِيْ زُمْرَتِهِ، وَاسْتَعْمِلْ أَلْسِنَتَنَا فِيْ مَدْحِهِ وَنُصْرَتِهِ، وَأَحْيِنَا مُسْتَمْسِكِيْنَ بِطَاعَتِهِ وَمَحَبَّتِهِ، وَأَمِتْنَا عَلَى سُنَّتِهِ وَجَمَاعَتِهِ", "lt": "Allâhumma biḥurmati hâdzan-nabiyyil-karîm, wa âlihî wa ashḥâbihis-sâlikîna linahjihil-qawîm, ij‘alnâ min khiyâri ummatih, wasturnâ bidzaili ḥurmatih, waḥsyurnâ ghadan fî zumratih, wasta‘mil alsinatanâ fî madḥihî wa nushratih, wa aḥyinâ mustamsikîna biṭâ‘atihî wa maḥabbatih, wa amitnâ ‘alâ sunnatihî wa jamâ‘atih", "id": "Ya Allah, dengan kehormatan Nabi yang mulia ini, serta keluarga dan para sahabatnya yang menempuh jalannya yang lurus, jadikanlah kami umatnya yang terbaik, tutupilah kami dengan ujung kehormatannya, kumpulkanlah kami kelak dalam rombongannya, gunakanlah lisan kami untuk memuji dan membelanya, hidupkanlah kami dalam keadaan berpegang teguh pada ketaatan dan kecintaan kepadanya, dan wafatkanlah kami di atas sunnah dan jamaahnya.", "no": 7},
{"ar": "اَللّٰهُمَّ أَدْخِلْنَا مَعَهُ الْجَنَّةَ فَإِنَّهُ أَوَّلُ مَنْ يَدْخُلُهَا، وَأَنْزِلْنَا مَعَهُ فِيْ قُصُوْرِهَا فَإِنَّهُ أَوَّلُ مَنْ يَنْزِلُهَا، وَارْحَمْنَا بِهِ يَوْمَ يَسْتَشْفِعُ بِهِ الْخَلَائِقُ فَتَرْحَمُهَا", "lt": "Allâhumma adkhilnâ ma‘ahul-jannata fa innahû awwalu man yadkhuluhâ, wa anzilnâ ma‘ahû fî qushûrihâ fa innahû awwalu man yanziluhâ, warḥamnâ bihî yauma yastasyfi‘u bihil-khalâ'iqu fatarḥamuhâ", "id": "Ya Allah, masukkanlah kami ke surga bersamanya, karena dialah yang pertama memasukinya; tempatkanlah kami bersamanya di istana-istananya, karena dialah yang pertama menempatinya; dan rahmatilah kami dengan perantaraannya pada hari ketika seluruh makhluk memohon syafaat melaluinya lalu Engkau merahmati mereka.", "no": 8},
{"ar": "اَللّٰهُمَّ إِنَّا قَدْ حَضَرْنَا قِرَاءَةَ مَوْلِدِ نَبِيِّكَ الْكَرِيْمِ، فَأَفِضْ عَلَيْنَا بِبَرَكَتِهِ لِبَاسَ الْعِزِّ وَالتَّكْرِيْمِ، وَأَسْكِنَّا بِجِوَارِهِ فِيْ دَارِ النَّعِيْمِ، وَنَعِّمْنَا فِي الْجَنَّةِ بِالنَّعِيْمِ الْمُقِيْمِ", "lt": "Allâhumma innâ qad ḥadlarnâ qirâ'ata maulidi nabiyyikal-karîm, fa afidl ‘alainâ bibarakatihî libâsal-‘izzi wat-takrîm, wa askinnâ bijiwârihî fî dârin-na‘îm, wa na‘‘imnâ fil-jannati bin-na‘îmil-muqîm", "id": "Ya Allah, kami telah menghadiri pembacaan maulid Nabi-Mu yang mulia, maka limpahkanlah kepada kami, berkat keberkahannya, pakaian kemuliaan dan kehormatan; tempatkanlah kami di sampingnya di negeri kenikmatan; dan berilah kami kenikmatan di surga dengan kenikmatan yang kekal.", "no": 9},
{"ar": "اَللّٰهُمَّ إِنَّا نَسْأَلُكَ بِجَاهِ هٰذَا النَّبِيِّ الْمُصْطَفَى، وَآلِهِ أَهْلِ الصِّدْقِ وَالْوَفَا، كُنْ لَنَا مُعِيْنًا وَمُسْعِفًا، وَبَوِّئْنَا مِنَ الْجَنَّةِ غُرَفًا، وَارْزُقْنَا بِجَاهِهِ عِنْدَكَ قَبُوْلًا وَعِزًّا وَشَرَفًا", "lt": "Allâhumma innâ nas'aluka bijâhi hâdzan-nabiyyil-mushṭafâ, wa âlihî ahlish-shidqi wal-wafâ, kun lanâ mu‘înan wa mus‘ifâ, wa bawwi'nâ minal-jannati ghurafâ, warzuqnâ bijâhihî ‘indaka qabûlan wa ‘izzan wa syarafâ", "id": "Ya Allah, kami memohon kepada-Mu dengan kedudukan Nabi pilihan ini dan keluarganya, ahli kejujuran dan kesetiaan: jadilah penolong dan pembantu kami, tempatkanlah kami di kamar-kamar surga, dan anugerahkanlah kepada kami, dengan kedudukannya di sisi-Mu, penerimaan, kemuliaan, dan kehormatan.", "no": 10},
{"ar": "اَللّٰهُمَّ إِنَّا نَتَوَسَّلُ إِلَيْكَ بِنَبِيِّكَ الْمُخْتَارِ، وَآلِهِ الْأَطْهَارِ، وَأَصْحَابِهِ الْأَخْيَارِ، كَفِّرْ عَنَّا الذُّنُوْبَ وَالْأَوْزَارَ، يَا اللهُ يَا اللهُ يَا اللهُ، وَاحْرُسْنَا مِنْ جَمِيْعِ الْمَخَاوِفِ وَالْأَخْطَارِ", "lt": "Allâhumma innâ natawassalu ilaika binabiyyikal-mukhtâr, wa âlihil-aṭhâr, wa ashḥâbihil-akhyâr, kaffir ‘annadz-dzunûba wal-auzâr, yâ allâh yâ allâh yâ allâh, waḥrusnâ min jamî‘il-makhâwifi wal-akhṭâr", "id": "Ya Allah, kami bertawasul kepada-Mu dengan Nabi-Mu yang terpilih, keluarganya yang suci, dan para sahabatnya yang terbaik: hapuskanlah dari kami dosa-dosa dan beban-beban kesalahan, ya Allah, ya Allah, ya Allah, dan jagalah kami dari segala yang menakutkan dan membahayakan.", "no": 11},
{"ar": "وَاجْمَعْ بَيْنَنَا وَبَيْنَهُ فِيْ دَارِ الْقَرَارِ، وَتَقَبَّلْ مِنَّا مَا قَدَّمْنَا مِنْ يَسِيْرِ أَعْمَالِنَا فِي الْإِعْلَانِ وَالْإِسْرَارِ، وَارْحَمْنَا بِرَحْمَتِكَ وَاغْفِرْ لَنَا، إِنَّكَ أَنْتَ الْعَفُوُّ الْغَفَّارُ يَا غَفَّارُ", "lt": "Wajma‘ bainanâ wa bainahû fî dâril-qarâr, wa taqabbal minnâ mâ qaddamnâ min yasîri a‘mâlinâ fil-i‘lâni wal-isrâr, warḥamnâ biraḥmatika waghfir lanâ, innaka antal-‘afuwwul-ghaffâru yâ ghaffâr", "id": "Kumpulkanlah kami bersamanya di negeri yang kekal, terimalah dari kami amal-amal kecil yang telah kami lakukan secara terang-terangan maupun tersembunyi, rahmatilah kami dengan rahmat-Mu dan ampunilah kami. Sesungguhnya Engkau Maha Pemaaf lagi Maha Pengampun, wahai Yang Maha Pengampun.", "no": 12},
{"ar": "إِلٰهِيْ تَمِّمِ النَّعْمَاءَ عَلَيْنَا ۞ وَوَفِّقْنَا لِشُكْرِكَ مَا بَقِيْنَا", "lt": "Ilâhî tammimin-na‘mâ'a ‘alainâ ۞ wa waffiqnâ lisyukrika mâ baqînâ", "id": "Tuhanku, sempurnakanlah nikmat-nikmat atas kami, dan berilah kami taufik untuk bersyukur kepada-Mu selama kami hidup.", "no": 13},
{"ar": "أَذِقْنَا بَرْدَ عَفْوِكَ وَالْعَوَافِيْ ۞ وَهَوِّنْ كُلَّ مَطْلُوْبٍ عَلَيْنَا", "lt": "Adziqnâ barda ‘afwika wal-‘awâfî ۞ wa hawwin kulla maṭlûbin ‘alainâ", "id": "Rasakanlah kepada kami sejuknya ampunan-Mu dan kesehatan, serta mudahkanlah bagi kami setiap hal yang kami cari.", "no": 14},
{"ar": "فَإِنَّا لَا نُعَوِّلُ فِيْ مُهِمٍّ ۞ أَلَمَّ بِنَا وَلَا مَا قَدْ لَقِيْنَا", "lt": "Fa innâ lâ nu‘awwilu fî muhimmin ۞ alamma binâ wa lâ mâ qad laqînâ", "id": "Sesungguhnya kami tidak bergantung, dalam urusan penting yang menimpa kami maupun yang telah kami alami,", "no": 15},
{"ar": "عَلَى أَحَدٍ وَلَا سَبَبٍ وَلٰكِنْ ۞ إِذَا ضَاقَتْ وَكُنْتَ لَهَا كَمِيْنَا", "lt": "‘Alâ aḥadin wa lâ sababin wa lâkin ۞ idzâ dlâqat wa kunta lahâ kamînâ", "id": "kepada seorang pun atau kepada sebab apa pun; akan tetapi, apabila urusan menjadi sempit, Engkaulah yang tersembunyi (menyiapkan jalan keluar) baginya.", "no": 16},
{"ar": "وَصَلِّ عَلَى رَسُوْلِكَ كُلَّ حِيْنٍ ۞ مُحَمَّدٍ النَّبِيِّ الزَّاكِي الْأَمِيْنَا", "lt": "Wa shalli ‘alâ rasûlika kulla ḥînin ۞ muḥammadinin-nabiyyiz-zâkil-amînâ", "id": "Limpahkanlah shalawat setiap saat kepada Rasul-Mu, Muhammad, Nabi yang suci lagi terpercaya,", "no": 17},
{"ar": "كَذَا آلٍ وَأَصْحَابٍ كِرَامٍ ۞ وَمَنْ وَالَاهُمُ وَالتَّابِعِيْنَا", "lt": "Kadzâ âlin wa ashḥâbin kirâmin ۞ wa man wâlâhumu wat-tâbi‘înâ", "id": "demikian pula kepada keluarga dan para sahabat yang mulia, kepada orang-orang yang mencintai mereka, dan kepada para tabi'in.", "no": 18},
{"ar": "يَا إِلٰهِيْ بِحَقِّهِ ۞ دَمِّرِ الْبَغْيَ وَالْفَسَادَ", "lt": "Yâ ilâhî biḥaqqihî ۞ dammiril-baghya wal-fasâd", "id": "Wahai Tuhanku, demi haknya, hancurkanlah kezaliman dan kerusakan.", "no": 19},
{"ar": "يَا إِلٰهِيْ بِحَقِّهِ ۞ جُدْ بِلُطْفِكَ يَا جَوَادُ", "lt": "Yâ ilâhî biḥaqqihî ۞ jud biluṭfika yâ jawâd", "id": "Wahai Tuhanku, demi haknya, limpahkanlah kelembutan-Mu, wahai Yang Maha Dermawan.", "no": 20},
{"ar": "يَا إِلٰهِيْ بِحَقِّهِ ۞ آتِنَا السُّؤْلَ وَالْمُرَادَ", "lt": "Yâ ilâhî biḥaqqihî ۞ âtinas-su'la wal-murâd", "id": "Wahai Tuhanku, demi haknya, berikanlah kepada kami permintaan dan keinginan kami.", "no": 21},
{"ar": "حَصَلَ الْقَصْدُ وَالْمُرَادُ ۞ وَصَفَا الْوَقْتُ وَالْوِدَادُ", "lt": "Ḥashalal-qashdu wal-murâdu ۞ wa shafal-waqtu wal-widâd", "id": "Tujuan dan keinginan telah tercapai, waktu dan kasih sayang pun menjadi jernih.", "no": 22},
{"ar": "وَبِرُؤْيَا مُحَمَّدٍ ۞ فَرِحَتْ أَنْفُسُ الْعِبَادِ", "lt": "Wa biru'yâ muḥammadin ۞ fariḥat anfusul-‘ibâd", "id": "Dengan melihat Muhammad, jiwa-jiwa para hamba bergembira.", "no": 23},
{"ar": "عَنْ غَرَامِيْ وَلَوْعَتِيْ ۞ لَا تُحَرِّكْ فِي الْمَلَامِ", "lt": "‘An gharâmî wa lau‘atî ۞ lâ tuḥarrik fil-malâm", "id": "Tentang cinta dan kerinduanku yang membara, janganlah engkau mengungkitnya dengan celaan.", "no": 24},
{"ar": "ذَاكَ دِيْنِيْ وَمِلَّتِيْ ۞ ذَاكَ لِيْ غَايَةُ الْمُرَامِ", "lt": "Dzâka dînî wa millatî ۞ dzâka lî ghâyatul-murâm", "id": "Itulah agama dan jalan hidupku; itulah puncak cita-citaku.", "no": 25},
{"ar": "مِحْنَتِيْ فِيْهِ لَذَّتِيْ ۞ صَلْوَتِيْ لِلْهَوَى الْحَرَمْ", "lt": "Miḥnatî fîhi ladzdzatî ۞ shalwatî lil-hawal-ḥaram", "id": "Ujianku dalam (mencintai)nya adalah kenikmatanku, dan pelipur laraku adalah cinta kepada Tanah Haram.", "no": 26},
{"ar": "مَا فُتِنَ أَحَدٌ كَفِتْنَتِيْ ۞ فَيَسُدُّوْنِيْ بِلَا كَلَامِ", "lt": "Mâ futina aḥadun kafitnatî ۞ fayasuddûnî bilâ kalâm", "id": "Tidak ada seorang pun yang terpikat seperti keterpikatanku, maka mereka membuatku terdiam tanpa kata.", "no": 27},
{"ar": "وَصَلَّى اللهُ عَلَى خَيْرِ خَلْقِهِ مُحَمَّدٍ وَآلِهِ وَأَصْحَابِهِ أَجْمَعِيْنَ، وَسَلَّمَ تَسْلِيْمًا كَثِيْرًا، وَاخْتِمْ لَنَا مِنْكَ بِخَيْرٍ بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِيْنَ", "lt": "Wa shallallâhu ‘alâ khairi khalqihî muḥammadin wa âlihî wa ashḥâbihî ajma‘în, wa sallama taslîman katsîrâ, wakhtim lanâ minka bikhairin biraḥmatika yâ arḥamar-râḥimîn", "id": "Semoga Allah melimpahkan shalawat kepada makhluk-Nya yang terbaik, Muhammad, serta seluruh keluarga dan sahabatnya, dan melimpahkan salam yang banyak. Akhirilah hidup kami dengan kebaikan dari-Mu, dengan rahmat-Mu, wahai Yang Maha Penyayang di antara para penyayang.", "no": 28},
{"ar": "صَلَّى اللهُ رَبُّنَا عَلَى النُّوْرِ الْمُبِيْنِ، أَحْمَدَ الْمُصْطَفَى سَيِّدِ الْمُرْسَلِيْنَ، وَعَلَى آلِهِ وَصَحْبِهِ أَجْمَعِيْنَ (3x)", "lt": "Shallallâhu rabbunâ ‘alan-nûril-mubîn, aḥmadal-mushṭafâ sayyidil-mursalîn, wa ‘alâ âlihî wa shaḥbihî ajma‘în (3x)", "id": "Semoga Allah, Tuhan kami, melimpahkan shalawat kepada cahaya yang nyata, Ahmad yang terpilih, pemimpin para rasul, serta kepada seluruh keluarga dan sahabatnya. (dibaca 3 kali)", "no": 29},
{"ar": "﴿سُبْحٰنَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُوْنَ ۝ وَسَلٰمٌ عَلَى الْمُرْسَلِيْنَ ۝ وَالْحَمْدُ لِلّٰهِ رَبِّ الْعٰلَمِيْنَ﴾ آمِيْنَ", "lt": "Subḥâna rabbika rabbil-‘izzati ‘ammâ yashifûn, wa salâmun ‘alal-mursalîn, wal-ḥamdu lillâhi rabbil-‘âlamîn. Âmîn", "id": "Maha Suci Tuhanmu, Tuhan Yang Maha Perkasa, dari apa yang mereka sifatkan. Salam sejahtera bagi para rasul. Segala puji bagi Allah, Tuhan semesta alam (QS. Ash-Shaffat: 180-182). Amin.", "no": 30}]}]});
